REPLACE INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
	(2, 'ruRU', 'Да, могучий |3-6($C), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.', 0),
	(6, 'ruRU', 'Ты $Gнашел:нашла; шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?', 0),
	(7, 'ruRU', 'Ну, $gдобыл:добыла; мне банданы?', 0),
	(10, 'ruRU', 'Ну, что тебе удалось узнать? Похоже, ты только что из боя... Жив ли Холстомер?', 0),
	(11, 'ruRU', 'Приветствую, $N. Ну, как идет война с гноллами?', 0),
	(12, 'ruRU', 'Быть может, я недостаточно ясно выразился? Прошу прощения. Чтобы доказать, что ты $gдостоин:достойна; вступить в ряды народного ополчения и служить Свету, ты $gдолжен:должна; убить 15 звероловов и 15 контрабандистов из Братства Справедливости и вернуться ко мне, когда это будет сделано.', 0),
	(15, 'ruRU', 'Ты $gбыл:была; в руднике? $gГотов:Готова; доложить об успехах?', 0),
	(16, 'ruRU', 'Работа фермера тяжела, от нее здорово пересыхает в глотке.$B$BЕсли ты дашь мне родниковой воды, могу предложить кое-что взамен.', 0),
	(17, 'ruRU', 'Ты принес грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!', 0),
	(18, 'ruRU', 'Ну, $Gдобыл:добыла; мне банданы?', 0),
	(19, 'ruRU', 'Орки Черной горы по-прежнему не дают нам покоя. Избавь нас хотя бы от Тарил\'зуна!', 0),
	(20, 'ruRU', 'Ты уже охотился на орков, $N? Если так, покажи мне...', 0),
	(21, 'ruRU', 'Я знаю, это поганая работа, $N, но ее необходимо выполнить ради безопасности Североземья. Ты $gготов:готова; предоставить отчет?', 0),
	(23, 'ruRU', 'Ах – $N – я только что подумала о тебе! Ну, как прошла охота?', 0),
	(24, 'ruRU', 'Еще раз привествую тебя, $N! Ты пришел показать мне свои охотничьи трофеи?', 0),
	(25, 'ruRU', 'Торопись, $N. Они должны получить указания, это срочно.', 0),
	(32, 'ruRU', 'Прости, мы не знакомы... Но судя по всему, тебе приходилось слышать обо мне. Чем могу помочь? Ты мне что-то принес?', 0),
	(33, 'ruRU', 'Здравствуй, $N! Как идет охота на зараженных зверей?', 0),
	(36, 'ruRU', 'Я буду очень скучать по Верне Хмуробров... Скажи-ка, ты не $gвстретил:встретила; ее по пути сюда?', 0),
	(47, 'ruRU', 'Эй! Ну как, есть Золотая пыль... пыль?', 0),
	(48, 'ruRU', 'И-ик! Хо-хо! Хочешь выступление на бис?$B$BГде-то в южных краях, там, где вьется лоза\nЕсть колодец с водой, что чиста как слеза.\nБьет священной воды одинокий ручей,\nБудь же другом, скорей, отправляйся за ней!', 0),
	(54, 'ruRU', 'У тебя сообщение от маршала Макбрайда? Североземье по сравнению с Элвиннским лесом - мирный сад, но мне любопытно, о чем пишет Макбрайд.$B$BДайте-ка мне бумаги...', 0),
	(55, 'ruRU', 'Неужели Морбент Скверн повержен?!', 0),
	(60, 'ruRU', 'Ну как, ты уже $gраздобыл:раздобыла; свечи?', 0),
	(61, 'ruRU', 'О, да это посылка от моего братца! Вот это здорово! Определенно, сегодня мой счастливый день!', 0),
	(62, 'ruRU', 'Ну что, $N, как насчет доклада? Что там происходит, в этом руднике?', 0),
	(64, 'ruRU', 'Боюсь, тебе так и не удалось достать мои часы?', 0),
	(68, 'ruRU', 'А, я тебя помню. Это ты спрашивал насчет Сталвана. Удалось его отыскать?', 0),
	(70, 'ruRU', 'Что это у тебя? Дай-ка посмотреть...', 0),
	(74, 'ruRU', 'Что это у тебя? Не вижу. Зрение стало совсем никудышное. Дай-ка страницу сюда.', 0),
	(75, 'ruRU', 'Ну что, нашел страницу, о которой я говорил?', 0),
	(78, 'ruRU', 'Тебя послал маршал Хаггард? Что ж ты молчишь?$B$BЭх, старина Хаггард. Бедняга скоро совсем ослепнет. Впрочем, давай, покажи, что там у тебя.', 0),
	(79, 'ruRU', 'Надеюсь, ты ко мне не по пустякам пришел, $C. Но, во имя Света, говори быстрее. Для меня превыше всего безопасность Темнолесья, и терять время впустую я не намерена.', 0),
	(80, 'ruRU', 'И снова ты здесь, $N. Что на этот раз?', 0),
	(82, 'ruRU', 'Ты ведь младший геодезист, да? Говори скорее, ситуация серьезная! Ты $Gпринёс:принесла; мне части тел насекомых, обещанные Рудознатцем?!', 0),
	(87, 'ruRU', 'О, $N? Привет, привет... Ну что, нашлось мое ожерелье?', 0),
	(89, 'ruRU', 'Мост сам собой не строится! Где железные пики и железные клепки?', 0),
	(90, 'ruRU', 'Ты принес 10 постных волчьих боков? А травяную приправу от Фелисии из Штормграда?', 0),
	(91, 'ruRU', 'Принеси мне 10 подвесок Темношкуров и получишь награду.', 0),
	(92, 'ruRU', 'Мне все еще нужны пять кусков жесткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса.', 0),
	(93, 'ruRU', 'Привет тебе, $N. Ну как, удалось добыть липкие паучьи лапки?', 0),
	(94, 'ruRU', 'Статуя льва уже не одно десятилетие несет свою одинокую стражу у печально знаменитой башни Илгалара.$B$BУ подножия статуи есть углубление, куда можно вложить драгоценный камень или амулет...', 0),
	(99, 'ruRU', 'Тебе удалось собрать для меня кандалы из деревни Погребальных Костров, $N?', 0),
	(101, 'ruRU', 'Принеси мне 10 клыков вурдалаков, 10 пальцев скелетов и 5 фиалов паучьего яда, и я создам тотем Кары, который будет наносить урон тем, кто попытается напасть на тебя.', 0),
	(102, 'ruRU', 'Набрал ли ты уже 8 лап с тех вероломных гноллов?', 0),
	(103, 'ruRU', 'Огонь вскоре погаснет, если не будет масла, $N.', 0),
	(104, 'ruRU', 'Ну как, вам еще не удалось справиться с угрозой по имени Старый Мрачноглаз? Его видели носящимся вдоль береговой линии Западного Края.$b$bВозвращайтесь ко мне, когда злобная тварь будет мертва.', 0),
	(113, 'ruRU', 'Ну как, младший геодезист $N, старина Пестычинс подготовил отчет?', 0),
	(115, 'ruRU', 'Как успехи с чародеями? Где полуночные сферы?', 0),
	(116, 'ruRU', 'Принеси мне бочонок светлого громопойла от Бухаря Громопойла из Западного Края, бочонок "Мерло" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу.', 0),
	(117, 'ruRU', 'Торопись, мой друг, и иди побыстрей,$bЧтоб нашего пойла отведать скорей.$bОно ближе к пиву - не спутаешь с кашей,$bНо нужен нам хмель, чтоб сварить пойло наше.', 0),
	(118, 'ruRU', 'Что такое? Говоришь, Вернер тебя послал? Давай сюда его письмо. И ГОВОРИ ГРОМЧЕ!', 0),
	(119, 'ruRU', 'О, да ты $Gвернулся:вернулась;! Удалось достать подковы?', 0),
	(120, 'ruRU', 'С чем $Gпришел:пришла;?', 0),
	(121, 'ruRU', 'Новости от генерала? Когда прибудут подкрепления?', 0),
	(122, 'ruRU', 'Если я не отдам чешую жадине Аргусу, он пошлет за ней кого-нибудь другого. Ты уже добыл материал?', 0),
	(123, 'ruRU', 'Что?! Да никто из наших в Элвиннских шахтах уже несколько месяцев не работает!$B$BДай-ка сюда эту бумажку...', 0),
	(124, 'ruRU', 'Лошади по-прежнему нервничают, а по ночам все еще доносится проклятый волчий вой. Прошу тебя, $N, сделай что-нибудь с этими гноллами!', 0),
	(125, 'ruRU', 'Удалось вытащить инструменты?', 0),
	(126, 'ruRU', 'Изувой – опасное существо, $N. Если ты еще не $Gготов:готова; сразиться с ним, я тебя понимаю.', 0),
	(127, 'ruRU', 'Ну как, где моя рыба-луна?', 0),
	(133, 'ruRU', 'Кажется, я слышу за домом шаги вурдалаков – надо поскорее сделать фигурку! Ты принес мне ребра вурдалаков?', 0),
	(134, 'ruRU', 'Ты принес мой ящик? Коли так, пожалуйста... Быстро дай его сюда!', 0),
	(143, 'ruRU', 'Привет тебе, |3-6($c). Какое дело привело тебя к народному ополчению?', 0),
	(144, 'ruRU', 'Скоро ли ждать прибытия народного ополчения? Добрые ли вести ты несешь от лорда Камнегрива?', 0),
	(145, 'ruRU', 'Похоже, ты $gприбыл:прибыла; издалека, |3-6($c). Что привело тебя в Темнолесье?', 0),
	(146, 'ruRU', 'Рад снова видеть тебя, $Gпосланник:посланница;. Могу ли я сообщить маршалу, что Ночная стража уже в пути?', 0),
	(147, 'ruRU', 'Тебе удалось разыскать Вымогателя? И на кого же он работает?', 0),
	(149, 'ruRU', 'Всхлипывает. Пожалуйста, не смотри на меня! Я вырвала глаза собственными руками, но все равно чувствую твой взгляд!$B$BЯ уродина! Уродина! Прошу тебя, отвернись!', 0),
	(150, 'ruRU', 'Принес плавники? Торопись, надо скорее изгнать мурлоков из нашего озера!', 0),
	(151, 'ruRU', 'Старая Савраска уже валится с ног. Не $gдобыл:добыла; ли ты овса для нее?', 0),
	(152, 'ruRU', 'Убей 7 волноловов, 7 воинов, 7 оракулов и 7 береговиков-мурлоков, – и награда будет ждать тебя.', 0),
	(153, 'ruRU', 'Принесите мне 15 красных кожаных бандан, и я вам хорошо заплачу.', 0),
	(154, 'ruRU', 'Чувствую, ты уже видел Слепую Мэри. Гребень все еще у тебя?..', 0),
	(156, 'ruRU', 'Привет. Ну как, принес цветки гнили?', 0),
	(157, 'ruRU', 'Я должен обвязать нитью из призрачных волос двери и окна, чтобы не пускать в дом чуждых призраков. Ты принес ее?', 0),
	(159, 'ruRU', 'Сок зомби согреет меня долгими холодными ночами. Ты принес его?', 0),
	(160, 'ruRU', 'Аберкромби?.. Я не знаю такого человека. Так говоришь, этот Аберкромби написал мне письмо?$B$BЧто ж, давай его сюда...', 0),
	(161, 'ruRU', 'Что ты там бубнишь, $gсынок:дочка;? В ушах звенит, аж жуть. Ух ты, что это ты мне $gпринес:принесла;?', 0),
	(162, 'ruRU', 'Да пребудут с тобой мир и покой, $Gнезнакомец:незнакомка;. Зачем ты $Gискал:искала; меня?', 0),
	(164, 'ruRU', 'С первого взгляда ты кажешься опытным бойцом, $C. Хочешь пополнить наши ряды?', 0),
	(167, 'ruRU', 'Нет ли у тебя каких-либо известий о моем брате? Можно ли еще надеяться, ведь столько времени прошло?', 0),
	(168, 'ruRU', 'Принеси мне карточки Союза шахтеров, которые принадлежали моим друзьям...', 0),
	(169, 'ruRU', 'Что это, |3-6($r)?', 0),
	(171, 'ruRU', 'Мне очень приятно видеть тебя снова, $N. Ты добровольцем принимал участие в Детской Неделе.', 0),
	(174, 'ruRU', 'Тебе удалось отыскать искусного инженера и сделать бронзовую трубку?', 0),
	(176, 'ruRU', 'О да, этот Дробитель мне и моим людям немало крови попортил... Ты можешь о нем что-нибудь сообщить?', 0),
	(177, 'ruRU', 'Я показал Когу наш прибор для изучения звезд, и он его одобрил. Ты не добыл отражающее устройство?', 0),
	(178, 'ruRU', 'Говоришь, ты $gслышал:слышала; мой голос из подвески? Хм-м-м... Дай-ка ее мне, надо ее как следует изучить.', 0),
	(179, 'ruRU', 'Что, потрепали тебя волки? Да уж, когти и клыки – это тебе не шуточки!', 0),
	(180, 'ruRU', 'Какие новости ты несешь Суду?', 0),
	(181, 'ruRU', 'Тебе удалось уговорить Ззарк\'Вула одолжить нам свой монокль для эксперимента?', 0),
	(184, 'ruRU', 'У тебя бумага на мою ферму? Вот это да! Вот это здорово! Несколько дней назад ее украли какие-то мерзавцы... Я думал, назад мне ее уже не получить.$B$BПожалуйста, отдай мне эту бумагу. Конечно, мы сейчас уезжаем из Западного Края и вернемся не скоро, но наступят времена, когда она нам очень пригодится...', 0),
	(186, 'ruRU', 'Если ты жаждешь великих свершений, докажи сначала, что способен на малые. Убей 10 тигров Тернистой долины и возвращайся.', 0),
	(187, 'ruRU', 'Добрые ли вести ты несешь?', 0),
	(188, 'ruRU', 'Как идет охота на Син\'Далл?', 0),
	(189, 'ruRU', 'Ну как, надеюсь, успешно? Проклятые тролли кишмя кишат! Грязные твари.\n\nКстати, мое предложение и на твоих друзей распространяется! Тебе не помешает помощь!', 0),
	(190, 'ruRU', 'Подлинный охотник думает лишь о добыче. А ты, друг мой, все больше о болтовне у костра. Иди, убей 10 ящеров-кнутохвостов, пока я не отправился и не перестрелял всех ящеров в джунглях за один заход.', 0),
	(191, 'ruRU', 'Иди, убей 10 пантер! Покажи, на что способен.', 0),
	(192, 'ruRU', 'Что ты здесь делаешь, $N! Ты $Gдолжен:должна; ползти сквозь кусты, пытаясь убить 10 тенебрюхих пантер. Я думал, что ты отнесёшься к этому делу серьёзнее.', 0),
	(193, 'ruRU', 'Баг\'тира – хитрый зверь. Как идет охота?', 0),
	(194, 'ruRU', 'Мне не доводилось встречать охотников, которые добывали дичь, попусту ошиваясь у костра – конечно, не считая моего отца. Ты собираешься подстрелить этих ящеров или будешь ждать, когда они умрут от старости?', 0),
	(195, 'ruRU', 'Добрые ли вести ты несешь?', 0),
	(196, 'ruRU', 'Ба! Что ты здесь делаешь? Настоящий охотник никогда не сдается, пока в поле зрения есть дичь. Не думаю, что тропические ловцы сами прибегут сюда и бросятся в костер. $GГлупый:Глупая; $Gмальчик:девочка;.', 0),
	(197, 'ruRU', 'Как идет охота на Тетис? Я так понимаю, ее следы вели к нашему лагерю?', 0),
	(198, 'ruRU', 'Да? Что тебе нужно? А, припасы гоблинов. Странно, что их доставил $C, обычно они сами этим занимаются. Не важно... Ты ведь их не касался? Славно, славно... Мы бы не хотели, чтобы с нашими минами что-нибудь случилось, о нет.', 0),
	(199, 'ruRU', 'Ну как, $gнашел:нашла; улики?', 0),
	(201, 'ruRU', 'Ну что, $N, тебе удалось обнаружить лагерь охотников?', 0),
	(202, 'ruRU', 'Смею ли я надеяться, что Курцен и его защитники мертвы, $N?', 0),
	(203, 'ruRU', 'Надеюсь, охота оказалась успешной, $N. Нам не продержаться без твоей помощи.', 0),
	(204, 'ruRU', 'Я жду – не дождусь зелий и экстракта, $N.', 0),
	(205, 'ruRU', 'Ты $Gпринёс:принесла; фетиши, $N? Должно быть, именно в них заключается секрет падения Курцена... Мне нужно это узнать!', 0),
	(206, 'ruRU', 'Да пребудет с тобой мое благословение. Сила Май\'Зота сравнима лишь с чернотой его души.', 0),
	(207, 'ruRU', '$N! У тебя есть прорисовки тролльских табличек? Я должен раскрыть их тайны!', 0),
	(208, 'ruRU', 'Вижу, ты вернулся, старина. Мне не раз приходилось заползать в лагерь и зализывать раны после столкновения с королем Бангалашем. Побудь здесь.', 0),
	(209, 'ruRU', 'Сильные, заразы, а? Ну, как успехи? Не хочу показаться нетерпеливым, но это мне покою не дает. Так как?', 0),
	(211, 'ruRU', 'Тебе было дано задание, $N. Ты $Gпринёс:принесла; мне кристалл лича в доказательство его выполнения?', 0),
	(213, 'ruRU', 'Мне нужны эти камни, $N. Любой ценой! Подробности мне не нужны, только результат, ни больше, ни меньше.', 0),
	(216, 'ruRU', 'О, привет еще раз, $N. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя в форт?', 0),
	(217, 'ruRU', 'Громаг и его охранники, Скрежетун и Буян, все еще живы. Задание не выполнено, покуда все трое живы. Все дворфы рассчитывают на тебя, $N.', 0),
	(218, 'ruRU', 'А, $N! Ну, как дела?', 0),
	(223, 'ruRU', 'Да, что тебе нужно? Быстрее, у меня полно неотложных дел.', 0),
	(224, 'ruRU', 'Лок Модан в осаде, $N! Все сторонники Альянса, способные держать оружие, должны нам помочь. Ты уже $Gубил:убила; 10  троггов из племени Камнедробов и 10 разведчиков из племени Камнедробов?', 0),
	(228, 'ruRU', 'Я не буду винить тебя, если тебе не удастся справиться с ним, $N. Мор\'Ладим отнял жизни у сильнейших из наших воинов.', 0),
	(230, 'ruRU', 'Что ты нашел?! Пожалуйста, дай посмотреть...', 0),
	(231, 'ruRU', 'Оставь меня в покое...', 0),
	(232, 'ruRU', 'Да, чем могу помочь? Ты здесь по приказу Королевского фармацевтического общества или же просто поговорить пришел?', 0),
	(233, 'ruRU', 'А? Что? Для меня что-то есть?', 0),
	(234, 'ruRU', 'Могу ли я тебе чем-нибудь помочь?', 0),
	(235, 'ruRU', 'Совет Приливов проявляет нетерпение. Они желают положить конец войне, которая вот уже не одну эпоху идет во всех измерениях. Мои собратья жаждут услышать новости о грандиозной победе над ненавистными элементалями огня. Где же огненные кристаллы, что так нужны мне?', 0),
	(237, 'ruRU', 'Мы должны выиграть время, |3-6($r). Тебе приказано убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов. Не ослабляй натиск на врага, пока не подойдут подкрепления. Сейчас не время сидеть сложа руки.', 0),
	(238, 'ruRU', 'Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.\n\nТы ведь принес его?', 0),
	(240, 'ruRU', '$N, ты уже здесь! А где моя еда?!', 0),
	(248, 'ruRU', 'Когда-то в этом кувшине был какой-то смрадный напиток, но теперь пустой сосуд лежит, забытый, на паре бочек.', 0),
	(249, 'ruRU', 'Торопись, $N, пока не сбылись мои опасения и темное влияние Морганта не расползлось по всей стране.', 0),
	(251, 'ruRU', 'Значит, это записка от отшельника Аберкромби? Я с ним не знаком, но если он живет на кладбище, то мозг у него – трухлявый, как старый пень!', 0),
	(252, 'ruRU', 'А, так записку перевели? Дай-ка взглянуть...', 0),
	(253, 'ruRU', 'Тебе удалось найти могилу Элизы? А достать сердце Бальзамировщика?', 0),
	(255, 'ruRU', 'Как дела?', 0),
	(256, 'ruRU', 'Да? Чем я могу вам помочь?', 0),
	(257, 'ruRU', 'Не вышло? Не расстраивайся, $Gбедненький:бедняжка; $n…$b$bНе всем же быть такими, как я.', 0),
	(258, 'ruRU', 'Вполне простительно пожалеть себя, если тебе утер нос кто-то столь же юный, как я. Не расстраивайся, $n...$b$bКстати, это у тебя имя такое или кличка?', 0),
	(262, 'ruRU', 'Если у тебя есть что-нибудь из вещей того незнакомца, которого ты разыскиваешь, покажи это мне. Может быть, я смогу понять, кто ее владелец.', 0),
	(263, 'ruRU', 'Уже $gвернулся:вернулась;? На всякий случай повторяю: я просил убить 10 шаманов из племени Камнедробов и 10 костегрызов из племени Камнедробов, $N. В атаку, Гроза троггов!', 0),
	(264, 'ruRU', 'Каменная плита холодна на ощупь. Могила была осквернена: вокруг валяется мусор, барельеф на плите исцарапан, из него выбиты куски, надгробье зарастает травой.\n\nНикому нет дела до погребенного здесь, особенно если это жертва поветрия.', 0),
	(265, 'ruRU', 'Иногда я продаю чистые тетради ученым и магам, а также тем, что хочет вести дневник.$B$BЯ помню всех покупателей за последние несколько месяцев...', 0),
	(266, 'ruRU', 'Хотя "Алый Ворон" процветает не так, как раньше, путники гостят здесь и в наши дни.$B$BЕсли ты опишешь того, кого ищешь, может быть, я его вспомню.', 0),
	(267, 'ruRU', 'Ты $gпринес:принесла; мне 8 каменных зубов троггов? Если нет, тебе есть чем заняться, $N.', 0),
	(268, 'ruRU', 'Тебе удалось выяснить, что это за незнакомец?', 0),
	(269, 'ruRU', 'Отдохни пока, брат. Я вижу, у тебя позади долгий путь, и на тебя возложена тяжкая ноша. Скажи, что за тень пала на тебя?', 0),
	(271, 'ruRU', 'А, $n! Уже $gвернулся:вернулась;? Опять $gохотился:охотилась;? Не огорчайся, если тебя постигнет неудача. Неудачи заставляют нас работать над собой!$b$bВ любом случае тебе повезет больше, чем некоторым...', 0),
	(274, 'ruRU', 'Что ты $gпринес:принесла; от Аслана?', 0),
	(276, 'ruRU', 'Ты еще не $Gвыполнил:выполнила; мое задание, |3-6($c).', 0),
	(277, 'ruRU', 'Ты принес эти проклятые камни для высекания огня?', 0),
	(278, 'ruRU', 'Ты $gпринес:принесла; все необходимое? Торопись!', 0),
	(279, 'ruRU', 'Наши купцы смогут почувствовать себя в безопасности, только когда мы избавимся от Жруна и его сородичей.', 0),
	(280, 'ruRU', 'Крышка бочки медленно отвинчивается.', 0),
	(282, 'ruRU', 'Приветствую! Я тебе вот что скажу, $N: ты в тоннеле Дун Морога будь поосторожнее, там полно троггов, так что дорога небезопасна.\n\nЯ тебе даже больше скажу: если у тебя нет неотложных дел в Дун Мороге, оставайся-ка лучше в Старой Наковальне, пока в тоннеле не станет поспокойнее.', 0),
	(286, 'ruRU', 'Ты принес статуэтку?', 0),
	(287, 'ruRU', 'Ты не $gсмог:смогла; найти Форт? Но я же дал четкие указания! У нас мало времени, поторопись! Не возвращайся, пока не найдешь пещеры.', 0),
	(288, 'ruRU', 'Трубы горят, сил нет! Добрый господин, не купишь бедному забулдыге чего-нибудь горячительного? Умираю!', 0),
	(289, 'ruRU', 'Мне снятся кошмары, в которых я слышу, как наяву, стоны моих обреченных собратьев! Заклинаю тебя, добрый сэр, освободи их от этого ужаса. Пусть их стоны и вопли умолкнут навечно.', 0),
	(290, 'ruRU', 'Сейф заперт надежно.', 0),
	(291, 'ruRU', 'Хм... похоже, мои охранники потеряли хватку и пропускают ко мне кого попало. Ладно, что тебе надо? Говори быстрее.', 0),
	(292, 'ruRU', 'Тебя послал этот пропойца Фитсиммонс? Так скажи ему, что эль у меня закончился! Нечего ему разорять мои запасы.', 0),
	(293, 'ruRU', 'Что это у тебя? Какой-то запачканный шар...', 0),
	(294, 'ruRU', 'Убей 10 крапчатых ящеров и 10 крапчатых крикунов, $N. Мои погибшие товарищи не заслужили своей горькой участи. Пора свести счеты.', 0),
	(295, 'ruRU', 'Крапчатые смертехваты и крапчатые острозубы должны заплатить за все, что они с нами сделали. Ты уже $Gубил:убила; по десятку этих мерзавцев?', 0),
	(296, 'ruRU', 'Зарлозуб мертв? Ты $gотомстил:отомстила; за смерть наших братьев?', 0),
	(297, 'ruRU', 'И где же идолы? Надо хорошенько изучить их и сообщить о результатах в Стальгорн!', 0),
	(298, 'ruRU', 'О, отчет о ходе работ на раскопе? Превосходно!', 0),
	(299, 'ruRU', 'Ты нашел недостающие фрагменты, $N? Адос, Модр, Голм и Неру...', 0),
	(301, 'ruRU', 'Представители моего клана терпеть не могут, когда нас беспокоят по пустякам, |3-6($c). Надеюсь, твои вести стоят моего драгоценного внимания.', 0),
	(304, 'ruRU', 'Ты нашел Балгараса, $C? Сколько раз мы пытались его разыскать, но все тщетно.', 0),
	(306, 'ruRU', 'Ты сумел разыскать Меррин? Она просила мне что-нибудь передать?', 0),
	(307, 'ruRU', 'Ну как, $gпринес:принесла; инструменты?', 0),
	(308, 'ruRU', 'Ох! Сколько же тут выпивки, а у меня строгий приказ ничего не трогать. Мне бы хоть попробовать нашего громового эля... Я от него лучше соображаю, честное слово!', 0),
	(309, 'ruRU', 'Где мой порох, $n? Он мне все нужнее и нужнее.', 0),
	(310, 'ruRU', 'Дата на бочонке показывает, что скоро его откроют.', 0),
	(311, 'ruRU', 'Ну что, подмена удалась?', 0),
	(312, 'ruRU', 'Тебе удалось заглянуть в мой мясной ларь, $n?', 0),
	(313, 'ruRU', 'Эй, $N! Ну что, $Gпобывал:побывала; в Серой берлоге? Эти вендиго – злющие тварюги.', 0),
	(314, 'ruRU', 'Вагаш по-прежнему режет наше стадо! Пожалуйста, помоги убить эту мерзкую тварь!', 0),
	(315, 'ruRU', 'Ты $Gдобыл:добыла; звездолист? Я уже приготовился сварить партию портера и хочу попробовать бросить в сусло эту травку.', 0),
	(317, 'ruRU', 'Подготовка идет отлично. Как охота?', 0),
	(319, 'ruRU', 'Ну, $Gрасправился:расправилась; со зверьем?', 0),
	(320, 'ruRU', 'Ну, $Gпривез:привезла; "Вечное сияние"?', 0),
	(322, 'ruRU', 'Ты пришел по какому-то делу, $C?', 0),
	(324, 'ruRU', 'Ты уже собрал достаточно светлостали?', 0),
	(325, 'ruRU', 'Привет, $N. Вроде недавно виделись, но с тех пор в тебе что-то решительно изменилось!', 0),
	(332, 'ruRU', 'Приветствую и добро пожаловать, $gмсье:мадам;! Не желаете ли отведать наших знаменитых вин?', 0),
	(335, 'ruRU', 'Вишлок скоро наберет достаточно сил, чтобы доставить нам кучу неприятностей. Ты уже раздобыл слезу Тиллоа и мускусный корень?', 0),
	(336, 'ruRU', 'Ты что, не видишь, как я занят? Я готовлю речь! Я значу очень много для будущего этой державы!$B$BО, а что это у тебя? Похоже на освежающий напиток...', 0),
	(337, 'ruRU', 'О-о-о! Что это у вас за книга? Можно взглянуть?', 0),
	(338, 'ruRU', 'Тебе удалось собрать все главы, $N?', 0),
	(339, 'ruRU', 'Тебе не удалось найти страницы 1, 4, 6 и 8? Именно их не хватает, чтобы собрать воедино главу I.', 0),
	(340, 'ruRU', 'Нам по-прежнему не хватает 10, 11, 14 и 16 страниц второй главы, $N.', 0),
	(341, 'ruRU', 'Ну как, где страницы 18, 20, 21 и 24? Стоит их найти, и третья глава будет собрана.', 0),
	(342, 'ruRU', 'Нам не хватает всего лишь трех страниц главы IV. Ты $Gпринёс:принесла; страницы 25, 26 и 27?', 0),
	(346, 'ruRU', 'Тебе удалось найти книгу?', 0),
	(347, 'ruRU', 'Как там моя ретбанская руда?', 0),
	(348, 'ruRU', '...мама?$B$B…так холодно…$B$B...отправляюсь в Круговерть Пустоты... Об-бними меня, мама...', 0),
	(349, 'ruRU', 'Знахарь Унбагва знать что есть Мокк Дикарь. Да, да!$B$BМоя говорить с духами, и он приходи.$B$BНо другие гориллы-звери тоже любят, когда духи говорят. Охрани знахаря Унбагва, и моя позвать его.$B$BЗнахарь Унбагва кое-что хотеть сначала. Твоя принеси клык гориллы, и моя начинать говорить с духи!', 0),
	(351, 'ruRU', 'Похоже, вы нашли обломки... механического цыпленка? Из яйца снова доносится голос:$B$B"Да, отличная работа! Это в самом деле мой автономный робот, хотя судя по сенсорам, он нуждается в хорошей починке перед перелетом в Пиратскую бухту. Для начала поместите маяк внутрь аппарата. А остальное он сделает сам!"', 0),
	(353, 'ruRU', 'Вы прибыли прямиком из Штормграда? Я слышал, что в человечьих землях обострилась ситуация с орками и грабителями. Там сейчас можно неплохо подзаработать – правда, |3-6($c)?', 0),
	(354, 'ruRU', 'Ты принес останки Агамондов? Эти проклятые твари уничтожены?', 0),
	(355, 'ruRU', 'Да?', 0),
	(356, 'ruRU', 'Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!', 0),
	(357, 'ruRU', '$N, ты принес книгу?', 0),
	(358, 'ruRU', 'Ты сделал то, о чем я просил? Убил этих псов и забрал у них лимфу?', 0),
	(361, 'ruRU', 'Да?', 0),
	(362, 'ruRU', 'Ты нашел Девлина?', 0),
	(365, 'ruRU', 'Страж смерти Симмер сказал мне, что ты принесешь очень нужные реагенты. Ты уже собрал десять тыкв, $N?', 0),
	(366, 'ruRU', 'Твои хозяева глупцы! Незачем было подсылать тебя. Я никогда не стану рабом Плети!', 0),
	(367, 'ruRU', 'Вы уже добыли 5 склянок крови пса Тьмы, $N? Время не ждет!', 0),
	(368, 'ruRU', '$N, тебе удалось собрать для меня 5 чешуек мурлоков из племени Злобного Плавника?', 0),
	(369, 'ruRU', 'Вы уже нашли яд злобного ночного кругопряда, $N? Это последний компонент, необходимый мне для испытания моего нового состава.', 0),
	(370, 'ruRU', 'Ты собрал 10 Алых перстней, |3-6($C)?', 0),
	(371, 'ruRU', 'Ну что, как прошел обход?', 0),
	(374, 'ruRU', 'Ты собрал 10 Алых перстней, |3-6($C)?', 0),
	(375, 'ruRU', 'Ты нашел для меня шкурки сумеречницы и грубую нить, $N?', 0),
	(376, 'ruRU', 'Постарайся остаться невредимым, пока я не найду для тебя каких-нибудь доспехов.', 0),
	(377, 'ruRU', 'Пока выродки вроде Декстрена Варда живут на этом свете, в мире нет места справедливости. Возвращайся, когда исполнишь приговор лорда Чернодрева. Тем самым мы утешим семьи покойных и – более того – преподадим урок Благородным домам.', 0),
	(378, 'ruRU', 'Я не могу допустить, чтобы идиотская бюрократия людей мешала правосудию дворфов, $N. Существуют неопровержимые доказательства, что за диверсией на мосту Тандола стоял Кам Гневливый. Из-за этого предателя погибли наши собратья. Если людям достаточно и того, чтобы Гневливый сгнил в тюрьме, это их дело... но я не смогу спать спокойно, пока мерзавец не будет убит.', 0),
	(380, 'ruRU', 'Удалось ли тебе найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!', 0),
	(381, 'ruRU', 'Они просто идиоты... копающие себе могилы.', 0),
	(382, 'ruRU', 'Как продвигается выполнение задания, $N?', 0),
	(383, 'ruRU', 'Да? Что тебе нужно?', 0),
	(384, 'ruRU', 'Мне нужно шесть ребер скального вепря и кружка "Болтливого пива", $N.', 0),
	(385, 'ruRU', 'Я не рассказывал, как кроколиск едва не откусил мне руку? Жуткая тварь была, зубы – как лезвия. Но мне повезло... Я заткнул ему пасть ножом. Этот нож я до сих пор храню...', 0),
	(386, 'ruRU', 'Ты уже побывал в тюрьме? Боюсь, что если предательство позволяет так долго сохранять жизнь Таргорру Ужасному, оно же может дать ему свободу. Он приговорен к смертной казни, $N, и не должен стать пешкой в руках интриганов.', 0),
	(388, 'ruRU', 'Я вижу, вы вернулись, $C. Вы уже собрали 10 красных шерстяных бандан, принадлежавших этому отродью, Братству Справедливости?', 0),
	(391, 'ruRU', 'Или ты мне принесешь голову Тредда, или я тебе, $N, твою собственную оторву, ясно?', 0),
	(392, 'ruRU', 'Да, $N? Что вы нашли?', 0),
	(393, 'ruRU', 'Приветствую. По какому делу вы ко мне явились, $C?', 0),
	(396, 'ruRU', '$N, верно? Барос Алекстон уже предупредил о вашем прибытии. Должен признаться, мне будет интересно вас выслушать.', 0),
	(398, 'ruRU', 'Да?', 0),
	(399, 'ruRU', '$n! Вы нашли компас?', 0),
	(400, 'ruRU', 'Хм? $GМал:Мала; ты еще для водителя осадной машины. Ну да ладно... Тебе что-нибудь починить надо?$B$BВозьми номерок и жди своей очереди. Я сейчас работаю над парой машин, и времени на еще одну работу у меня не будет как минимум пару дней.$B$BИли ты тут по другому вопросу?', 0),
	(404, 'ruRU', 'Ты выполнил задание, которое я тебе дал? Принес мне гнилые когти?', 0),
	(405, 'ruRU', 'Здравствуй. Либо ты не знаешь, кто я, либо у тебя ко мне очень срочное дело.\n\nПотому что иначе ты не посмел бы меня беспокоить…', 0),
	(407, 'ruRU', 'Прочь, нечестивое созданье! Свет, защити меня! Алый орден избавит Азерот от таких...\n\nОй... Это что, еда для меня? Я умираю с голода...', 0),
	(408, 'ruRU', 'Мы не можем позволить себе прохлаждаться, $N. С каждым часом кольцо Плети вокруг Тирисфальских лесов сжимается все сильнее.', 0),
	(409, 'ruRU', 'Старый, побитый, окровавленный стол.', 0),
	(411, 'ruRU', 'Ты вернул книгу Гюнтеру? Что он сказал?', 0),
	(412, 'ruRU', 'Перенаправлятор будет закончен и введен в эксплуатацию, как только у нас будет достаточно зубцов рестабилизации и гиромеханических шестерней.', 0),
	(413, 'ruRU', 'Привет, |3-6($c)! Что за дело привело тебя сюда?$B$BНадеюсь, что-нибудь стоящее. Я уже много дней не дрался хорошенько, да и этот бочонок эля уже почти пуст...', 0),
	(414, 'ruRU', 'Привет, |3-6($c), добро пожаловать в Телcамар!', 0),
	(416, 'ruRU', 'Приветствую тебя, $N! Как идет ловля крыс?', 0),
	(417, 'ruRU', 'Привет, $N. Есть у тебя весточка от моего друга Хилдельва?', 0),
	(418, 'ruRU', 'Я давно собираюсь начать готовить; где же все компоненты?', 0),
	(420, 'ruRU', 'О, приветствую! Как дела? Не хочешь пропустить стаканчик? В такой холод только этим и спасаешься.', 0),
	(421, 'ruRU', 'Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.', 0),
	(422, 'ruRU', 'Чтобы понять, с чем мы имеем дело, |3-6($C), мне нужно внимательно изучить книгу "Зелье Аругала". Принесите его мне, или мне придется поискать себе достойного слугу', 0),
	(423, 'ruRU', 'Мне понадобятся 6 наручей обжор и 3 наруча чернозлобов, чтобы я мог полностью разобраться с ситуацией и определиться с окончательным решением по Аругалу. А теперь – за дело. Убивайте обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберете всего, что мне нужно.', 0),
	(424, 'ruRU', 'Убит ли Мрачнон Белесый? Вариматасу вряд ли понравится, если мы проигнорируем его повеление.', 0),
	(425, 'ruRU', 'Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.', 0),
	(426, 'ruRU', 'Наш бой с Плетью продолжается, $N! Выполни свой долг и вышвырни эту мерзкую безмозглую $r<нежить> обратно в Чумные земли!', 0),
	(429, 'ruRU', 'У меня мало времени, |3-6($C): Темная Госпожа возложила на меня тяжелую задачу.', 0),
	(430, 'ruRU', 'Моя сестра сказала, что вы поможете нам. Это правда?', 0),
	(432, 'ruRU', 'Гр-р-р… Как я зол!', 0),
	(433, 'ruRU', 'Если мы сможем изгнать троггов из карьера Гол\'Болар, это будет первый шаг на долгом пути к избавлению от этой заразы.', 0),
	(435, 'ruRU', 'Ты вернул книгу Гюнтеру? Что он сказал?', 0),
	(437, 'ruRU', 'Вы уже уничтожили Плеть Ночи, $N? От этого зависит наш успех в борьбе против Гнилошкуров!', 0),
	(438, 'ruRU', 'Вы уже уничтожили Плеть Ночи, $N? От этого зависит наш успех в борьбе против Гнилошкуров!', 0),
	(439, 'ruRU', '$N, вы вернулись. Я полагаю, ваше расследование дало результаты?', 0),
	(440, 'ruRU', 'Здравствуйте, $N. Что привело вас обратно в Брилл?', 0),
	(441, 'ruRU', 'Мы знакомы?', 0),
	(442, 'ruRU', 'Силам Плети нельзя позволить оставаться в Серебряном бору, $N. Возвращайся ко мне с доказательством смерти Тула.', 0),
	(443, 'ruRU', 'Вы собрали лимфу Гнилошкуров, $N?', 0),
	(444, 'ruRU', 'Мои исследования требуют серьезной концентрации. Так что, надеюсь, ваш визит не праздный.', 0),
	(445, 'ruRU', 'Что у вас за дело ко мне, |3-6($C)?', 0),
	(446, 'ruRU', 'Приветствую вас, $N. Что сказал Бетор?', 0),
	(447, 'ruRU', 'Приветствую вас, |3-6($C). Какое дело у вас к Королевскому фармацевтическому обществу?', 0),
	(448, 'ruRU', 'Приветствую вас, $N. Что сказал Бетор?', 0),
	(449, 'ruRU', 'Удалось ли вам прояснить судьбу стражей смерти?', 0),
	(450, 'ruRU', 'Вижу, $N, вы снова здесь.', 0),
	(451, 'ruRU', 'Что вновь привело вас в Подгород, $N?', 0),
	(453, 'ruRU', 'Кто ты?! Оставь меня в покое!', 0),
	(455, 'ruRU', 'Ты идешь из озера Лок Модан? Что там орки? Как обстановка у Врат Альгаза?', 0),
	(456, 'ruRU', 'Дел еще немало, $N. Возвращайся ко мне, как только сократишь поголовье ночных саблезубов и щетинистых вепрей.', 0),
	(457, 'ruRU', 'Твоя работа еще не завершена, $N. Возвращайся ко мне после того, как убьешь 5 облезлых ночных саблезубов и 5 щетинистых вепрей.', 0),
	(458, 'ruRU', 'Твоя работа еще не завершена, $N Возвращайся ко мне после того, как убьешь 7 облезлых ночных саблезубов и 7 щетинистых вепрей.', 0),
	(459, 'ruRU', 'Помоги мне подтвердить или опровергнуть мои подозрения, $N. Принеси мне 8 кусочков мха Скверны.', 0),
	(460, 'ruRU', 'Видно, что эта могила была выкопана в спешке.', 0),
	(461, 'ruRU', 'Вот это место! Поднесите меня поближе...', 0),
	(464, 'ruRU', 'Ну что, ты показал оркам, почем фунт лиха?', 0),
	(465, 'ruRU', 'Вот одна из катапульт. Поджигаем?', 0),
	(466, 'ruRU', 'Где руда, $N?!', 0),
	(469, 'ruRU', 'Не интересуется ли $Gдобрый:прелестная:c; |3-6($c) сапогами из кроколисковой кожи? Могу предложить отличные выделанные шкуры!', 0),
	(470, 'ruRU', 'Где же моя сумочка?', 0),
	(471, 'ruRU', 'Помощник мне – как сын родной! Трудно же ему придется в жизни, одноногому...$B$BА, это ты, $N? Как твоя охота?', 0),
	(474, 'ruRU', 'Ты уже убил Нек\'роша?', 0),
	(475, 'ruRU', 'Добро пожаловать, $N Нашла ли ты ростки у озера?', 0),
	(476, 'ruRU', 'Добро пожаловать, $N Нашла ли ты ростки у озера?', 0),
	(477, 'ruRU', 'Вижу, $N, вы снова здесь.', 0),
	(478, 'ruRU', 'Узнали что-нибудь полезное, $N?', 0),
	(479, 'ruRU', 'Надо торопиться, нельзя дать их планам претвориться в жизнь – или мы можем перестать владеть Серебряным бором.', 0),
	(480, 'ruRU', 'Быстрее, время на исходе, $N!', 0),
	(481, 'ruRU', 'Слушаю вас, |3-6($C). Что это?', 0),
	(483, 'ruRU', '$N, похищенные друиды-вороны навеки останутся в ловушке Изумрудного Сна, если мы не сумеем добыть реликвии Пробуждения из обители Бен\'этиль, что на западе отсюда.$b$bЧем дольше мы медлим, тем неизбежнее их рок.', 0),
	(484, 'ruRU', '$n, я ведь тебя посылал за шкурами? Где же они?', 0),
	(486, 'ruRU', 'Наши собратья не смогут проснуться, пока Урсал Изверг жив, $N.', 0),
	(487, 'ruRU', 'На дороге все еще неспокойно, |3-6($c). Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.', 0),
	(488, 'ruRU', 'Ну что, $N, не $gзапыхался:запыхалась;? А я все думал, когда же ты принесешь то, что мне нужно:', 0),
	(489, 'ruRU', 'Ой, $N, ты мне что-то $Gпринес:принесла;? Видать, что-то вкусненькое?', 0),
	(491, 'ruRU', '$N, ты сразил Тула Когтя Ворона?', 0),
	(492, 'ruRU', 'Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!', 0),
	(493, 'ruRU', 'У вас ко мне какое-то дело?', 0),
	(496, 'ruRU', 'Я вижу, ты вернулся. Надеюсь, тебе удалось собрать нужные мне вещества. Еще один день без единой смерти совсем в тоску меня вгонит.', 0),
	(499, 'ruRU', 'Ква!', 0),
	(500, 'ruRU', 'Ну как, $N, поохотился на огров? Удалось собрать кости?', 0),
	(501, 'ruRU', 'Я помню тебя, $N. Ты собирался помочь мне составить последний эликсир. Мне нужна кровь горного льва, и я внесу новую толику страдания в жизнь обитателей Хилсбрада.', 0),
	(502, 'ruRU', 'Ав?', 0),
	(503, 'ruRU', 'Дай мне ключ, |3-6($C), и я сам отомкну замок.', 0),
	(506, 'ruRU', 'Дай мне ключ, |3-6($C), и я сам отомкну замок.', 0),
	(509, 'ruRU', 'Как дела во Владении Нетандера?', 0),
	(510, 'ruRU', '$N, вид у тебя обеспокоенный. Ты хочешь о чем-то рассказать?', 0),
	(511, 'ruRU', 'Да, господин? У тебя какое-то дело ко мне?', 0),
	(512, 'ruRU', 'Как охота на сторонников Синдиката? Где их перстни?', 0),
	(513, 'ruRU', 'Видишь, я занят, |3-6($C)? Темная Госпожа велит вывести новую чуму, пока нас не одолела Плеть со стороны Нордскола. С юга же нас теснят люди, поэтому время сейчас – главная ценность. Надеюсь, ты не по пустякам меня тревожишь!', 0),
	(514, 'ruRU', 'Тебя прислал Диббс из Южнобережья? Как поживает старый книжный червь?', 0),
	(515, 'ruRU', 'Я рад, что ты вернулся, $N. Я уж совсем заскучал. Ни единого развлечения, сижу, травлю и заражаю Ампи, а потом воскрешаю ее. И так целый день.\n\nКак прошло путешествие в Подгород? Тебе удалось зарубить по дороге человечка-другого?', 0),
	(516, 'ruRU', 'Узнали что-нибудь полезное, $N?', 0),
	(517, 'ruRU', 'Иногда я впадаю в такую тоску в этом городишке, что открываю кувшин формальдегида и наслаждаюсь ароматом. Ампи начинает нервничать.\n\nНу что, удалось добыть бочку у дворфов? Честное слово, если я буду пялиться на этот эликсир целый день и ни на ком его не опробую, я закричу!', 0),
	(518, 'ruRU', 'Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.\n\nТы ведь принес его?', 0),
	(519, 'ruRU', 'Мне нужны их головы, а не оправдания.', 0),
	(520, 'ruRU', 'Три головы у меня есть, а четвертой пока не видать. Это будет или голова Муг\'Тола, или твоя. Уж поверь мне на слово.', 0),
	(521, 'ruRU', 'Да? О чем ты хочешь доложить?', 0),
	(523, 'ruRU', 'Пусть барон Вардус не надеется, что Южнобережье возволит ему безнаказанно подсылать к нам своих головорезов. Мне нужна его голова!', 0),
	(524, 'ruRU', 'От ковра идет гнилостный запах.', 0),
	(527, 'ruRU', 'Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...', 0),
	(529, 'ruRU', 'Удалось ли тебе выполнить приказ, |3-6($C)? Мертв ли кузнец Веррингтан и его подмастерья? И где партия железа?', 0),
	(530, 'ruRU', 'Где его руки, $N?', 0),
	(531, 'ruRU', 'Молодец, $n! Мы его хорошенько проучили! Дай мне голову, я сама ей займусь.', 0),
	(532, 'ruRU', 'Какие вести ты несешь?', 0),
	(533, 'ruRU', 'Ну как, удалось что-нибудь узнать? Боюсь, надежды для Гол\'дира все меньше и меньше...', 0),
	(535, 'ruRU', 'Так что, ты принес мне чего-нибудь выпить или пришел просто покончить со мной?', 0),
	(536, 'ruRU', 'Еще один эль, пожалуйста, последний как будто пропал!$B$BСвет, сколько еще я буду здесь торчать?$B$BО, это ты, $N. Ты уже $Gубил:убила; этих мурлоков? ', 0),
	(540, 'ruRU', 'Жаль, что я сам не могу поискать в руинах, но боюсь, старые кости не выдержат пути вверх по горам. А у тебя как идут поиски знаний, $N?', 0),
	(542, 'ruRU', '$N, вы вернулись! Как ваша миссия в Альтераке? Вы что-нибудь принесли?', 0),
	(543, 'ruRU', 'Приветствую, $N! Постарайтесь не наступить мне на отвороты брюк, костюмчик только что от портного.', 0),
	(544, 'ruRU', 'Удалось ли найти воров? И что куда важнее, вернуть похищенное?', 0),
	(545, 'ruRU', 'Здравствуй, $N. Элементали – непростые противники, но я не сомневаюсь, что ты справишься. Ты несешь мне их браслеты?', 0),
	(546, 'ruRU', 'Итак, $N возвращается? Сколько людей ты убил сегодня? Надеюсь, не одну сотню!\n\nТы несешь мне черепа?', 0),
	(547, 'ruRU', 'Тебе удалось добыть мой меч, $N? Если верховный палач Дарталия узнает о моей небрежности, она прикажет меня повесить вниз головой!', 0),
	(549, 'ruRU', 'Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?', 0),
	(550, 'ruRU', 'Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?', 0),
	(552, 'ruRU', 'Удалось ли тебе вернуть жезл Гелькулара? Там так много йети, что найти его будет нелегко. И все же без него не обойтись.', 0),
	(553, 'ruRU', 'От гробницы Гелькулара исходит духовная энергия.', 0),
	(554, 'ruRU', 'Опять мне мешают?$B$BА, на этот пергамент наложено очень тонкое, сложное заклинание. Разумеется, я смогу его распутать, но на это потребуется время. А время – деньги.$B$BМожет быть, мне просто купить его у тебя?', 0),
	(555, 'ruRU', 'Ну как, удалось найти нужные продукты? Да, скажу тебе, бывали времена поспокойнее. Ах, если бы не было войн... ', 0),
	(556, 'ruRU', 'Где истертые каменные талисманы, $N? Колдун хочет раскрыть их тайны.', 0),
	(557, 'ruRU', 'Здравствуй, $N. Элементали – непростые противники, но я не сомневаюсь, что ты справишься. Ты несешь мне их браслеты?', 0),
	(558, 'ruRU', 'Когда-нибудь, я хочу быть героем - как Джайна... Ну, мальчик, который герой.', 0),
	(559, 'ruRU', 'Ты несешь мне головы, $N?', 0),
	(560, 'ruRU', 'Приветствую тебя. Ты хочешь предложить свою помощь в поддержании порядка в Южнобережье?', 0),
	(563, 'ruRU', 'Приветствую тебя. Чем могу тебе помочь я, городской стражник Штормграда?', 0),
	(565, 'ruRU', 'Итак, ты вернулся к великому Бартоло. Быть может, все материалы для плаща из меха йети собраны? Или просто хочешь постоять рядом со знаменитостью?', 0),
	(566, 'ruRU', 'А, $N. Ты не за наградой за голову барона Вардуса?', 0),
	(568, 'ruRU', '$C. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?', 0),
	(569, 'ruRU', 'Я жду, когда ты принесешь мне осколок таблички, $N.', 0),
	(570, 'ruRU', 'Добрые ли вести ты несешь?', 0),
	(572, 'ruRU', 'Сопутствовал ли тебе успех в охоте?', 0),
	(574, 'ruRU', 'Сержант Йохва говорит, что ты силен и отважен, $C. Докладывай!', 0),
	(575, 'ruRU', 'У меня все готово, не хватает только шкур. Одно тебе скажу, не надо заставлять Ридлвокса ждать.$B$BНе стоит расстраивать главного изобретателя Союза ремонтников.', 0),
	(576, 'ruRU', 'Эгей, $Gприятель:подруга;! Может, я и не вижу ничего, но чую я тебя аж с другой стороны порта.$B$BГлаз бы мне не помешал. Капитан меня протащит под килем, если узнает, что моя гляделка в руках грязных пиратов Кровавого Паруса.$B$BКому нужен слепой вперёдсмотрящий? Я буквально жил на марсовой площадке... а теперь мне в лучшем случае поручат драить палубу.', 0),
	(577, 'ruRU', 'Превосходные сапоги Дриззлика – отличная работа, стопроцентная кожа морских кроколисков. Лучше не бывает!\n\nОписания заманчивей не придумаешь, верно?\n\nРазве что ты принес мне шкуры?', 0),
	(579, 'ruRU', 'Король Вариан уделяет огромное внимание просвещению и всемерно заботится о том, чтобы с ценных книг вовремя делались списки, доступные горожанам. Все просто: принесите мне библиотечный свиток, и я выдам вам копию любой имеющейся книги.', 0),
	(580, 'ruRU', 'Разрази меня гром! У меня почти кончилась выпивка! Кэп собирается поднять якоря, а старый Слим засохнет, как пустыня Танарис. А уж когда кэп узнает, что пропал его портвейн... лучше сразу за борт!', 0),
	(581, 'ruRU', '$C. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?', 0),
	(582, 'ruRU', '$N. Я боюсь за сына нашего вождя. Ты принес мне головы? Я хочу их осмотреть.', 0),
	(585, 'ruRU', 'Я жду черепов...', 0),
	(586, 'ruRU', 'Хотя моя собственная плоть постепенно облезает с черепа, я чую твой страх.\n\nХа! Ты никогда не справишься с моим заданием...', 0),
	(587, 'ruRU', 'Ну как, удалось найти товары, дружище?', 0),
	(589, 'ruRU', 'Ты принес осколки, $N? Без них нам не обойтись, даже когда удастся заполучить Око Разума.', 0),
	(591, 'ruRU', 'Приветствую тебя, $N. Духи поют хвалу твоей храбрости, но о победе над Май\'Зотом они молчат.\n\nНесешь ли ты мне Око?', 0),
	(596, 'ruRU', 'Когда-нибудь племя Черного Копья сокрушит Кровавый Скальп! Ты принес мне ожерелья наших врагов?', 0),
	(598, 'ruRU', 'Клан Дробителей Черепов проклянет день, когда они выступили против нас! Ты справился с моим заданием?', 0),
	(600, 'ruRU', 'Ты $Gпринёс:принесла; мне кристаллы?? Они мне нужны!!!$B$BТо есть... Мне нужно знать, что гнусную Торговую Компанию вскоре вытеснят из Тернистой долины. Потому что, э-э-э, нам, честным предпринимателям, надо зарабатывать на хлеб насущный!', 0),
	(601, 'ruRU', 'Как дела, $N?', 0),
	(602, 'ruRU', 'Простите, но сейчас я очень занят.', 0),
	(604, 'ruRU', 'Эгей, $N. Какие вести ты несешь из южного лагеря Кровавого Паруса?', 0),
	(605, 'ruRU', 'Удалось добыть осколки? Процент с выручки получишь!', 0),
	(606, 'ruRU', 'Эй, мне не нравится, как вы на меня смотрите, $Gсударь:леди;.', 0),
	(607, 'ruRU', 'Ладно, $N. Где долг Трусишки?', 0),
	(608, 'ruRU', 'В чем проблема, $N? Нам нужно атаковать раньше, чем это сделают пираты Кровавого Паруса!', 0),
	(609, 'ruRU', 'Ну что, $Gнашёл:нашла; этих трех зараз? $GЗабрал:Забрала; у них ценности?', 0),
	(610, 'ruRU', 'Ты знаешь, что меня раньше никто не побеждал? Да, бывало, ранили, без этого ни одна поножовщина не обходится, но он долбанул меня по голове, я и отключилась. Пришла в себя – а кинжала нет.$B$BПо моему прозвищу легко понять, что без кинжала мне не жить, и мне нужен именно этот кинжал.', 0),
	(611, 'ruRU', 'Тебе удалось добыть для меня Камень Приливов, $N? Я уже приготовил для него место и купил красивую подставку.', 0),
	(613, 'ruRU', 'Эгей, $N! $GНашёл:Нашла; ключ Моури?', 0),
	(614, 'ruRU', 'Эгей, $N! $GНашёл:Нашла; Горлаша? Это был мой любимый сундук, к тому же в тайном отделении лежат все мои сокровища!', 0),
	(617, 'ruRU', 'Если ты не по делу, вали отсюда, $N.', 0),
	(621, 'ruRU', 'Ты $Gпринёс:принесла; мне образцы смеси Занзила?', 0),
	(622, 'ruRU', 'Привет, $N. Добрался до Пиратской бухты без приключений? Починил ли гоблин Кразек мой горшок??', 0),
	(623, 'ruRU', 'А?', 0),
	(624, 'ruRU', 'Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему – нет, я надеюсь?\n\nУф! Было бы очень жаль!', 0),
	(627, 'ruRU', 'Привет, $N. Удалось добыть кровавые камни?', 0),
	(628, 'ruRU', 'Я где-то читал, что солоноводные кроколиски постепенно вымирают... это повредит моему делу, а?$B$BВпрочем, надеюсь, ты $Gдобыл:добыла; мне шкуру старого солоноводного кроколиска!', 0),
	(629, 'ruRU', 'Я жду, когда ты принесешь мне осколок таблички, $N.', 0),
	(630, 'ruRU', 'Хвала предкам, кто-то пришел мне на помощь. Ты несешь мне ключ, а вместе с ним и свободу?', 0),
	(632, 'ruRU', 'Есть новости о Ржавом Засове, $N?', 0),
	(635, 'ruRU', 'Дай мне ключ, |3-6($C), и я сам отомкну замок.', 0),
	(639, 'ruRU', 'Вы еще не выяснили местонахождение первой печати? Скорее всего, она находится у кого-то из посланников Синдиката в Стромгарде.', 0),
	(640, 'ruRU', 'Тром\'ка, |3-6($C). Зенгу сообщил, что вам нужна моя помощь.', 0),
	(641, 'ruRU', '$N! У вас есть вторая печать?', 0),
	(642, 'ruRU', 'Эта группа кристаллов выглядит очень похожей на кристаллы Мизраэли. Однако они не излучают такое же чувство надежности и безопасности.', 0),
	(643, 'ruRU', 'Храброзова будет нелегко выследить, $N. Верхом он может перемещаться очень быстро. Тем не менее эта печать нам необходима.', 0),
	(644, 'ruRU', 'Вы вернулись, $N. Прерван ли род Игнеуса Троллебоя?', 0),
	(645, 'ruRU', 'Углубления в камне на верхней стороне надгробия Троллебоя совпадают с сияющими линиями печати Игнеуса...', 0),
	(646, 'ruRU', '$N! Вам удалось забрать меч?', 0),
	(647, 'ruRU', 'Что хорошего скажешь, |3-6($r)?', 0),
	(651, 'ruRU', 'Перед вами внутренний связывающий камень. Это самый мощный из связывающих камней, и нужно открыть его, чтобы открылись замки остальных камней.', 0),
	(652, 'ruRU', 'Краеугольный камень заряжен сильнейшей геомантической энергией.', 0),
	(656, 'ruRU', 'Кристаллы Мизраэли сейчас подозрительно спокойны.', 0),
	(658, 'ruRU', 'Мы признательны вам за помощь в поисках гонца, $N.$B$BПока вас не было, Кин увидела аптекаря, выходящего из того же дома к югу отсюда. Я уверена, что они замышляют что-то дурное – но мне нужны доказательства, чтобы не натворить чего-нибудь по неосторожности.$B$BА вам удача улыбнулась?', 0),
	(660, 'ruRU', 'Время для болтовни закончилось. Защитите Кинелори, если вам небезразлична судьба народа Хилсбрада.', 0),
	(662, 'ruRU', 'Как успехи в поиске и спасении документов, $N? Нам и правда очень нужно забрать судовые журналы и карты с "Девичьей Блажи" и "Духа Серебряного бора".\n\nЕсли имеющиеся там сведения попадут в руки врагов, командир флота Морской Рок нас по палубе размажет.\n\nЭто если нам вообще удастся отсюда выбраться...', 0),
	(664, 'ruRU', 'Как успехи в поиске и спасении документов, $N? Нам и правда очень нужно забрать судовые журналы и карты с "Девичьей Блажи" и "Духа Серебряного бора".\n\nЕсли имеющиеся там сведения попадут в руки врагов, командир флота Морской Рок нас по палубе размажет.\n\nЭто если нам вообще удастся отсюда выбраться...', 0),
	(665, 'ruRU', 'Некогда болтать! Нужно зарядить очки энергией камня!', 0),
	(666, 'ruRU', 'Ну, и как работают очки? Все функционирует как надо? Можно подрегулировать, если есть необходимость.\n\nАх да, эти очки понадобятся мне, когда вы закончите. Я уверен, что капитан О\'Брин найдет им потом самое разнообразное применение.', 0),
	(667, 'ruRU', 'Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!', 0),
	(668, 'ruRU', 'Эй, |3-6($C). Что привело вас на мостик?', 0),
	(669, 'ruRU', 'Что привело вас в Пиратскую бухту, |3-6($C)?', 0),
	(670, 'ruRU', 'Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!', 0),
	(671, 'ruRU', 'Однажды проклятая кровь по-прежнему течет в моих жилах, $N. Если кто-то... что-то... призывает демонов... его надо остановить.', 0),
	(672, 'ruRU', 'Я создам амулет, который частично наделит Гор\'муля силой ящеров. Может быть, это пробудит в нем огонь жизни...', 0),
	(673, 'ruRU', 'Кровь моя пылает... все сильнее. Чернокнижника нужно остановить.', 0),
	(674, 'ruRU', 'Какая может быть надежда, если рукой труса может быть убит сильнейший из сильных? Какая надежда, ответьте мне!', 0),
	(678, 'ruRU', 'Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!', 0),
	(679, 'ruRU', '$N! Вам удалось забрать меч?', 0),
	(680, 'ruRU', 'Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор\'Калара.', 0),
	(681, 'ruRU', '$N, с каждым часом наша власть над Стромгардом становится все слабее. Вы должны поторопиться, иначе наш город обязательно падет.', 0),
	(682, 'ruRU', 'Вы нашли знаки Стромгарда, $N? В Синдикате должны понять, что они не могут наживаться на смерти наших воинов.', 0),
	(684, 'ruRU', 'Приветствую, $C. Вы хотите мне о чем-то сообщить?', 0),
	(685, 'ruRU', 'Приветствую, докладывайте.', 0),
	(688, 'ruRU', 'Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор\'Калара.', 0),
	(691, 'ruRU', 'Что-нибудь вам уже удалось, $N?$B$B<Кретьен в процессе чтения делает какие-то пометки в своем журнале.>$B$BЕсли мои исследования верны, клыки можно собирать с любых троллей из племени Сухокожих. Лекарские сумки должны быть у знахарей Сухокожих, а особые ножи даются самым лучшим темным охотникам племени, когда они проходят ритуал посвящения. Невозможно заранее сказать, у какого из темных охотников есть такой нож, пока не сразишься с ним.', 0),
	(692, 'ruRU', 'Вы нашли фрагменты?! Вам непременно понадобится Свиток Мизраэли, если вы хотите вновь пленить ее, пока еще не стало слишком поздно!', 0),
	(693, 'ruRU', 'Наша цель – жезл, $N. Пока сосредоточьтесь на этой задаче.', 0),
	(694, 'ruRU', 'Привет еще раз, $N. Вы еще не нашли лазурный агат?', 0),
	(696, 'ruRU', 'Тебе все удастся сделать, и я уверен, Малин будет более чем доволен тобой.', 0),
	(697, 'ruRU', 'Слушаю вас... Ваше лицо мне смутно знакомо. Прошу прощения, мы раньше нигде не встречались? У меня столько дел, что я просто теряюсь.', 0),
	(701, 'ruRU', 'Я все приготовил, теперь мне нужны лишь сердца ящера.', 0),
	(702, 'ruRU', 'Это ты опять? Не хватало мне очередной порции жалости Тор\'гана.\n\nЧто ты принес на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..', 0),
	(703, 'ruRU', 'Привет, $N! Ну что, что там с моими крылышками?', 0),
	(704, 'ruRU', 'Ты нашел эти урны, $N? Надо разобраться, как они связаны с троггами!', 0),
	(705, 'ruRU', 'Ты $Gпринёс:принесла; мне жемчужины? У меня почти кончился запас световых бомб.', 0),
	(706, 'ruRU', 'Как охота, $C?', 0),
	(709, 'ruRU', 'Ты $Gнашел:нашла; табличку? В ней должен содержаться ключ к нашему спасению!', 0),
	(710, 'ruRU', 'Так, вот сюда будет в самый раз... Слушай, подержи-ка вот здесь эту штуку! Ага, вот так, только выровняй по нормали. О чем бишь я... Ах, да! Камни, мне нужны маленькие осколки камней... Удобный полигон и материалы для исследования – все, что нужно ученому...', 0),
	(711, 'ruRU', 'Ты чрезвычайно $Gпорадовал:порадовала; меня, $N. Как я и предполагал, мелкие камни разрушились в ходе иследования. Если этот эксперимент будет вполовину столь удачен, как я предполагаю, то те элементали, которых я вызывал прежде, в сравнение не будут идти с теми, которыми я смогу повелевать!', 0),
	(712, 'ruRU', 'Большие камни, которые ты принес мне, просто чудесны, $N! Люсьен доставит те, что останутся от экспериментов, в Каранос. Они мне еще пригодятся.$B$BНапример, устрою себе из них уютное маленькое убежище, когда начну, наконец, практические исследования в рамках междисциплинарного подхода к взрывчатым веществам широкого спектра действия...$B$B*Голос Лотвиля стихает по мере того, как ученый вновь погружается в свои эксперименты*', 0),
	(713, 'ruRU', 'Ты $Gпринёс:принесла; масло? Мне оно так нужно!', 0),
	(714, 'ruRU', 'Да-да, одну секундочку... $B$B<Лотвил продолжает ковыряться в каком-то хитроумном приспособлении>', 0),
	(715, 'ruRU', 'Лотвиль уже почти закончил. А как твои успехи?', 0),
	(716, 'ruRU', 'Лучше бы тебе не тянуть, $N.$B$BС Лотвилем никогда не знаешь, что случится в следующий миг.', 0),
	(717, 'ruRU', 'Мощная магия держит драконов под замком, и все же мы должны устранить даже малейшую возможность того, что они снова вырвутся на свободу!', 0),
	(718, 'ruRU', 'Да, пустыня не лучшее место для похудания...$B$BЭй, что это у тебя?', 0),
	(719, 'ruRU', 'Не знаю, зачем эти из клана Тенегорна рыщут, но у них определенно есть какая-то цель...', 0),
	(727, 'ruRU', 'Приветствую! Добро пожаловать в мою лавку, только не трогайте что попало!$B$BЗнание может быть смертельно опасным!', 0),
	(732, 'ruRU', 'Шайка бродячих огров кочует от лагеря к лагерю в Бесплодных землях. Пустынный ветер заметает их следы, и их перемещения крайне сложно отследить. Слыхал, их видели недавно близ лагеря Бофф. Попробуй поискать там.', 0),
	(733, 'ruRU', 'Ну, мы тут состряпали кое-какое укрепления из подручных материалов, но... Как видишь, наскребли негусто. Удалось добыть что-нибудь?', 0),
	(734, 'ruRU', 'Пекрасно, прекрасно...$B$B*Лотвиль на секунду отрывает взгляд от кандалов*$B$BСбегай-ка к Люсьену, $N. Мне нужен зубец #5. Принеси его мне.', 0),
	(735, 'ruRU', 'Вы принесли то, о чем я вас просил?', 0),
	(737, 'ruRU', 'Ну вот и ты! Где $Gпропадал:пропадала;? $GПринес:Принесла; книгу?', 0),
	(741, 'ruRU', 'Чем могу помочь, |3-6($r)?', 0),
	(743, 'ruRU', 'Гарпии из клана Ярость Ветра – наши смертельные враги. Их ярость в битве сравнится лишь с их жаждой сырой плоти.', 0),
	(744, 'ruRU', 'Этот головной убор станет замечательным подарком моему брату!', 0),
	(745, 'ruRU', 'If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.', 0),
	(746, 'ruRU', 'Привет, $N. Ты принес сломанные инструменты? Дворфийские раскопки разъяряют мулгорских кодо. Пора положить конец осквернению нашей земли!', 0),
	(747, 'ruRU', 'Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.', 0),
	(748, 'ruRU', 'Ты несешь лапы и когти, $N?', 0),
	(749, 'ruRU', 'Ну как, нашел перепелятников? А где их перья?', 0),
	(750, 'ruRU', 'Если ты сможешь добыть шкуры, я замолвлю о тебе словечко перед отцом, вождем Соколиным Ветром.', 0),
	(751, 'ruRU', 'Привет тебе, $N. Удалось что-нибудь вызнать о планах Торговой Компании и ее деятельности на нашей родине?\n\nЕсли они хотят творить в наших землях то же, что и в других, мы быстро с этим покончим.', 0),
	(752, 'ruRU', 'Остроклык больше не будет угрожать нам, если ты принесешь мне его голову, $N.\n\nМы, таурены, живем охотой, а самая захватывающая охота – та, где ты и сам можешь стать жертвой. Если ты преуспеешь в этом задании, то поймешь, о чем я говорю.', 0),
	(753, 'ruRU', 'Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?', 0),
	(755, 'ruRU', 'Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?', 0),
	(756, 'ruRU', 'Ну как, ты добыл когти, как я велел? С каждым часом Колодец Громового Рога загрязняется все больше!', 0),
	(757, 'ruRU', 'Ты прошел обряд Силы, $N? Покажи мне доказательства твоей доблести, проявленной в войне против нашего врага – племени Дыбогривов.', 0),
	(761, 'ruRU', 'Ну как, нашел перепелятников? А где их перья?', 0),
	(763, 'ruRU', 'Что привело тебя в мою деревню, |3-6($C)?', 0),
	(764, 'ruRU', 'Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.', 0),
	(765, 'ruRU', 'Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.', 0),
	(766, 'ruRU', 'Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.', 0),
	(767, 'ruRU', 'Ну как, нашел перепелятников? А где их перья?', 0),
	(771, 'ruRU', 'Когда ты принесешь мне достаточно камней и янтарного семени, я сделаю для тебя воду Провидцев.', 0),
	(776, 'ruRU', 'Ты уже выследил Арра\'чею?', 0),
	(778, 'ruRU', 'Да... Не совсем тот результат, на который я рассчитывал... Не вернешь ли ты теперь мне оковы?', 0),
	(779, 'ruRU', 'Перед вами Печать земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.', 0),
	(780, 'ruRU', 'То, что боевые вепри творят в наших землях, уже переходит всякие границы. Сумел ли ты приструнить этих зверей? А бока и рыла принес?', 0),
	(781, 'ruRU', 'Ты чем-то обеспокоен, $N? Какую весть ты принес?', 0),
	(786, 'ruRU', 'Кентавры постоянно изводят Орду своими набегами. Они намерены взять нашу родину в осаду! Этого нельзя допустить!', 0),
	(788, 'ruRU', 'Не рано ли ты $gвернулся:вернулась;, а, $n? Надеюсь, ты не будешь уверять, будто $gвыполнил:выполнила; все, что тебе было поручено?', 0),
	(789, 'ruRU', 'У скорпиона панцирь прочный, но не настолько, чтобы сильный воин не сумел его пробить. Пусть рука твоя будет тверда, и душа не знает сомнений – тогда скорпионы окажутся легкой добычей!', 0),
	(790, 'ruRU', 'Ох... Отец мой говаривал, что толку из меня не выйдет, и вот лежу я под деревом, помираю и думаю: прав был папаня…\n\nНо я хочу умереть, зная, что последний из моих врагов тоже мертв!', 0),
	(791, 'ruRU', 'Когда мы заселяли эти земли, я гордо сражался плечом к плечу с вождем. Все мое тело покрыто шрамами.\n\nЯ отстаивал честь Орды своим боевым топором в день победы над Архимондом, когда по необходимости был заключен нечестивый союз с людьми и эльфами.\n\nНо моя должность стража открыла мне новый взгляд на вещи.', 0),
	(792, 'ruRU', 'Ну что, собрала плоды?', 0),
	(794, 'ruRU', 'Ну что, $N, задание выполнено? Удалось ли тебе раздобыть медальон Пылающего Клинка?', 0),
	(804, 'ruRU', 'Ну что, $N, задание выполнено? Удалось ли тебе раздобыть медальон Пылающего Клинка?', 0),
	(805, 'ruRU', 'Ну что, $N, задание выполнено? Удалось ли тебе раздобыть медальон Пылающего Клинка?', 0),
	(806, 'ruRU', 'Ну что, $N, удалось тебе найти Пшикса? Он и ему подобные должны быть изгнаны из наших земель!', 0),
	(808, 'ruRU', 'Ну что, $N, череп моего брата у тебя? Он наконец свободен?', 0),
	(809, 'ruRU', 'Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.', 0),
	(812, 'ruRU', 'Я даже рад, что не могу сейчас вернуться в Сен\'джин. Все смеялись бы над моей слабостью и глупостью!', 0),
	(813, 'ruRU', 'Не забывай, если ты на какую-то тварь охотишься, первым делом надо как следует изучить ее повадки! Это может спасти тебе жизнь.', 0),
	(815, 'ruRU', 'Завтрак, обед, ужин! Какая, в сущности, разница? Все равно кто-то должен готовить еду, и этот кто-то – я!', 0),
	(816, 'ruRU', 'Я молюсь, чтобы Крон вернулся ко мне, но, боюсь, я уже знаю, что с ним случилось…', 0),
	(817, 'ruRU', 'Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!', 0),
	(818, 'ruRU', 'Вот-вот, сила и воля по-настоящему проявляются только со временем. Потеряешь терпение, дашь слабину – тут-то и вылезет твоя подлинная натура!', 0),
	(819, 'ruRU', 'Да?', 0),
	(821, 'ruRU', 'Как идут поиски?', 0),
	(822, 'ruRU', 'Ну как, трудишься, ищешь все составляющие, $N?', 0),
	(823, 'ruRU', 'Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!', 0),
	(824, 'ruRU', 'А, привет. Я много времени трачу на изучение воды – вернее, всех Стихий – так много, что порой не замечаю никого вокруг.\n\nВ чем тебе помочь разобраться?', 0),
	(825, 'ruRU', 'Когда мы узнаем, как люди управляют своей странной техникой, у нас будет куда больше шансов победить их в грядущих битвах.\n\nС новыми знаниями Орда станет сильнее!', 0),
	(826, 'ruRU', 'Ну что, $N, Залазан побежден?', 0),
	(827, 'ruRU', 'Ну что, $N, удалось тебе проникнуть в Скалу Черепа? Принесла обжигающие ошейники?', 0),
	(828, 'ruRU', 'Ну что, $N, удалось тебе найти Пшикса? Он и ему подобные должны быть изгнаны из наших земель!', 0),
	(829, 'ruRU', 'Мое почтение, |3-6($C). Чем могу я помочь тебе, сестра?', 0),
	(830, 'ruRU', 'У тебя озабоченный вид, |3-6($C). Что у тебя там?', 0),
	(831, 'ruRU', 'Ты что, не видишь? Я занят. Ну, докладывай. Но если дело не срочное...', 0),
	(834, 'ruRU', 'Не пойми меня неправильно, я мастер своего дела, но ведь это же просто смешно! Что мне тут делать, песочные замки строить?', 0),
	(835, 'ruRU', 'Даже не верится, что такое мог говорить мой шеф, Газлоу, а ведь он мужик соображающий. "Не бойся рисковать, когда надо", – вот что он говорил.\n\nВедь гарпии так и будут нападать на нас и на караваны, пока мы что-нибудь с этим не сделаем, верно?', 0),
	(840, 'ruRU', 'Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.', 0),
	(842, 'ruRU', 'Ну-с, и кто у нас тут? Неужели Каргал снизошел до того, чтобы прислать мне очередного рекрута?', 0),
	(843, 'ruRU', 'С появлением в Бейл Модане дворфов многие ни в чем не повинные таурены лишились жизни или покинули родину предков. Я должен вернуть свои земли!', 0),
	(844, 'ruRU', 'Принес клювы долгоногов?', 0),
	(845, 'ruRU', 'Сколько жевр тебе удалось убить?', 0),
	(846, 'ruRU', 'Вижу, ты вернулся, $N.\n\nХотя смерть Хазгорма и замедлила уничтожение холмов моих предков, полностью остановить разрушение не удалось.\n\nКрепость в Бейл Модане – угроза для нас всех. Она была построена для защиты раскопа, а теперь представляет собой грозную военную силу.\n\nЕсли ты принесешь мне все необходимое, я готов сделать заряд, после взрыва которого дворфы-торопыги передумают лезть в Степи.', 0),
	(848, 'ruRU', 'И где же споры? Мне надо сварить определенное зелье для коллеги из Громового Утеса, для этого и требуются споры...', 0),
	(849, 'ruRU', 'Ну вот, теперь, когда дворфийский ветролет уничтожен, я ощущаю сладость мести.', 0),
	(850, 'ruRU', 'Привет, $N. Принес голову Барака?', 0),
	(851, 'ruRU', 'Удалось найти Верога, $N?', 0),
	(852, 'ruRU', 'Так Хэрзул повержен?', 0),
	(853, 'ruRU', 'Ты несешь мне посылочку от аптекаря Хелбрима?', 0),
	(855, 'ruRU', 'Как идет охота, $N?', 0),
	(857, 'ruRU', 'Где слеза Лун? Она мне нужна! Нужна, говорю!', 0),
	(858, 'ruRU', 'Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!', 0),
	(862, 'ruRU', 'Ну что, достаточно пещерных крыс притащил?', 0),
	(863, 'ruRU', 'Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.', 0),
	(865, 'ruRU', 'Ты принес рога, $N? Я собираюсь сколотить состояние на этих тварях!', 0),
	(867, 'ruRU', 'Ну как, много ли гарпий удалось убить? Режь их, круши и бери трофеи. Мне нужно 8 когтей Зачарованного Крыла.', 0),
	(868, 'ruRU', 'Осторожно, яйца хрупкие. Разбитые мне не нужны.', 0),
	(869, 'ruRU', 'Принес головы, $N?', 0),
	(870, 'ruRU', 'И где же споры? Мне надо сварить определенное зелье для коллеги из Громового Утеса, для этого и требуются споры...', 0),
	(871, 'ruRU', 'Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.', 0),
	(872, 'ruRU', 'Отрежь голову их вожаку, и воцарится хаос. Хорошенько усвой этот урок. Он пригодится тебе в будущем.\n\nЭти свиньи будут метаться без цели, и мы захватим все Степи.', 0),
	(873, 'ruRU', 'Не бойся вод, |3-6($R).', 0),
	(874, 'ruRU', 'Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!', 0),
	(875, 'ruRU', 'Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.', 0),
	(876, 'ruRU', 'Ты ничего не получишь, пока я не увижу голову Серены.', 0),
	(877, 'ruRU', 'Осторожно, яйца хрупкие. Разбитые мне не нужны.', 0),
	(878, 'ruRU', 'Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.', 0),
	(879, 'ruRU', 'И как идет охота, |3-6($R)? фыркает Торк полагает, что знает, кто возглавляет набеги на его народ, фыркает но он поймет, как ошибался.\n\nМоя смерть неотвратима, но тебе удалось нанести серьезный урон моим врагам, и Кривозуб ни о чем не жалеет. фыркает', 0),
	(880, 'ruRU', 'Как идет сбор панцирей? Много набрал?', 0),
	(881, 'ruRU', 'Тебя ожидает великий кот, $N.', 0),
	(882, 'ruRU', 'Удалось ли тебе одолеть Ишамухала, $N?', 0),
	(883, 'ruRU', '$N, я вижу в твоих глазах сияние новой силы! Скажи, ты встретился с великим Лакота\'мани?', 0),
	(884, 'ruRU', '$N, я вижу в твоих глазах сияние новой силы! Тебе удалось встретиться с могучей Оватанкой?', 0),
	(885, 'ruRU', 'Я вижу, ты исполнен решимости, $N. Решимости, порожденной страданием…\n\nТебя тяготит гибель Ваште Пауни?', 0),
	(887, 'ruRU', 'Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?', 0),
	(888, 'ruRU', 'Ну что, удалось найти мои вещи?', 0),
	(890, 'ruRU', 'Хочешь отправить товар со следующим кораблем, $N?', 0),
	(891, 'ruRU', 'Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.', 0),
	(892, 'ruRU', 'Ну и что сказал Дыбоволос?', 0),
	(893, 'ruRU', 'У меня тоже есть сомнения насчет того, что жалкие иглогривые могли научиться кузнечному делу, но я выполняю приказы вождя, и потому стараюсь узнать побольше о племени Иглогривых.\n\nУ меня бывали задания и попротивней, но я с радостью выполняю их, чтобы служить народу орков.', 0),
	(894, 'ruRU', 'Привет, $N. Принес голову Барака?', 0),
	(895, 'ruRU', 'Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?', 0),
	(896, 'ruRU', 'Если бы мы знали, кто именно нашел этот изумруд, дело выеденного яйца не стоило бы...', 0),
	(898, 'ruRU', 'Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.', 0),
	(899, 'ruRU', 'Иглогривы за все заплатят, $N. Клянусь.', 0),
	(900, 'ruRU', 'Привет, $N. Принес голову Барака?', 0),
	(901, 'ruRU', 'Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.', 0),
	(902, 'ruRU', 'А, вот и ты, $N! Принес самофланж?', 0),
	(903, 'ruRU', 'Как успехи на охоте? Удалось найти хищников?', 0),
	(905, 'ruRU', 'Осторожно, яйца хрупкие. Разбитые мне не нужны.', 0),
	(906, 'ruRU', 'Да, что такое?', 0),
	(907, 'ruRU', 'Тебе удалось одолеть рокочущих ящериц, $N?', 0),
	(913, 'ruRU', 'Задание выполнено? Тебе удалось убить грозового змея?', 0),
	(914, 'ruRU', 'Меня преследуют воспоминания о моих кошмарах, $N. Удалось ли тебе убить отступников и завладеть их кристаллами?', 0),
	(916, 'ruRU', 'Тебе удалось собрать ядовитые железы, $N?', 0),
	(917, 'ruRU', 'Тебе удалось проникнуть в Паучье логово, $N? А найти паучье яйцо?', 0),
	(918, 'ruRU', 'Ты $Gдобыл:добыла; саженцы? Мне не терпится посадить их.', 0),
	(919, 'ruRU', 'Добро пожаловать, $N. $GНашел:Нашла; ли ты ростки у озера?', 0),
	(920, 'ruRU', 'Пожалуйста, принеси мне все эти ингредиенты, $N Иверрону нужна наша помощь!', 0),
	(921, 'ruRU', 'Лунные колодцы содержат воду Источника Вечности, древнего источника магии, который навлек на наш мир так много ужасов.$b$bДруиды пользуются свойствами колодцев, а Стражи чтят их как святилища Элуны, но использовать магию колодцев запрещено всем.', 0),
	(922, 'ruRU', 'Привет тебе...$B$BЧем могу помочь?', 0),
	(923, 'ruRU', 'Ты $Gбыл:была; у Родникового озера, $N? Удалось поохотиться там на древесников?', 0),
	(927, 'ruRU', 'О, $N! Ты что-то мне принесла?', 0),
	(928, 'ruRU', 'Привет тебе, |3-6($c). Чем обязан удовольствию встречи с тобой?', 0),
	(929, 'ruRU', 'С возвращением, $n. $GИсполнил:Исполнила; ли ты поручение?', 0),
	(930, 'ruRU', 'Похоже, ты что-то хочешь мне рассказать, $N? Ты что-то знаешь о древесниках?', 0),
	(931, 'ruRU', 'Ты что-то мне принесла?', 0),
	(932, 'ruRU', 'Ты еще не $Gубил:убила; лорда Меленаса? Необходимо убрать его быстро и тихо, $N. Его существование - угроза всем нам.', 0),
	(933, 'ruRU', 'Поначалу на донесения об обезумевших фурболгах не обращали внимания. Кто бы мог подумать, что эти миролюбивые людомедведи могут впасть в бешенство? Сколько еще бед должно свалиться на наши головы?', 0),
	(935, 'ruRU', 'Я не звал тебя, так что не понимаю, зачем ты $Gпришел:пришла; отвлекать меня разговорами.$b$bЧто бы там ни было, пожалуйста, побыстрее.', 0),
	(937, 'ruRU', 'Их безжалостные когти и острые клювы могут оказаться для тебя трудным испытанием, $N но я верю, что ты с честью выдержишь его.', 0),
	(938, 'ruRU', 'Туманна... Это бла моя вина! Ведьмы застали меня врасплох... Я не должна была позволить им ее у вас...', 0),
	(939, 'ruRU', 'Что такое, $C? У тебя встревоженный вид.', 0),
	(940, 'ruRU', 'Хм-м... В тебе силен дух леса, |3-6($c). Что у тебя за дело к верховному друиду калдорай?', 0),
	(941, 'ruRU', 'Кадка полна земли, специально подготовленной Деналаном.', 0),
	(942, 'ruRU', 'Что это там у вас, дружище?', 0),
	(943, 'ruRU', 'При помощи камня Релу я смогу раскрыть тайны моей окаменелости, а также и окаменелости Сомнамбулера с Темного Берега, $N.', 0),
	(947, 'ruRU', 'Вы еще не собрали грибов для меня, $N? В пещеру ходили?', 0),
	(950, 'ruRU', '$N. Ты вернулся.', 0),
	(951, 'ruRU', '$N. Ну что, удалось ли тебе что-то раскопать в руинах Матистры?', 0),
	(952, 'ruRU', 'А. $C. Чем может тебе помочь Ону?', 0),
	(953, 'ruRU', 'Когда вы изучите таблички и узнаете о падении Амет\'Арана, я пойду с этой информацией в Аубердин и сообщу Кругу Древних.', 0),
	(954, 'ruRU', 'Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнасе оценить ситуацию!', 0),
	(955, 'ruRU', 'Когда я получу серьги, я применю заклинание, чтобы обнаружить местонахождение связывающей меня печати. Веками я мечтал о свободе, которую принесло бы мне разрушение печати... Быть может, эти века таким грузом лежат на моем разуме, что я уже никогда не приду в себя...', 0),
	(956, 'ruRU', 'Столпы этого святилища для меня – тюремная решетка, $N. У меня нет сил их разрушить, и нет такой магии, чтобы сокрушить их...\n\nБольше тысячи лет я смотрю на них и думаю: если я переживу этот камень, буду ли я свободен? Или меня держит незримая решетка?', 0),
	(957, 'ruRU', 'По правде говоря, $n, я боюсь... Боюсь, что твой приход – и все это – лишь плод моего воспаленного воображения. Можешь ли ты понять, какая это мука? Я... Пожалуйста, ступай скорее.', 0),
	(958, 'ruRU', 'Если бы инструменты их гибели были разрушены во время катаклизма, уничтожевшего наш мир... Тем не менее мы должны сделать все возможное, чтобы ужасы нашего прошлого не повторились в будущем.', 0),
	(959, 'ruRU', 'Портовый начальник не дает мне покоя с тех пор, как Безумный Магглиш скрылся с этой бутылкой. Судя по всему, портвейн предназначался в подарок Газлоу самим бароном Ревилгазом. \n\nЕсли у тебя довольно смелости и терпения для поисков Безумного Магглиша и похищенного портвейна, я щедро награжу тебя.', 0),
	(962, 'ruRU', 'Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.', 0),
	(963, 'ruRU', 'С неизбывной печалью в сердце я последовал за Шан\'до Яростью Бури в долгий сон, и взял свою боль с собой в сны, и спал на протяжении тысячелетий.', 0),
	(966, 'ruRU', 'Нашли ли вы у них еще свитки? Я смогу составить более целостное представление об этом культе, если вы сможете их найти.', 0),
	(967, 'ruRU', 'У вас ко мне какое-то дело, |3-6($c)?', 0),
	(969, 'ruRU', 'Принеси мне кристаллы – и я расскажу больше тебе!', 0),
	(970, 'ruRU', 'Ну, как, удалось добыть самоцвет души?', 0),
	(971, 'ruRU', 'Долог путь до Ясеневого леса, и задача ваша нелегка. Но если вы доставите мне манускрипт, $N... Велика будет ваша награда.', 0),
	(973, 'ruRU', 'У тебя немного ошарашенный вид, $n. С тобой ничего не случилось?', 0),
	(974, 'ruRU', 'Я бы и сам пошел, но уж больно боюсь элементалей Огня!', 0),
	(977, 'ruRU', 'Я уже почти закончила прикреплять мех, $N. Пожалуйста, поскорее принеси мне рога, что я просила!', 0),
	(978, 'ruRU', 'И откуда только берется эта магия? Думаю, что мы на правильном пути к отысканию ответа, $N.', 0),
	(982, 'ruRU', 'Капитаны тех кораблей были славными ночными эльфами, и они заслужили лучшую участь, чем та, что им выпала. Может быть, внимание, проявленное к их личным ценностям, – наилучший способ позволить их душам обрести покой.', 0),
	(983, 'ruRU', 'Жужжалка 827 хранит зловещее молчание. Единственный мигающий индикатор показывает, что в приемник нужно поместить 6 ножек крабов.', 0),
	(984, 'ruRU', 'Как идут ваши поиски, $N?', 0),
	(985, 'ruRU', 'Не отдаляй руки своей от того, что должно быть сделано, дитя мое. Я знаю, какое омерзение внушает сама мысль об убийстве лесных созданий, но в данном случае – это необходимость. Никакого способа исцеления от этой скверны, отравившей лес, пока не нашлось, и мы должны сделать все возможное, чтобы остановить ее продвижение, пока средство не будет найдено.', 0),
	(986, 'ruRU', 'В здравом уме я не позволю вам идти искать Волкора, пока не сошью для вас тот плащ.', 0),
	(992, 'ruRU', 'Рад тебя видеть, младший геодезист $N! Ты уже $Gвыполнил:выполнила; задание?', 0),
	(996, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(997, 'ruRU', 'Ты что-то мне $Gпринес:принесла;?', 0),
	(998, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(1001, 'ruRU', 'Приемник машины открыт и, кажется, ждет, когда в него поместят 3 глаза крепкозуба.', 0),
	(1002, 'ruRU', 'Хотя вы еще не поместили внутрь Жужжалки клыки лунопардов, вам кажется, что оттуда раздаются звуки статических разрядов и невнятное гномье бормотание. Может быть, кто-то уже успел починить машину?', 0),
	(1003, 'ruRU', 'Вы слышите пение, раздающееся из Жужжалки 525.$B$B Хотя изшшш крабов сладкое винннцо, из млатозшшшуба эль хоть куда, и сшшшамогонка лунная вкусна, но нет ничшшего лучше пива медвежшшшьего, и сшшшкоро будет оно у меня! $B$BЗаслонка открыта и ждет добытых вами 4 седых скальпов, а песенка звучит снова и снова.', 0),
	(1007, 'ruRU', 'Ты $Gснашел:нашла; статуэтку, $N?', 0),
	(1008, 'ruRU', 'Мы не можем допустить, чтобы наги наводнили наше побережье, $N. Жизненно важно, чтобы ты $Gотправился:отправилась; на Зорамское взморье, дабы довершить свое дело.', 0),
	(1009, 'ruRU', 'Говорят, что кольцо Зорама является ключом к любому замку в этом городе. Ты $Gдобыл:добыла; его, $N?', 0),
	(1010, 'ruRU', 'Ты $Gдобыл:добыла; Батранов волос, $N? Ребенок слабеет с каждым часом...', 0),
	(1011, 'ruRU', 'Ты нашел лагерь $N? добыл бутыль заразы?', 0),
	(1013, 'ruRU', 'Нашел книгу, $N?', 0),
	(1014, 'ruRU', 'Со смертью Аругала мы сможем укрепить власть Темной Госпожи в Лордероне.', 0),
	(1016, 'ruRU', 'Поскольку тебе придется разрушить браслеты, чтобы убить элементалей, наверное трудно будет найти те самые, в которых содержится информация, которая нужна для гадального свитка. Ты можешь выменять нужные тебе браслеты у кого-нибудь другого, но, может, у тебя есть уже разгаданный свиток?', 0),
	(1017, 'ruRU', 'Дело сделано? Сарилус Грязнорожденный мертв?', 0),
	(1020, 'ruRU', 'Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!', 0),
	(1023, 'ruRU', 'Добро пожаловать, $N.', 0),
	(1024, 'ruRU', 'Здравствуй. Как поживаешь?', 0),
	(1026, 'ruRU', 'Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.', 0),
	(1027, 'ruRU', 'Ты нашел последний фрагмент жезла, $N?', 0),
	(1028, 'ruRU', 'Вы ощущаете ненавязчивую, но мощную силу в святилище и окружающих деревьях.$B$BВы кладете жезл в святилище, и вас окутывает тихий звон, а святилище начинает светиться...', 0),
	(1031, 'ruRU', 'Ты нашел их? Что сказала Анилия? Где она?', 0),
	(1032, 'ruRU', 'Пожалуйста, помоги мне отомстить за смерть Анилии.', 0),
	(1033, 'ruRU', '$N, ты $Gнашел:нашла; озеро Ирис? Ты $Gпринес:принесла; Слезу?', 0),
	(1034, 'ruRU', 'Ты уже принес звездную пыль, $N?', 0),
	(1035, 'ruRU', 'Ты сразился с Чащобным Оракулом, $N? Если так, до дай мне, пожалуйста, лунный камень. Релара при последнем издыхании!', 0),
	(1038, 'ruRU', 'Что удалось найти?', 0),
	(1046, 'ruRU', 'Часовые здесь, в Ясеневом лесу, делают что могут, но лишь благодаря таким |3-6($r)ям как ты, мы не сдаем своих позиций.', 0),
	(1048, 'ruRU', 'Я считаю, что для выживания в этом мире нужно помнить только одно правило: чем больше знаешь, тем больше видишь.\n\nУчись, наблюдай, и тогда разглядишь то, чего никто другой не увидит |3-6($R).', 0),
	(1049, 'ruRU', 'Кэрн – отважный и благородный вождь, и я доверил бы ему свою жизнь. Но есть и те, кому я в нынешние времена нипочем бы не доверился.\n\nКак только смогу собрать все возможные сведения, я сумею дать вождю небезосновательный совет.\n\nТебе удалось добраться до Тирисфальских лесов? Удалось проникнуть в Монастырь Алого ордена? "Компендиум павших" – лишь кусочек сложной мозаики...', 0),
	(1050, 'ruRU', 'Этот монастырь был духовной школой паладинов. Некогда он был цитаделью Света, а теперь попал в руки безумных фанатиков Алого ордена.$B$BОни считают, что у них благородная цель – очистить землю от нежити. Но безумие запятнало их деяния, и ныне они враги всем.$B$BПринеси мне "Мифологию Титанов", чтобы я могла изучить эту книгу. Я буду хранить ее здесь, в Стальгорне.$B$BОскверненные стены монастыря – не место для такого исторического сокровища.', 0),
	(1052, 'ruRU', 'Кто идет? Что вам от меня надо?', 0),
	(1054, 'ruRU', 'Из-за этой фурболгской заразы дни славы Ясеневого леса остались далеко в прошлом.', 0),
	(1058, 'ruRU', 'Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!', 0),
	(1060, 'ruRU', 'На вид ты темная личность. Ты хочешь мне что-то показать?', 0),
	(1062, 'ruRU', 'У тебя какие-то новости от землепряда Магграна?', 0),
	(1065, 'ruRU', 'Ага, вы доставили мне новых подопытных?', 0),
	(1066, 'ruRU', 'Тебе удалось найти темных магов Синдиката и принести кровь невинных?', 0),
	(1067, 'ruRU', 'Ты вернулся, $N. Аптекарь Лидон пришел к нам на подмогу?', 0),
	(1068, 'ruRU', 'Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.', 0),
	(1069, 'ruRU', 'Принес яйца, $N? Я уже заключил договор о транспортировке с управляющим пристанью Головокружилкинсом.', 0),
	(1073, 'ruRU', 'Я не могу сделать нитромирглицероний без этих зелий... они жизненно важны для его создания.', 0),
	(1074, 'ruRU', 'А, славно, славно, с возвращением.', 0),
	(1076, 'ruRU', 'Привет, $N. Тебе удалось найти нужный мне компонент?', 0),
	(1077, 'ruRU', 'Хо-хо, ты уже обратно? У тебя оно есть? Заклинание, в смысле?', 0),
	(1078, 'ruRU', 'И еще раз привет тебе, $N.$B$BТебе удалось побывать в той долине в Каменном Когте и добыть чешую?', 0),
	(1079, 'ruRU', 'Тебе удалось раздобыть чертежи, $N?', 0),
	(1080, 'ruRU', 'Ну и как дела, $N?', 0),
	(1088, 'ruRU', 'Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.', 0),
	(1089, 'ruRU', 'Три замочных скважины вырезаны в камне.', 0),
	(1091, 'ruRU', 'Да, $N? Какое у тебя ко мне дело?', 0),
	(1092, 'ruRU', 'Что это? Я могу помочь тебе?', 0),
	(1093, 'ruRU', 'Тебе удалось добыть чертежи? Я хочу порадовать нового начальника. Надеюсь, как только он убедится в моей верности – ну, насколько его вообще можно убедить... гоблинский гонор, и все такое... – он найдет достойное применение моему гениальному уму.', 0),
	(1094, 'ruRU', 'Эй, привет! Чем могу быть полезен?', 0),
	(1095, 'ruRU', 'Духи деревьев плачут по своим погибшим собратьям, $N. Тебе нужно уничтожить шреддеры XT:4 и XT:9, иначе, я боюсь, Каменный Коготь никогда не оправится от этого ужаса.', 0),
	(1096, 'ruRU', 'Паровой Клапан потребует какое-нибудь доказательство того, что Геренцо мертв. Полагаю, его механическая рука вполне сгодится.', 0),
	(1102, 'ruRU', 'Как только я узнаю, что грязные твари Лабиринтов Иглошкурых изгнаны из их мерзкого логова, я упокоюсь с миром, зная, что месть свершилась.\n\nТы изгнал этих игрогривов из Лабиринтов? И подтвердишь свою весть, показав мне сердце этой ведьмы?', 0),
	(1104, 'ruRU', 'Привет-привет! Ну, где же яд?', 0),
	(1105, 'ruRU', 'Мой брат разрабатывает новое топливо, и это меня немного беспокоит... Мне нужно как можно быстрее сделать новый топливный бак!\n\n$N, тебе удалось добыть черепашьи панцири?', 0),
	(1106, 'ruRU', 'Что ж, вы нашли меня. Поздравляю.$B$BВы насчет топора, который я сделал для Гат\'Илзогга? Или пришли защитить честь герцогини Пемей?$B$BА хотя какая разница... Если вы пришли драться со мной, то давайте скорее с этим покончим.', 0),
	(1107, 'ruRU', 'Эй, где там мои плавники? Если не защитить машину от ее же собственной скорости, долго она тут не протянет!', 0),
	(1108, 'ruRU', 'Ну как, $N, удалось добыть немного индарилия? Я тут уже свой горн раскочегарил, можно начинать плавить.', 0),
	(1109, 'ruRU', 'Вижу, ты вернулся. Удалось добыть гуано летучих мышей?', 0),
	(1110, 'ruRU', '$N, вы уже были на равнинах? Нашли какие-нибудь детали, которые я просил?', 0),
	(1111, 'ruRU', 'Следующий! Так, ты отправитель или получатель?', 0),
	(1112, 'ruRU', 'Вы уже забрали части из Кабестана?', 0),
	(1113, 'ruRU', 'Ты уже вернулся из Монастыря Алого ордена? Для этого восхитительного эксперимента мне понадобится много сердец!\n\nНе сомневаюсь, Вариматас и Темная Госпожа будут рады, избавившись от алого сброда.', 0),
	(1114, 'ruRU', 'Принес мне что-нибудь? Здорово! Ну-ка, посмотрим...', 0),
	(1116, 'ruRU', 'Уже вернулись? И сонная пыль у вас есть?', 0),
	(1118, 'ruRU', 'Здрасьте-здрасьте. Что $Gтакой:такая; $Gблагородный:благородная; $C делает в Пиратской бухте?', 0),
	(1119, 'ruRU', 'Привет, $N. Кранк Шипучка согласился нам помочь?', 0),
	(1120, 'ruRU', 'Привет! Есть что-нибудь для меня?', 0),
	(1121, 'ruRU', 'На что $Gуставился:уставилась;?', 0),
	(1122, 'ruRU', 'Здравствуйте, $N. Ну, как там сработала моя выпивка? Забористая штука, да?', 0),
	(1124, 'ruRU', 'Эти земли не прощают беспечности, $C). Что привело тебя в пустоши Силитуса?', 0),
	(1130, 'ruRU', 'Меня преследуют воспоминания о моих кошмарах, $N. Удалось ли тебе убить отступников и завладеть их кристаллами?', 0),
	(1131, 'ruRU', 'Вы убили злобного Сталезуба, $N?', 0),
	(1134, 'ruRU', 'Тебе удалось добыть ядовитые железы величавых виверн, $N? Мы не можем позволить оркам использовать яд этих тварей против нас!', 0),
	(1138, 'ruRU', '...краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый сюрприз. Вот и... ну, и все.', 0),
	(1141, 'ruRU', 'Из окуней с Темных берегов можно приготовить множество вкусных блюд. Окуни хороши на вкус, но ловить их, я думаю, еще приятнее.$B$BТы еще не наловил окуньков?', 0),
	(1142, 'ruRU', 'Что привело тебя ко мне, |3-6($r)?', 0),
	(1143, 'ruRU', 'Атрикус Нарассин – древний и могущественный чернокнижник. Может быть, нам стоило бы подождать, пока сам Делгрен не придет на помощь, но он, очевидно, очень сильно верит в вас, раз уж послал вас в одиночку.', 0),
	(1145, 'ruRU', 'Я завидую вам, |3-6($C). Похоже, вы давно не бывали в Оргриммаре...\n\nЯ бы и сам отправился в путешествие, во славу Вождя, но Траллу я нужен здесь. Однако он очень мудрый правитель, и я верю ему. Я готов оставаться здесь столько, сколько буду ему нужен.', 0),
	(1146, 'ruRU', 'Нас привела на Мерцающую равнину война. А что привело вас сюда, $N?', 0),
	(1148, 'ruRU', 'Ага, давненько ты ко мне не заглядывал, $N. Чем я могу тебе помочь? Похоже, на тебе еще не обсохла кровь врагов? Это хорошо. Хорошо и для вас, и для Орды, потому что чем больше битв вы пройдете, тем сильнее станете.', 0),
	(1149, 'ruRU', 'Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?', 0),
	(1150, 'ruRU', 'Чтобы пройти все назначенные испытания, ты должен подготовиться морально, духовно и физически.\n\nМы слишком часто рвемся вперед неподготовленными. Я считаю своим долгом подготовить всех новичков, которые приходят ко мне, вне зависимости от их племени. Они должны знать, с чем им предстоит столкнуться за порогом родного дома.', 0),
	(1151, 'ruRU', 'Племена кентавров зовут Рок\'Алима Крушителем – из-за грохота, который издают его кулаки, которые он обрушивает на тех, кто достаточно смел или глуп для того, чтобы оказаться у него на пути.', 0),
	(1152, 'ruRU', 'О, привет еще раз, $N. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя в форт?', 0),
	(1153, 'ruRU', 'Потом я встретился с путешественниками снова – с теми самыми, что не продали мне образец руды. Я плюнул в них за то, что они не стали помогать вождю.\n\nПусть они умрут в бою как трусы, а не как благородные воины, вставшие на сторону Орды.', 0),
	(1154, 'ruRU', 'Принеси мне книгу, когда прочитаешь ее. До этого я не буду задавать тебе вопросов.', 0),
	(1160, 'ruRU', 'Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.', 0),
	(1164, 'ruRU', 'Убей их и принеси мне головы!', 0),
	(1175, 'ruRU', 'Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.', 0),
	(1176, 'ruRU', 'Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.', 0),
	(1178, 'ruRU', 'Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.', 0),
	(1179, 'ruRU', 'Смотри куда прешь! Эй, эй, эй! Тут все хрупкое и важное, не вздумай ничего портить, а то мы не выиграем гонку!', 0),
	(1182, 'ruRU', 'Мне не хочется это признавать, но гномская команда очень сильная. Нашим ребятам надо дать пинка, чтобы шевелились.', 0),
	(1183, 'ruRU', '$N! Удалось ли отыскать топливный регулятор?', 0),
	(1186, 'ruRU', '$N! Удалось ли отыскать топливный регулятор?', 0),
	(1187, 'ruRU', 'И как мне показаться на треке, если у меня нет никакого ускорителя? Это ж ерунда какая-то!', 0),
	(1188, 'ruRU', 'Знаете, в Гизмориуме есть все для починки любых механизмов! Чем могу помочь?', 0),
	(1189, 'ruRU', 'Ты представляешь, Поззик подсунул мне в болид ведро с песком! Как я могу выжать максимальную скорость, если у меня под сиденьем целое ведро песка?', 0),
	(1192, 'ruRU', 'Я хотел бы использовать индарилий в разных частях наших болидов, но сначала мне нужно создать эти части из большого количества этого материала.$B$BИндарилиевую руду можно найти в Ульдамане – это в Бесплодных землях, на другом берегу моря в Каз Модане.$B$BГномы то и дело получают поставки индарилия, так что нам надо не отставать.', 0),
	(1195, 'ruRU', 'Как только у нас будет наполненный фиал, мы отправим его моему помощнику, Рау, в Тысячу Игл. Он-то и просил фиал этой воды, так что ему лучше знать, что с ней делать.', 0),
	(1196, 'ruRU', 'Хм, неужто тебя послал Занген?', 0),
	(1197, 'ruRU', 'Жду не дождусь, когда смогу получить это раздвоенное копыто. Вы уже добыли его?', 0),
	(1199, 'ruRU', 'В Непроглядной Пучине некогда был древний храм ночных эльфов. Одно время там находился самый мощный лунный колодец. Кто знает, какое зло ныне клубится там, когда храм в руках Сумеречного Молота?$B$BУдалось ли тебе проредить их ряды?', 0),
	(1200, 'ruRU', 'Время дорого, $C. $B$BМоя задача в Дарнассе – обеспечить процветание Серебряного Рассвета и поражение злых сил, вторгшихся в Калимдор. $B$BГовори, зачем пришел или уходи.', 0),
	(1204, 'ruRU', 'Ну как? Удалось добыть необходимые мне языки?', 0),
	(1205, 'ruRU', 'Ты добыл зуб Зыбуна, $N? Удалось ли тебе прекратить страдания этого существа?', 0),
	(1221, 'ruRU', 'Ну что, принес корни, $N?', 0),
	(1239, 'ruRU', 'У тебя для меня еще что-то есть, $N?', 0),
	(1240, 'ruRU', 'Рядом с тобой вьется очень сердитый дух, брат. Что привело тебя к Кин\'вилаю?', 0),
	(1241, 'ruRU', 'Хм-м, ну, надеюсь, у вас есть действительно достойный повод оторвать меня от рыбалки. Я не подаю нищим и не покупаю ничего у разносчиков...', 0),
	(1242, 'ruRU', 'Здравствуйте, $N. Могу ли я чем-нибудь вам помочь? Не хотите ли отведать "Чеддер Триаса"? Или кусочек "Дарнассийского блю"?', 0),
	(1243, 'ruRU', 'По этим лесам путешествовать небезопасно, $N. Будьте осторожны, и если приметите опасность – немедленно обращайтесь к Смотрящим. Не пытайтесь разобраться самостоятельно. Иначе помощь может прийти слишком поздно...$B$BВпрочем, мы оба знаем, что вы плюнете на мои предупреждения и будете сражаться со всем, что выползет из сумерек, верно? Я знаю таких, как вы – настоящих приключенцев...', 0),
	(1244, 'ruRU', 'Будьте осторожнее, $N. Хоть вас и прислал сюда Триас, но это не значит, что все чудовища из чащоб будут к вам благосклонны. Особенно учитывая, что ваше расследование связано с Братством Справедливости.', 0),
	(1245, 'ruRU', 'Ой, да вы вернулись, и целиком, а не кусками в посылке! Разумеется, вы не за сыром явились, так давайте сразу перейдем к делу! Помог ли вам Бакус, или в Сумеречном лесу вы ничего не нашли?', 0),
	(1251, 'ruRU', 'Что это у тебя там, $N? Вещественное доказательство с руин "Последнего привала"?', 0),
	(1261, 'ruRU', 'Ты выяснил, что случилось с Маргом?', 0),
	(1268, 'ruRU', 'Что это у тебя там, $N? Вещественное доказательство с руин "Последнего привала"?', 0),
	(1269, 'ruRU', 'Удалось найти хоть какие-то намеки на то. Что случилось в таверне "Последний привал"?', 0),
	(1275, 'ruRU', 'Когда у меня будет достачно образцов для изучения, я смогу начать настоящее исследование. Имея оскверненные стволы мозга как сатиров, так и нагов из Непроглядной Пучины, я смогу сопоставить их мутации.$B$BБыть может, полученные знания помогут нам не допустить окончательного перехода на сторону зла эльфов крови.', 0),
	(1321, 'ruRU', 'Что это у тебя тут, |3-6($C)?', 0),
	(1322, 'ruRU', 'Ты добыл яд этих пауков?', 0),
	(1338, 'ruRU', 'Письмо из дворфийских земель? Интересно, кто это пишет мне из такой дали…$B$BПозволь взглянуть на заказ.', 0),
	(1358, 'ruRU', 'У вас есть для меня посылочка?', 0),
	(1359, 'ruRU', 'Вы мне что-то принесли?', 0),
	(1360, 'ruRU', 'Ну, тебе удалось надавать этим троггам и добраться до моего сундука?', 0),
	(1361, 'ruRU', 'Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!', 0),
	(1364, 'ruRU', 'Что привело вас в Крепость Стражей Пустоты, |3-6($C)?', 0),
	(1365, 'ruRU', 'Ну что, $N, удалось тебе одолеть Дез\'хепа?', 0),
	(1366, 'ruRU', 'Как идет добыча ушей, $N? Много нарезал?', 0),
	(1387, 'ruRU', 'Тебе есть что сообщить, $N?', 0),
	(1392, 'ruRU', 'Приветствую. И добро пожаловать в Убежище!', 0),
	(1393, 'ruRU', 'Это нелегкая задача, $N. Не сдавайся!', 0),
	(1395, 'ruRU', 'Приветствую! Не обращай внимания на всю эту суматоху, это обычное дело в Крепости Стражей Пустоты.$B$BУ тебя что-то для меня есть?', 0),
	(1423, 'ruRU', 'У тебя что-то есть для меня?', 0),
	(1431, 'ruRU', 'Мы охотно приняли бы в дар шерстяную ткань. Если ты дашь нам 60 отрезов, Оргриммар будет тебе чрезвычайно признателен за щедрость. 60 отрезов нам вполне бы хватило – вместе с дарами от прочих пожертвователей этого было бы достаточно, чтобы продолжать работу.\n\nЕсли у тебя при себе имеется 60 отрезов шерсти и ты готов ее пожертвовать, я могу ее принять прямо сейчас.', 0),
	(1433, 'ruRU', 'Спутник-таурен предупредил меня, что сатиры – не совсем то, чем кажутся. Он считает, что зло в них исказило их истинную природу. Но сам я такого не видел.\n\nЯ вижу только, как они безжалостно убивают слабых и оскверняют души тех, кто обращается к темным силам.\n\nИ я буду уничтожать их, пока вождь не поручит мне другое дело. Жалости к ним я не испытываю.', 0),
	(1434, 'ruRU', 'Что у вас за новости, |3-6($C)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!', 0),
	(1439, 'ruRU', 'Боюсь, Тиранис попытается узнать тайны Пылающего Клинка и стать одним из них, если, конечно, они это позволят. Его всегда восхищала та власть, которую дает магия – и никогда он не думал о цене этой власти...$B$BНе знаю, как мне вернуться к семье, когда душа Тираниса подвергается такой опасности... Наш народ считает преступлением даже изучение подобной магии, а уж если Тиранис преобразится в одно из тех существ, с которыми му ведем войну...', 0),
	(1442, 'ruRU', 'Я с трудом поверил бы в чистые намерения того, кто ищет самоцвет Кора, не будь это искатель святого пути. Но таким, как вы, я доверяю даже больше, чем собственным сородичам. И я не стану судить о вашем ордене по деяниям ваших падших собратьев.', 0),
	(1446, 'ruRU', 'Теперь, когда Джаммал\'ана нет, у меня появилась возможность вернуться к своему народу.$B$BС таким духовным лидером, как Джаммал\'ан, племя Атал\'ай было обречено.', 0),
	(1452, 'ruRU', 'Пробовали болтливое пиво? Один из моих любимых сортов, надо сказать... Ик!$B$BНо если вы хотите, чтобы я вспомнил все детали того... ик... душераздирающего полета, потребуется что-то покрепче, и-ик, да...$B$BМне так представляется, что потрошка и печенки вы мне не торопитесь нести?$B$BИк!', 0),
	(1456, 'ruRU', 'Не знаю уж, кем там был этот Ниджел, но что в его лагере я провел самую паршивую ночь в своей жизни, это точно, уж можешь мне поверить, $N.', 0),
	(1457, 'ruRU', 'Слушай, $N, дела идут полным ходом, деньги крутятся, так что мне не до болтовни. Оно, конечно, если у тебя что-то есть к Горной корпорации, тогда отойдем, поговорим, а если нет, то лучше пудри мозги кому-нибудь из моих подчиненных – они тебе ответят на все вопросы, только оставь меня в покое!', 0),
	(1458, 'ruRU', 'Отвратные они твари, эти сатиры, точно? Поговаривают, что они как-то связаны с ночными эльфами, но мне в это как-то не слишком верится.$B$BСдается мне, эти слухи пошли из-за того, что один эльф несколько лет назад втянул их в войну. После этой войны весь мир поменялся. Опаснее стал, да и страшнее тоже...', 0),
	(1459, 'ruRU', 'Ты уж извини, что я тебе не сказал, где искать скорпионов и кодо. Я здешние места не особо знаю, да и времени у меня не было все тут обследовать...', 0),
	(1466, 'ruRU', 'Я даже и представить себе не мог, что все эти демонические твари обитают тут, в Пустошах. Мне все как-то казалось, что после ухода эльфов тут кентавры живут...$B$BИнтересно, как здесь эти твари оказались и чего им тут надо?', 0),
	(1467, 'ruRU', 'Рад тебя видеть, $N. Бизнес процветает, Молоты звенят по наковальням, меха раздувают огонь, а моя жена готовит мне пирог на десерт... Жизнь прекрасна, не так ли?', 0),
	(1469, 'ruRU', 'Наконец-то вы вернулись, $N! Давненько мы не виделись, я было подумал, что вы забыли о моем поручении...$B$BВы нашли этого хитроумного всадника на грифоне? Он что-нибудь сказал?', 0),
	(1470, 'ruRU', 'Твои силы пока малы, но мне кажется, что ты уже начинаешь ощущать скрытые возможности. \n\nДаже мертвый может почувствовать себя живым, когда эта сила циркулирует в нас.', 0),
	(1478, 'ruRU', 'Я полагаю, ты уже собрал достаточно погибельника?', 0),
	(1479, 'ruRU', 'Разве мы уже там?', 0),
	(1485, 'ruRU', 'Важно уметь контролировать существ, которых ты будешь призывать с помощью магии. Интересующихся ремеслом чернокнижников и так мало, поэтому я не позволю тебе рисковать жизнью прежде, чем увижу, что ты к этому готов.', 0),
	(1486, 'ruRU', 'Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6($C)?', 0),
	(1489, 'ruRU', 'Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.', 0),
	(1490, 'ruRU', 'Могу я тебе чем-то помочь?', 0),
	(1491, 'ruRU', 'Где моя воющая субстанция?', 0),
	(1492, 'ruRU', 'Желаешь отплыть на ближайшем корабле или послать товар на ту сторону света?', 0),
	(1499, 'ruRU', 'Ты слышал приказ, $N. Речь идет о безопасности Дуротара! Выполняй свою задачу – либо уходи с позором.\n\nПокажи свою доблесть, выбей людей из крепости Тирагард!', 0),
	(1501, 'ruRU', 'Ну что, $N, табличка Верги у тебя? Пока ты ее не добудешь, я с тобой и разговаривать не стану!', 0),
	(1504, 'ruRU', 'Демон Бездны – создание могущественное! Я помню, как боролся с ним, когда был в твоем возрасте, $N. С годами мой демон стал меньше сопротивляться – но подозреваю, он просто надеется, что я утрачу бдительность.\n\nНе забывай этого, $N!', 0),
	(1506, 'ruRU', 'Ну что, $N, удалось тебе проникнуть в Скалу Черепа? Принес обжигающие ошейники?', 0),
	(1507, 'ruRU', 'Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!', 0),
	(1508, 'ruRU', 'Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!', 0),
	(1510, 'ruRU', 'Долина Высокого леса лежит к северо-западу отсюда. Иди, $N. Всели страх в сердца тех, кто разоряет эти земли!', 0),
	(1511, 'ruRU', 'Да, чего тебе?', 0),
	(1512, 'ruRU', 'А, вот и ты! Ну что, готов встретиться с суккубом?', 0),
	(1513, 'ruRU', 'Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!', 0),
	(1514, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(1515, 'ruRU', 'Ууф-ф...', 0),
	(1518, 'ruRU', 'Я хочу быть первым, кто поприветствует тебя на первом из четырех путей, которые поведут тебя на встечу судьбе.$B$BЕсли у тебя есть камень, дарованный землей, я дам тебе тотем, который она обещала.$B$BЕсли нет, ступай, пока не найдешь свой путь. ', 0),
	(1528, 'ruRU', 'Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.', 0),
	(1530, 'ruRU', 'Тебе удалось добраться до гнезд?', 0),
	(1535, 'ruRU', 'Я готова дать тебе следующее задание. Ты уже наполнила бурдюк?\n\nЯ знаю, как ревниво иглогривы относятся к водопоям. Ведь даже малый источник для них – настоящее сокровище. Они устраивают пир, если Степи осчастливит хоть небольшой дождь. Вода для них священна, ведь здесь ее очень мало. Ясно?', 0),
	(1558, 'ruRU', 'Разве мы уже там?', 0),
	(1560, 'ruRU', 'Где Туга?', 0),
	(1579, 'ruRU', 'Нашел мои суперразъемы, $N? Без этих суперразъемов я не могу приспособить шатуны!', 0),
	(1580, 'ruRU', 'Ну как, нашел хоть один электропеллер? Они нужны мне, чтобы продолжить мои ислледования о подсадных утках...', 0),
	(1581, 'ruRU', 'Ну, привет тебе, $N. Привезла эликсиров на продажу?', 0),
	(1598, 'ruRU', 'Было бы слишком опасно самой пытаться украсть эту книгу из аббатства. Какая удача, что этот простофиля сделал всю грязную работу за меня!', 0),
	(1640, 'ruRU', 'Эту кружку ты получишь только через мой труп...', 0),
	(1654, 'ruRU', 'Предметы эти нелегко добыть, но, смею тебя заверить, оружие, которое я для тебя сделаю, сторицей окупит твои труды.$B$BЭто будет лучшая моя работа и лишь малая награда за все, что ты сделал для меня.', 0),
	(1655, 'ruRU', 'Ну, что, удалось? Огры получили от тебя по полной, да?', 0),
	(1656, 'ruRU', 'Yes, young one? What can Kauth do for you?$B$BThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?', 0),
	(1665, 'ruRU', 'Я наблюдал за твоей дракой с Бартлби. Неплохо! Удалось отобрать кружку?', 0),
	(1667, 'ruRU', 'Мой знак у тебя? Страшно подумать, какие преступления может совершить Джек с его помощью.', 0),
	(1678, 'ruRU', 'Ты уже $gпобывал:побывала; в хижине Веджрека, $N? От тебя, часом, не троллем воняет?', 0),
	(1681, 'ruRU', 'Тебе удалось пробраться в поселок Сталекрута? А мрачная руда у тебя?', 0),
	(1687, 'ruRU', 'Разве мы уже там?', 0),
	(1690, 'ruRU', 'Так быстро $gвернулся:вернулась;? Надеюсь, ты $Gсумел:сумела; навести справедливость по-гоблински над бандитами и ворами Скитальцев Пустыни, как я тебя просил!', 0),
	(1691, 'ruRU', 'Ну что, удалось одолеть кочевников, о которых я говорил? Все планы Водной компании Прибамбасска зависят от твоего успеха! Не подведи нас...', 0),
	(1699, 'ruRU', 'Ты теряешь время, $N. На твоем месте я бы поторопился.', 0),
	(1702, 'ruRU', 'Привет! Меня мучает жажда, а тебя?', 0),
	(1707, 'ruRU', 'Ты $Gпринёс:принесла; все пять бурдюков? Если да, то лечебный набор Водной компании Прибамбасска, модель 103-ХВ, твой!', 0),
	(1740, 'ruRU', 'Мне понадобилось много лет, чтобы собрать все части сферы Заргейна, но она служит мне верой и правдой, как будет служить тебе шар Соран\'рука', 0),
	(1796, 'ruRU', 'Как идут поиски одеяния, $N? Удалось создать его самостоятельно? Когда делаешь что-то сам, куда приятнее наполнять этот предмет магией. Получаешь большее удовлетворение. Но я пойму, если ты предпочтешь более легкий путь – заказать одеяние. Подобная... целеустремленность тоже хороша.', 0),
	(1799, 'ruRU', 'Ты явно не маг, и я не уверена, что тебе можно доверять. Я ощущаю в тебе колдовскую силу, но кажется, тебя не затронула скверна, столь легко берущая верх над вашим братом.\n\nДа, |3-6($C)… |3-6($C) пришел просить меня о помощи.\n\nИтак, что тебе нужно, $N?', 0),
	(1803, 'ruRU', 'Может быть, фолиант Заговора и упоминался в сказках, но даже в самых невероятных историях есть доля правды.', 0),
	(1878, 'ruRU', 'Опять ты здесь? Если ты несешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!', 0),
	(1885, 'ruRU', 'Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!', 0),
	(1886, 'ruRU', 'Пришел доложить об успехе?', 0),
	(1898, 'ruRU', 'Добрый день. Чем могу помочь?', 0),
	(1899, 'ruRU', 'Как твои успехи?', 0),
	(1918, 'ruRU', 'Да, в чем дело?', 0),
	(1978, 'ruRU', 'Да?', 0),
	(1998, 'ruRU', 'Я целиком положился на тебя. Выполни распоряжение лорда Вариматаса.', 0),
	(2038, 'ruRU', '$N! Где мои вещи?!', 0),
	(2078, 'ruRU', 'И где есть мой первый помощник, $N? Пойдешь на корм акулам, если не поторопишься!', 0),
	(2098, 'ruRU', 'Эй, $gсухопутник:сухопутница;, еще не нашелся мой сломанный ключ?', 0),
	(2118, 'ruRU', 'Вы привели ко мне больного зверя, $N?$B$BЕсли вам не удалось захлопнуть ловушку, не беспокойтесь - надежда Тарнариуна живет вечно. Если вам нужна еще одна ловушка, отмените ваше задание и вновь обратитесь ко мне.', 0),
	(2138, 'ruRU', 'Задание выполнено?', 0),
	(2139, 'ruRU', 'Когда зараженная злом мать-медведица будет убита, количество бродящих по нашей земле бешеных колючешерстных медведей уменьшится. Не теряйте времени, $N.', 0),
	(2158, 'ruRU', 'Ну, добыла мне банданы?', 0),
	(2159, 'ruRU', 'Чем я могу тебе помочь, $Gюноша:девица;? Желаешь отдохнуть на постоялом дворе? Или тебе нужен камень возвращения?', 0),
	(2160, 'ruRU', 'А, привет-привет! Заходи, садись у огня: тут и согреешься, и доброго эля выпьешь, с дороги-то...', 0),
	(2161, 'ruRU', 'Добро пожаловать в Колючий Холм!', 0),
	(2178, 'ruRU', 'Мой горшок пуст, а я проголодалась! Что ж вы так долго?', 0),
	(2198, 'ruRU', 'Ты ошибся гномом, приятель! Меня там и близко не было. Ты ничего не докажешь!$B$BПодожди, а тебе вообще, чего надо??? Что за... Где ты это взял?', 0),
	(2199, 'ruRU', 'Ты принес мне пять серебряных слитков, как я просил? Я поделюсь с тобой моей печальной повестью об ожерелье, коим ты ныне владеешь... Но только после того, как я получу слитки! Неужели ты не поможешь бедному гному?', 0),
	(2201, 'ruRU', 'Образ Талваша появляется на поверхности воды в чаше.$B$B"Ого! Да ты еще жив! Удалось ли тебе найти камни? Я так надеюсь, что тебе удастся спасти мою репутацию. Умоляю тебя, скажи, что ты не терял времени даром и вызываешь меня не для того, чтобы просто поболтать. Подобные сеансы стоят недешево, а я сейчас весьма стеснен в средствах."', 0),
	(2204, 'ruRU', 'Ты не останавливался даже чтобы привести себя в порядок после Ульдамана, так ведь? Пришел прямо сюда благоухая подземельными ароматами. Что ж будем надеяться, что все эти жертвы были принесены не напрасно.$B$BУдалось тебе добыть источник силы для ожерелья?', 0),
	(2206, 'ruRU', 'С каждой минутой, что вы ошиваетесь тут, в казармах, ваша жизнь становится короче на 60 секунд.', 0),
	(2241, 'ruRU', 'Какая прелесть! Ты принесла цветочки на собственную могилу!', 0),
	(2242, 'ruRU', 'Ну так что там у Сефира Древнего обнаружилось, $N?', 0),
	(2279, 'ruRU', 'Да, могу я вам чем-нибудь помочь? Я, вообще-то занят, в настоящий момент, делом, которое представляет немалую важность для всей Лиги. Но я весь внимание.', 0),
	(2282, 'ruRU', 'Я забыл предупредить тебя насчет орков?$B$BГоворят, в последнее время они все время толкутся вокруг мельницы.', 0),
	(2381, 'ruRU', 'Что ж, по крайней мере, ты пока цел. А сокровище нашел?', 0),
	(2382, 'ruRU', 'У вас есть для меня посылочка?', 0),
	(2383, 'ruRU', 'Что у тебя там? Пергамент? Ты что, $gграмотный:грамотная;?', 0),
	(2418, 'ruRU', 'Ну, что там с камнями? Мне нужен источник питания для моей механической мышки...', 0),
	(2438, 'ruRU', 'Прошу, быстрее. Могу лишь надеяться, что фурболги не повредили моего ловца снов.$B$BТы еще не $Gдобыл:добыла; его, $N?', 0),
	(2439, 'ruRU', 'Добро пожаловать в хранилище Стальгорна, $N. Чем могу помочь?', 0),
	(2459, 'ruRU', 'Пусть Фероситас и эти мистики Кривой Сосны вернут то, что принадлежит мне! Прошу тебя, отними у них изумруд, чтобы я мог восстановить своего ловца снов.', 0),
	(2498, 'ruRU', 'Ну так что там у Сефира Древнего обнаружилось, $N?', 0),
	(2499, 'ruRU', 'Тебе удалось найти Дубохмура, |3-6($R)?', 0),
	(2500, 'ruRU', 'Ты принес все необходимое? Пока не принесешь, платить не буду.', 0),
	(2518, 'ruRU', 'В великой печали даю я тебе это поручение, но у нас нет надежды исцелить леди Сатру.$B$BМы надеемся, что если принести серебряные паутинные железы в жертву Элуне, то она благословит Сатру, и та возродится с покоем в душе.', 0),
	(2519, 'ruRU', 'Ну так что там у Сефира Древнего обнаружилось, $N?', 0),
	(2520, 'ruRU', 'Ты $Gоставил:оставила; жертву у фонтана, $N?', 0),
	(2523, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(2541, 'ruRU', 'Если бы я смог осмотреть этот оберег, я смог бы понять суть чар. Удалось тебе его найти?', 0),
	(2561, 'ruRU', '$N, будь $Gосторожен:осторожна; с моим телом: на него наложены могучие чары.', 0),
	(2605, 'ruRU', 'Прошу, скажи мне, что ты $Gнашёл:нашла; собирателей росы!', 0),
	(2606, 'ruRU', 'Значит, старый Синь опять за свое? Из чего сделан этот состав?', 0),
	(2623, 'ruRU', 'Ожидаю приказов.', 0),
	(2641, 'ruRU', 'Фиалковый траган можно найти только в озере, под водой. Надеюсь, ты умеешь задерживать дыхание!', 0),
	(2661, 'ruRU', 'А, вот и ты, $N. Что ты мне $Gпринёс:принесла;?', 0),
	(2741, 'ruRU', 'Супер Яйц-О-Матик – последнее изобретение Кургль Поскакушки. Очень впечатляющее устройство.$B$BПриближаясь к панели управления, вы слышите, как машина яростно гудит.', 0),
	(2746, 'ruRU', 'Я наблюдаю за Лесковаром вот уже две недели. Триас никогда ему не доверял, но мы и не подозревали, что он втянут во что-то, связанное с Братством Справедливости. Мы отслеживали то, что могло связывать его с Сумеречным Молотом. В любом случае, он становится более опасным, чем допустимо для этого города, и тут-то мы и вступаем в дело.$B$BПринесите мне указанные предметы, и мы сможем осуществить мой план.', 0),
	(2747, 'ruRU', 'Редко удается принести яйца из Фераласа в таком необыкновенном состоянии. Они очень редко встречаются...', 0),
	(2748, 'ruRU', 'Из хороших яиц при правильных условиях вылупляются гиппогрифы, не пораженные заклинаниями огров клана Гордунни.', 0),
	(2749, 'ruRU', 'Обычные яйца гиппогрифа вылупляются только в половине случаев. Мы будем тщательно ухаживать за ними, и при удаче кто-нибудь из них вылупится.', 0),
	(2750, 'ruRU', 'Яйца вроде этого не спасти – из них никто не вылупится.', 0),
	(2758, 'ruRU', 'Может быть, ты станешь $Gодним:одной; из $Gнаследников:наследниц; Гальвана!', 0),
	(2759, 'ruRU', 'Редкая ты, должно быть, птица, $Gдружище:подруга;. Дай-ка мне глянуть на этот знак...', 0),
	(2760, 'ruRU', 'Приветствую! Подойди ближе, покажи Гальвану что у тебя.', 0),
	(2761, 'ruRU', 'Когда хорошо поработаешь, мышцы ноют и тело ломит!', 0),
	(2762, 'ruRU', 'Когда хорошо поработаешь, мышцы ноют и тело ломит!', 0),
	(2763, 'ruRU', 'Когда хорошо поработаешь, мышцы ноют и тело ломит!', 0),
	(2765, 'ruRU', 'Получите свою награду!', 0),
	(2768, 'ruRU', 'Ты нашел Блая? Ты принес мой изыскательский стержень?', 0),
	(2770, 'ruRU', 'Вы принесли чешую? Мне не терпится извлечь из нее максимум пользы!', 0),
	(2771, 'ruRU', 'Ты $Gсделал:сделала; все необходимые предметы, $N?', 0),
	(2772, 'ruRU', 'Ты $Gсделал:сделала; все необходимые предметы, $N?', 0),
	(2773, 'ruRU', 'Ты $Gсделал:сделала; все необходимые предметы, $N?', 0),
	(2781, 'ruRU', 'Да, $C, я официальный представитель Водной компании Прибамбасска. Чем могу быть полезен?', 0),
	(2801, 'ruRU', 'Ожидаю приказов.', 0),
	(2841, 'ruRU', 'Не вижу чертежей! Они спрятаны у тебя под одеждой или ты вернулся с пустыми руками и только понапрасну меня раздражаешь?', 0),
	(2846, 'ruRU', 'Ты принес тиару, $N? Велрата поняла, что значит переходить мне дорогу?', 0),
	(2865, 'ruRU', '$GПринёс:Принесла;? Мой кузен в Пиратской бухте очень ждет этих панцирей. А он не любит ждать!', 0),
	(2873, 'ruRU', 'Ну что, $N? Удалось тебе отыскать партию рома?', 0),
	(2874, 'ruRU', 'Ну что, Столи раскошелился?', 0),
	(2875, 'ruRU', 'Вид у тебя ошеломленный. Ты что, наши юридические документы $Gпочитал:почитала;?', 0),
	(2878, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(2880, 'ruRU', 'Мне нужно пять ожерелий, которые носят эти тролли. Если непонятно, то поясню, что проще всего снять ожерелье с мертвого тролля.$B$BДокажите, что вы друг Громового Молота.', 0),
	(2882, 'ruRU', 'Сундук заперт!', 0),
	(2922, 'ruRU', 'Ну как, нашел Техбота?', 0),
	(2924, 'ruRU', 'Ну как, нашел механизмы?', 0),
	(2926, 'ruRU', 'Разве не понятно?! Мы пытаемся спасти целый народ! Нам необходимо изучить радиоактивный осадок! Ради будущего всех гномов!', 0),
	(2928, 'ruRU', 'Если бы речь шла о гонках, вы бы уже проиграли.', 0),
	(2930, 'ruRU', 'Вы принесли призматическую перфокарту?', 0),
	(2946, 'ruRU', 'Какой знакомый постамент. Возможно, он тут неспроста...', 0),
	(2951, 'ruRU', 'Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.', 0),
	(2962, 'ruRU', 'Хм, вы не светитесь. Хороший знак.', 0),
	(2966, 'ruRU', 'Какой знакомый постамент торчит из горячего песка. Возможно, он тут неспроста...', 0),
	(2967, 'ruRU', 'Добро пожаловать, $N. Ну как, пригодились диски?', 0),
	(2977, 'ruRU', 'Добро пожаловать, $N. Ну как, пригодились диски или дело ничем не закончилось?', 0),
	(2981, 'ruRU', 'Ты добыл зуб Зыбуна, $N? Удалось ли тебе прекратить страдания этого существа?', 0),
	(2990, 'ruRU', '$N, вы пришли с подарком?', 0),
	(2991, 'ruRU', 'Вы достали медальон Некрума, $N? В нем сокрыта сила, которую мне не терпится изучить.', 0),
	(2996, 'ruRU', 'Мы охотно приняли бы в дар шерстяную ткань. Если ты дашь нам 60 отрезов, Оргриммар будет тебе чрезвычайно признателен за щедрость. 60 отрезов нам вполне бы хватило – вместе с дарами от прочих пожертвователей этого было бы достаточно, чтобы продолжать работу.\n\nЕсли у тебя при себе имеется 60 отрезов шерсти и ты готов ее пожертвовать, я могу ее принять прямо сейчас.', 0),
	(3022, 'ruRU', 'Еще одна посылочка от Кургль?', 0),
	(3042, 'ruRU', 'Принес?', 0),
	(3065, 'ruRU', 'А, еще $Gодин:одна:r; |3-6($r) в наших рядах! Ты мне подходишь.$b$bС топором тебе пока не управиться, но копье тоже сгодится.$b$bДобро пожаловать в Долину Испытаний!', 0),
	(3082, 'ruRU', 'Джен\'шан видит перед собой $gмогучего охотника:могучую охотницу;! Духи довольны.$b$bТропа охотника – один из древнейших путей этого мира. Орда обратилась к нам, когда пыталась выжить на Азероте. Ее воины попросили обучить их, открыть им наши тайны. Да, они уже были сильны: среди них были и грозные шаманы, и отважные воины. Но путь охотника еще не был их путем...', 0),
	(3083, 'ruRU', 'Добро пожаловать в Долину Испытаний, $N! Раз ты здесь, значит ты $gполучил:получила; мою табличку, так что перейду к делу.$b$bЯ – Руаг, моя работа – готовить разбойников, воров, карманников и прочих ловкачей. И именно ко мне обратится с вопросами Раздробленная Рука, если ты не сумеешь показать себя. Не тревожься, Рука не станет следить за каждым твоим шагом. Однако если ты им понадобишься, разумнее работать на них.', 0),
	(3084, 'ruRU', 'А, $n! Рада видеть тебя здесь. У меня немало дел, и учеников хватает, но каждый раз, как ко мне является кто-то из твоего племени, я чувствую, что круг замкнулся: ведь когда-то я сама училась у одного из ваших шаманов!', 0),
	(3085, 'ruRU', 'А-а, ты здесь! Хорошо-хорошо! Духи предупреждали меня, что скоро ты явишься повидаться с Кен\'джаем. Я рад приветствовать тебя в Долине Испытаний. Это место недолго будет тебе домом, но постарайся научиться здесь всему, чему можно.', 0),
	(3086, 'ruRU', 'Ага, $n, ты уже нравишься Май\'ах! Неплохо, неплохо. Уважай Май\'ах, и Май\'ах будет уважать тебя. Ну, хватит про это. Ты здесь, чтобы учиться магии, а не слушать болтовню Май\'ах.$b$bЧему Май\'ах тебя не сможет научить, так это одному: как остановить демонов.', 0),
	(3087, 'ruRU', 'А, вот и ты! Хорошо. Дженшан тебя ждала.\n\nМногие думают, что путь охотника прост, но Джен\'шан тебе скажет: это неправда. На то, чтобы совладать со зверями Дуротара и других земель, нужно не меньше искусства, чем на то, чтобы плести чары или говорить с предками.\n\nБыть может, стрелять из лука или ружья не так опасно, как применять заклинания, но твоим врагам от этого будет не легче.', 0),
	(3088, 'ruRU', 'Тс-с, тише! Не доверяю я этому Нартоку. С тем, кто норовит забиться в пещеру глубже меня, лучше не связываться.$b$bНадеюсь, тебе без труда удалось меня отыскать?', 0),
	(3089, 'ruRU', 'А, $gпришел:пришла; наконец-то! А я уж думать начала, долго ли мне тебя еще ждать. Я отправила пергамент довольно давно, но не была уверена, что его тебе доставили.$B$BНу ладно, довольно болтать. Ты здесь потому, что был $gизбран:избрана; стать $gдуховным наставником:духовной наставницей; нашего народа.', 0),
	(3090, 'ruRU', 'Ага, вот и ты... тебя никто не заметил по дороге? Это хорошо.\n\nНаш мир полон глупцов, $N. Даже у великого Тралла есть свои недостатки. Он отказывается от могущества, которое необходимо, чтобы полностью подчинить эти земли! Мы ведь уже не марионетки порождений Пустоты. Мы сами себе господа. Мы горды и могущественны!', 0),
	(3091, 'ruRU', 'А, вот наконец-то и ты, $C. Я не солгал тебе в записке, $N. Мы тоже таурены особой породы, не как шаманы и друиды нашего племени. Мы не менее важны. Мы те, кто защищает границы, охотится на кентавров и воюет.', 0),
	(3092, 'ruRU', 'Добро пожаловать в Лагерь Нараче, $N. Я слышал много хорошего о тебе. Твоя кровь сильна, а многие из старейшин считают, что ты уже достаточно $gумелый:умелая;. И все же мы это проверим. $B$BРавнины Мулгора будут тебе домом на какое-то время – постарайся изучить их как можно лучше. Однажды тебе придется отправиться в незнакомые земли, чтобы овладеть более сложными умениями. Будь $gготов:готова; к этому.', 0),
	(3093, 'ruRU', 'И вот ты $gпришел:пришла; ко мне, быстрее, чем вода падает с неба. Мне приятна твоя поспешность. Она говорит о том, что ты понимаешь, как важен наш разговор и твое присутствие здесь. Я понимаю стихии и говорю с духами нашего народа, не стремясь при этом выбиться в лидеры. Я смогу научить тебя тому же.', 0),
	(3094, 'ruRU', 'Вот и ты! Очень хорошо. Духи предков по всему Мулгору вдруг стали беспокойны, и никто не может понять, что послужило этому причиной. Отныне ты всегда $gдолжен:должна; будешь прислушиваться к духам природы и становиться их воплощение. Помни это.', 0),
	(3095, 'ruRU', 'Итак, ты $gприбыл:прибыла;. Хорошо. Я слышал, что еще нескольким удалось избежать "смерти" и они направляются сюда. Возможно, подобная живучесть пригодится им и в будущем. $b$bБлагодари Сильвану за свою свободу... свободу тела и духа. Хотя тебя по-прежнему мучают чума и ее последствия, ты можешь теперь передвигаться свободно – на вид ты в полном порядке.', 0),
	(3096, 'ruRU', 'Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеловы, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.', 0),
	(3097, 'ruRU', 'Итак, меж огня, чумы, беспорядков и еще худших бед, еще $gодин "верный":одна "верная"; стучит в мою дверь. Что ж, позволь поприветствовать тебя, |3-6($c). И дай мне минутку, чтобы я объяснил тебе пару вещей, прежде чем ты решишь, что пора отправляться на поиски того, что притягивает тебя: Священный Свет позабыл о тебе, духи твоих предков – всего лишь сказки, а создания Хаоса не желают тебя. $b$bТы понимаешь, о чем я?', 0),
	(3099, 'ruRU', 'Приветствую тебя, брат. Я знал, что твое появление – лишь вопрос времени. \n\nТо, что я сказал, заинтересовало тебя, не правда ли? Я задел правильную струну... нечто внутри тебя знало, что сказанное мною – правда. Хорошо. \n\nЗнай же: я не предаю Сильвану. Если уж на то пошло, она сама признала бы мою правоту, потому что ее собственные воззрения поставили Отрекшихся в то положение, в каком они находятся сейчас.', 0),
	(3100, 'ruRU', 'А, так ты $gполучил:получила; мое письмо, $N... Это хорошо.$B$BВ последнее время в Элвине прямо-таки наплыв воинов. Для Штормграда это хорошо, а вот местным кобольдам и бандитам из Братства Справедливости приходится несладко, ха-ха.', 0),
	(3101, 'ruRU', 'Наконец-то! Вот мы и встретились, $gбрат мой:сестра моя;. Приветствую тебя в Североземье! Это место будет твоим домом, пока ты не усвоишь азы нашего дела, но знай, что Штормград недалеко, и рано или поздно твой путь приведет тебя туда. Ну а пока наберись терпения... рыцарь Серебряной Длани.', 0),
	(3102, 'ruRU', 'Ты добралась сюда в целости и сохранности, и вроде бы тебя никто не заметил. Это хорошо – не люблю лишнее внимание... Думаю, ты меня понимаешь.\n\nЕще ни во что не успела вляпаться? Нет? Здорово! Но ничего, все впереди.', 0),
	(3103, 'ruRU', 'Ах, наконец-то ты $gпришел:пришла;. Я знала, что ты меня найдешь. Отблеск света Благодати лежит на тебе и избранном тобой пути. Нынешние времена суровы – Пылающий Легион все еще оскверняет своим присутствием Азерот, Калимдор ищет пути избавления от собственных несчастий, и ты $gдолжен:должна; будешь помогать нуждающимся в меру своих сил.', 0),
	(3104, 'ruRU', 'Привет, $N. Я – Келден. Чем могу помочь?', 0),
	(3105, 'ruRU', 'Наконец-то ты $gпришел:пришла;, $N Представляешь, только что мимо проходили стражники и очень подозрительно на меня косились... жалкие тупицы.', 0),
	(3106, 'ruRU', 'Холодно сегодня, правда? Кажется, этот снег никогда не растает.$b$bДумаю, сложно не заметить, что в нашем городе поселились гномы, так ведь, $N? А все почему? Да потому, что они подорвали свой собственный дом, вот и прибились к нам. Но знаешь что? Я их не осуждаю. Если бы в Стальгорн пролезла подобная пакость, я бы тоже стал подумывать о взрывчатке...', 0),
	(3107, 'ruRU', 'Итак, ты здесь – и очень вовремя. Нам многое предстоит сделать в Холодной долине – а может, и за ее пределами. Мне понадобится твоя помощь, а тебе, несомненно, будет нелишней моя.$B$BТеперь ты рыцарь Серебряной Длани: не забывай об этом!', 0),
	(3108, 'ruRU', 'Ага, наконец-то ты $gпришел:пришла;! Рад тебя видеть, честное слово! Надеюсь, тебе не пришлось распутывать следы, чтобы меня найти? Ха-ха!$b$bНаша профессия основана на древних традициях, которые мы свято чтим, $N. Чтобы научиться понимать природу и выслеживать медведя в горах – да и просто чтобы выжить в одиночку, – требуется мужество, ум и хитрость. Как ты думаешь, у тебя есть все это?', 0),
	(3109, 'ruRU', 'Ага! Ты наконец-то $gпришел:пришла;! Прекрасно!$b$bУ нас тут такие дела творятся! Любая помощь пригодится, уж ты мне поверь. Раз уж ты здесь, то наверняка знаешь, что нет ничего лучше холодной клинка в руке и тени, защищающей получше любой брони, так ведь?', 0),
	(3110, 'ruRU', 'А, вот и ты, $N! Отлично!$b$bЧестно говоря, я уже почти утратил веру в то, что ты придешь... Почти утратил веру, понимаешь? Ну, это шутка была… Что? Не смешно? А, забудь! В любом случае, ты ведь $gшел:шла; сюда не за тем, чтобы слушать мои шутки.', 0),
	(3112, 'ruRU', 'О, а вот и еще один <гном>, отправляющийся на поиски приключений... Решимость в глазах, сжатые кулаки...\n\nНу ладно, ладно, успокойся, я вовсе не собирался тебя дразнить. Я, не поверишь, даже уважаю твою решимость. Судьба гномов мне отнюдь не безразлична – я вместе с вами скорблю о потере Гномрегана.', 0),
	(3113, 'ruRU', 'Рад тебя здесь видеть – это значит, мое послание нашло адресата. Прости, что заставил тебя поверить, будто это послание от кого-то свыше. Понимаешь, таким, как мы, сейчас лучше держаться вместе.$b$bМногим кажется, что двум разбойникам в одном городе не ужиться, но я думаю, мы отлично сработаемся. Как ты считаешь?', 0),
	(3114, 'ruRU', 'Ну да, |3-6($r), я слушаю. В чем дело? Давай же, говори, в конце концов! Только учти, что после пары-тройки стаканов слух у меня становится не очень.', 0),
	(3115, 'ruRU', 'Просто великолепно! Вне всякого сомнения, моя записка нашла адресата!$b$bПослушай, $N, пора перестать обращать внимание на глупцов. Священный Свет? Щит и меч?!.. Нет, для таких, как мы, это слишком мелко, слишком ограниченно. Только посмотри, во что превратила наш дом "обычная" магия! Можно считать, что нашей расы уже не существует. Вымерла. Теперь мы вынуждены рассчитывать на дворфов, а они скорее вступят в союз с людьми, чем помогут нам заново отстроить наш дом. Мы оказались существами второго сорта. Тебе не приходилось замечать, как на нас смотрят?..', 0),
	(3116, 'ruRU', 'Я рада, что ты здесь.$B$BМногое случилось за последние годы, $N: создание Тельдрассила, порча, павшая на множество лесных обитателей здесь и в округе, обнаружение земель, которые мы считали для себя потерянными, например, Фералас... так много, и все за столь короткое время. Но это лишь некоторые из причин, по которым мы здесь, важнее всего – защитить наш род от зла.', 0),
	(3117, 'ruRU', 'Ты наконец-то здесь, $N, хотя и не так скоро, как я надеялась. Добро пожаловать в Тенистую долину.\n\nНадеюсь, ты получила мое послание, будучи в добром здравии и расположении духа?\n\nКак я говорила ранее, я намереваюсь обучить тебя охотничьему мастерству: приручению зверей, которые помогут тебе в бою, стрельбе из лука с безукоризненной меткостью и уважению к землям, которые мы зовем домом, так и к тем, что лежат за очерченными нами пределами.', 0),
	(3118, 'ruRU', 'Привет, $N. Рад, что тебе удалось меня найти, а то я уж думал, что ты заблудилась по пути.\n\nНа самом деле в Тенистой долине ничего особенного не случилось с тех пор, как я послал знак, но, пожалуй, сбором информации тебе лучше заняться самой. Поговори с остальными эльфами, живущими около Альдрассила.', 0),
	(3119, 'ruRU', 'Рада видеть, что тебя ничто не задержало в пути, $N. Добро пожаловать.$B$BТебе, наверное, доводилось слышать, что в Тельдрассил постоянно прибывают новые путешественники. Даже членам Альянса было позволено ступать на ветви Тельдрассила для того, чтобы встретиться с другими кальдораями, готовящимися к грядущим приключениям.', 0),
	(3120, 'ruRU', 'А, это ты, $gюный:юная:c; |3-6($c). Вижу, ты желаешь продолжить свое обучение. Это хорошо.$B$BСкажи, известно ли тебе, что такое Изумрудный Сон? Хотя, возможно, ты еще к этому не $gготов:готова;... Ну ладно, всему свое время.$B$BПока что обсудим другие вопросы.', 0),
	(3161, 'ruRU', 'У тебя возникли затруднения?$B$BГаз\'рилловые украшения можно найти по всему Танарису, $N, так что разуй глаза!', 0),
	(3221, 'ruRU', 'Вы уже уничтожили Плеть Ночи, $N? От этого зависит наш успех в борьбе против Гнилошкуров!', 0),
	(3261, 'ruRU', 'Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6($C)?', 0),
	(3281, 'ruRU', 'И где серебро?', 0),
	(3301, 'ruRU', 'Я чувствую, от тебя пахнет пылью Степей, |3-6($C). Ты издалека пришел.', 0),
	(3321, 'ruRU', 'Сегодня мы отпразднуем твое вступление в Орден.', 0),
	(3341, 'ruRU', 'Это очень важное дело, $N. Мы должны предотвратить попытки Плети пополнить свои ряды.', 0),
	(3361, 'ruRU', 'Я тебе вот что скажу, $N: таким, как я, в этом городе не место. И в Гномрегане-то всякой пакости хватало до того как... Ну, ты меня понимаешь. Вот теперь и тут покоя не дают...\n\nКак насчет моих вещей, а? Представить себе не могу, что с ними могли сделать эти мерзавцы-тролли!', 0),
	(3362, 'ruRU', 'Я бы хотел поближе взглянуть на этот кактус в долине... Так что оставь его целым, хорошо?', 0),
	(3363, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(3364, 'ruRU', 'Ну да. Я и есть Дарнан Мехорез. И какое у тебя ко мне дело?', 0),
	(3365, 'ruRU', 'Я так понимаю, жгучая бражка попала к старине Дарнану как раз вовремя! А как моя кружка? Надеюсь, ты не забыла, что ее надо было принести обратно?', 0),
	(3368, 'ruRU', '*По лицу Ториуса катятся слезы*', 0),
	(3369, 'ruRU', 'Могу я тебе чем-то помочь?', 0),
	(3370, 'ruRU', 'Могу я тебе чем-то помочь?', 0),
	(3373, 'ruRU', 'Приблизившись к купели, о которой говорил Эраникус, вы снова слышите его голос. $B$B"Да, смертный эта купель освободит неоскверненную частицу моего разума, заключенную в этот камень. Помести его в купель и позволь магии зеленых драконов очистить мою сущность от скверны. только тогда я обрету истинную свободу и только тогда драконы вновь обретут власть над Аталаи."', 0),
	(3376, 'ruRU', 'Остроклык больше не будет угрожать нам, если ты принесешь мне его голову, $N.\n\nМы, таурены, живем охотой, а самая захватывающая охота – та, где ты и сам можешь стать жертвой. Если ты преуспеешь в этом задании, то поймешь, о чем я говорю.', 0),
	(3449, 'ruRU', 'О, рад, что вы сюда добрались, $N. Вы сделали эти картинки для Тимора?\n\nХотя местечко опасное, на побережье особого шевеления нет. Может, потому что наги кишат под водой, но это уже не моя проблема... Я небеса патрулирую.', 0),
	(3461, 'ruRU', 'Вы вернулись! Замечательно. А готовальню мою принесли?', 0),
	(3513, 'ruRU', 'Что это?', 0),
	(3519, 'ruRU', 'Тебе удалось проникнуть в Паучье логово, $N А найти паучье яйцо?', 0),
	(3520, 'ruRU', 'Ты несешь мне сущность дольных крикунов, $N?', 0),
	(3521, 'ruRU', 'Пожалуйста, принеси мне все эти ингредиенты, $N. Иверрону нужна наша помощь!', 0),
	(3522, 'ruRU', 'О... $N, какое счастье, что ты $Gвернулся:вернулась;...', 0),
	(3523, 'ruRU', 'Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.', 0),
	(3524, 'ruRU', 'Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнасе оценить ситуацию!', 0),
	(3525, 'ruRU', 'Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.', 0),
	(3527, 'ruRU', 'Ты несешь мне таблички пророчества Мошару?$B$BЯ хочу изучить их и понять, как сковать сущность Хаккара!', 0),
	(3528, 'ruRU', 'Тебе удалось победить аватару Хаккара, $N? Заряжено ли это яйцо его сущностью?', 0),
	(3568, 'ruRU', 'Ты ведь догадываешься, к чему все идет, $N? Ей не выжить... видно с первого взгляда. Лучшее, что она может сделать, – это помочь нам отыскать лекарство от чумы. Быть может, в воде, которую она пила, мы найдем намеки на то, как можно получить рецепт? Если все равно помирать, почему бы не сделать перед смертью доброе дело для своего народа? Ты согласен?', 0),
	(3569, 'ruRU', 'Я пришла в Подгород, потому что слышала, что алхимики давно работают над созданием лекарств, которые могут исцелить их собственную болезнь. Я надеялась, что они и мне помогут.\n\nХотя я чувствую себя не в своей тарелке, выбора нет – боль раздирает меня изнутри, и мне срочно нужна помощь.', 0),
	(3661, 'ruRU', 'Старайтесь избегать их, $N. Дикосовухи могут счесть вас за врага.', 0),
	(3741, 'ruRU', 'Привет. Я очень переживаю из-за пропажи ожерелья. Ведь его мне папа привез! Кстати, он говорит, что в озере водятся чудовища. Вы уже их победили?', 0),
	(3764, 'ruRU', 'А, опять эта грязь. Верховный друид требует с каждого искателя приключений по двадцать кучек – двадцать кучек ему и будет. И пусть те, кто строит нам козни, топает по обочине!', 0),
	(3783, 'ruRU', 'Мне так много нужно всего собрать, чтобы начать! Пожалуйста, принеси мне эти меха как можно скорее!', 0),
	(3802, 'ruRU', 'Статуя зловеще нависает над вами.', 0),
	(3845, 'ruRU', 'Приветствую! Простите, а мы не встречались раньше? Ваше лицо выглядит знакомым...', 0),
	(3881, 'ruRU', 'Если мы вообще хотим выжить в этом жутком месте, нам нужна провизия. А спасение хоть каких-то из наших исследовательских инструментов было бы просто манной небесной!', 0),
	(3882, 'ruRU', 'Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...', 0),
	(3884, 'ruRU', 'Приветствую! Мы с коллегами рады видеть собрата по разуму после стольких недель общения с диким зверьем! Что привело тебя в Кратер Ун\'Горо?', 0),
	(3901, 'ruRU', 'Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеловы, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.', 0),
	(3902, 'ruRU', 'Удалось ли тебе найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!', 0),
	(3904, 'ruRU', 'Ты $gпринес:принесла; мой виноград, $N?', 0),
	(3905, 'ruRU', 'Сдается мне, ты в хорошем настроении! Сядь, отдохни тут немножко. Хочешь вина?', 0),
	(3908, 'ruRU', 'Ого! Неужели Линкен наконец-то собрался прислать мне свой меч?', 0),
	(3921, 'ruRU', 'Я очень занята, |3-6($C). Если ты пришел не по важному делу, иди своей дорогой...', 0),
	(3922, 'ruRU', 'Несешь заготовки, $N? Я все посматриваю на самофланж, и мне не терпится им заняться.', 0),
	(3923, 'ruRU', 'Осторожно! Голову береги! Не стой под стрелой!', 0),
	(3924, 'ruRU', 'Где руководство?', 0),
	(4021, 'ruRU', 'Где знамя?', 0),
	(4101, 'ruRU', 'Оскверненный лес страдает, $N – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут в злые руки, это обернется бедой для всего Оскверненного леса.\n\nПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.', 0),
	(4103, 'ruRU', 'Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.$B$BЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.', 0),
	(4104, 'ruRU', 'Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.$B$BЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.', 0),
	(4105, 'ruRU', 'Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.$B$BВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.', 0),
	(4106, 'ruRU', 'Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!$B$BКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.', 0),
	(4107, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!', 0),
	(4108, 'ruRU', 'Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.$B$BЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.', 0),
	(4109, 'ruRU', 'Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.$B$BЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.', 0),
	(4110, 'ruRU', 'Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.$B$BВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.', 0),
	(4111, 'ruRU', 'Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!$B$BКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.', 0),
	(4112, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!', 0),
	(4113, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4114, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4115, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4116, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4117, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4118, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4119, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4123, 'ruRU', 'Ты принес сердце горы? Для меня его ценность поистине безгранична.', 0),
	(4126, 'ruRU', 'Ты нашел рецепт, $N? Меня передергивает от одной мысли о том, что эти наглецы будут пить наш фамильный напиток!', 0),
	(4136, 'ruRU', 'Ты привел Риббли? Хотя меня больше интересует не столько он сам, сколько его голова.', 0),
	(4161, 'ruRU', 'Помни о равновесии, $N. Желаю тебе открыть в себе понимание и любовь к живым лесам.', 0),
	(4201, 'ruRU', 'Ты принес все, что нужно? Боль в моем сердце растет с каждым днем!', 0),
	(4221, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4222, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4284, 'ruRU', 'Я чувствую, что близка к разгадке, $N!', 0),
	(4343, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4401, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4402, 'ruRU', 'Ну что, собрала плоды?', 0),
	(4403, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4421, 'ruRU', 'Порча здесь сводит существ с ума ...', 0),
	(4441, 'ruRU', 'Будем надеяться, что сия вода освободит духи Древ и подарит им мир.', 0),
	(4443, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4444, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4445, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4446, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4447, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4448, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4461, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на кнутокорень. Находящиеся на виду корни кажутся жесткими и кожистыми, и все растение покрыто какой-то липкой пленкой. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4462, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на Ночного дракона. Плоды его тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4464, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4465, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на песнецвет. Резкий, нездоровый запах исходит от него. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4466, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4467, 'ruRU', 'Вы нашли чахлое, пораженное какой-то порчей растение, похожее на ветроцвет. Ягоды на нем тоже кажутся какими-то гнилыми и ядовитыми. Если вы хотите вернуть его к нормальному состоянию, то срочно необходимо им заняться.', 0),
	(4495, 'ruRU', 'А, это ты, юный |3-6($C. Вижу, ты желаешь продолжить свое обучение. Это хорошо.\n\nСкажи, известно ли тебе, что такое Изумрудный Сон? Хотя, возможно, ты еще к этому не готова... Ну ладно, всему свое время.\n\nПока что обсудим другие вопросы.', 0),
	(4496, 'ruRU', 'Найти подходящую ароматическую железу может оказаться непросто – она должна быть в идеальном состоянии, чему совсем не способствует способ добычи. Что же до почвы, её-то должно быть совсем нетрудно отыскать.$B$BКороче, ты $Gпринёс:принесла; мне всё необходимое?', 0),
	(4502, 'ruRU', 'Это правда, что вулкан в Ун\'Горо активен? Уверена, что многое смогу узнать по вулканическому пеплу, $N.', 0),
	(4504, 'ruRU', 'Тран\'рек гений, прочь сомненья – этот суперклей с руками оторвут!', 0),
	(4507, 'ruRU', 'Нам не обойтись без мозга королевы. Судя по всему, силитиды находятся под контролем чуждой злой силы. Мне страшно думать, кто может управлять такими злобными тварями, как силитиды, $N.', 0),
	(4508, 'ruRU', 'Они глупцы, $N! Бессмысленная ненависть к Орде затмила им разум. Они не видят дальше своего носа – не верят в опасность, грозящую всем нам. Не знаю, как еще можно доказать им реальность нашествия силитидов. Может, бросить прямо в ульи?$B$BПрости, ты, наверное, несешь какие-то вести?', 0),
	(4509, 'ruRU', 'Они глупцы, $N! Бессмысленная ненависть к Альянсу затмила им разум. Они не видят дальше своего носа – не верят в опасность, грозящую всему миру. Не знаю, как еще можно доказать им реальность нашествия силитидов. Может, бросить прямо в ульи?$B$BПрости, ты, наверное, несешь какие-то вести?', 0),
	(4510, 'ruRU', 'Слава Элуне, $C. Что я могу для тебя сделать сегодня?', 0),
	(4511, 'ruRU', 'Заг заг! Чем могу помочь тебе, $C?', 0),
	(4512, 'ruRU', 'Некоторые мои эксперименты дают просто невероятные результаты. Думаю, еще немного, и я смогу понять природу этих тварей и выяснить, какую роль они сыграли в происхождении жизни в Азероте... если, конечно, они вообще имеют отоношение к Азероту.$B$BОдна из величайших моих теорий – не слишком популярных – гласит, что слизнюки и слизь не связаны собственно с происхождением нашей планеты. Они, скорее, ее выделения.$B$BНо я не могу ни доказать ее, ни опровергнуть, пока не получу побольше образцов.', 0),
	(4513, 'ruRU', 'Как много нужно обдумать. Но что это значит? И как это влияет на жизнь народов Азерота?', 0),
	(4542, 'ruRU', 'Что вы хотели, |3-6($C)? Срочное послание? Для меня?', 0),
	(4581, 'ruRU', 'Ты что-то мне принес?', 0),
	(4601, 'ruRU', 'Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.', 0),
	(4681, 'ruRU', 'Когда вы исследуете останки твари, лежащие в воде к западу отсюда, я, наверное, смогу представить надлежащий отчет в Храм Луны в Дарнассе. Возможно, тогда мы приблизимся к пониманию того, почему эти несчастные создания выбирают такую смерть, выбрасываясь на отмели на Темном Берегу.', 0),
	(4722, 'ruRU', 'Здравствуйте, $N, вы хотите рассказать еще что-то о тварях, выбросившихся на берег?', 0),
	(4723, 'ruRU', 'Может, когда-нибудь мы изыщем средство, чтобы несчастные твари больше не заканчивали впустую  свою жизнь на отмелях Темного Берега. А до тех пор мы должны продолжать наши исследования.$B$BПриветствую, $N! С какими вы вестями?', 0),
	(4725, 'ruRU', 'Приятно вновь увидеть вас, $N. Мы прилагаем большие усилия, чтобы узнать, почему же огромные морские существа выбрасываются на пески Темного Берега, но на каждый найденный ответ возникает два новых вопроса.$B$BВы пришли, чтобы снова оказать нам помощь в расследовании?', 0),
	(4726, 'ruRU', 'Удалось получить сущность детенышей? Мне не терпится изучить ее.$B$BКроме того, моего заказчика лучше не разочаровывать.', 0),
	(4727, 'ruRU', 'Приветствую снова, $N! Вы нашли еще каких-то выбросившихся на берег тварей, о которых следовало бы узнать Храму Луны?', 0),
	(4728, 'ruRU', 'Приветствую вас снова, $N! Что привело вас обратно в Аубердин? Может быть, вы хотите доложить о новой находке?', 0),
	(4729, 'ruRU', 'Киблер яростно спорит с Опусом.', 0),
	(4730, 'ruRU', 'Снова приветствую вас, $N! Хотите сообщить об очередной находке?', 0),
	(4731, 'ruRU', 'Я вновь приветствую вас, $N! Работа, которую вы проделали для Храма Луны, просто великолепна. Порадуете нас снова плодами своих трудов?', 0),
	(4732, 'ruRU', 'Я вновь приветствую вас, $N! Вам удалось обнаружить еще что-то, интересное Храму Луны?', 0),
	(4733, 'ruRU', 'Хвала Элуне – я рада нашей встрече, $gдорогой:дорогая; $N. Расследование Храмом Луны феномена выброшенных на берег созданий продолжается. Быть может, вы хотите предложить нам еще что-то интересное?', 0),
	(4737, 'ruRU', 'Наг все больше и больше, $N. Прошу, сделай это для меня.', 0),
	(4740, 'ruRU', 'Приветствую вас, |3-6($c). Чем часовые могут помочь вам? Вы пришли узнать о награде за голову Глубомрака?', 0),
	(4762, 'ruRU', 'Загрязнение реки Скалистой – лишь первое проявление тревожной тенденции здесь, на Темном Берегу. Проба, которую вы добудете, поможет нам составить план... как я начинаю подозревать, план атаки.', 0),
	(4763, 'ruRU', 'Талисман Скверны – это жуткое приспособление, которое служит для нарушения природного баланса. Когда вы найдете этот предмет среди того, чем сатир мучает фурболгов, и принесете его мне для уничтожения, можно будет считать, что мы одержали великую победу!', 0),
	(4764, 'ruRU', 'Ты принес пряжку, $N? Мой клиент готов хорошо за нее заплатить.', 0),
	(4765, 'ruRU', 'Мне доложили о прибытии вестника. Вестника с даром с пика Черной горы.\n\nЭто ты?', 0),
	(4767, 'ruRU', '$N, вы набрали для меня яиц виверн? Мне не терпится начать дрессировку моих новых ветрокрылов!', 0),
	(4781, 'ruRU', 'Да-да, золотые слитки. Принеси мне слиток, и тогда поговорим про нить. А пока я советую сосредоточиться на обучении. Самые суровые испытания еще впереди. Поверь, сколько ты ни занимайся, сколько ни копи силу, ее все равно будет не хватать.', 0),
	(4783, 'ruRU', 'Пустоши – опасное место: наги, гиганты, сатиры, Пылающий Легион... И вдобавок ко всему еще и воинственные кентавры.\n\nЯ уже говорил, что это подвергнет испытанию не только твою силу и ловкость, но и терпение. Не теряй бдительности, $N.', 0),
	(4784, 'ruRU', 'Осталось недолго, $N, честное слово. Одеяние неплохо послужит тебе и даст преимущество над противниками.', 0),
	(4786, 'ruRU', 'Осталось недолго, $N, честное слово. Одеяние неплохо послужит тебе и даст преимущество над противниками.', 0),
	(4787, 'ruRU', 'Ты несешь древнее яйцо? Я чувствую, как просыпаются великие силы. Боюсь, время у нас на исходе.', 0),
	(4801, 'ruRU', 'В Зимних Ключах тебе биться предстоит с огромными кошками, ледопардами. Эти звери жутко быстрые и ловкие. Если хочешь обрести скорость ледопарда принеси э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь э\'ко добыть.', 0),
	(4802, 'ruRU', 'В Зимних Ключах тебе придется сражаться со свихнувшимися существами – фурболгами племени Зимней Спячки. По воле своего вождя они обрели невероятную силу. Если и ты хочешь получить силу этого племени, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь камень э\'ко добыть.', 0),
	(4803, 'ruRU', 'В Зимних Ключах тебе встретятся большие медведи с очень толстой шкурой. Это медведи-щербозубы. Судя по тому, что они способны выдержать – отлично защищены. Если хочешь получить сопротивляемость огню, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь э\'ко добыть.', 0),
	(4804, 'ruRU', 'В Зимних Ключах тебе предстоит биться с тварями, которые зовутся химеры-хладнокрылами. Эти существа владеют мощной магией холода. Если хочешь обрести способность противостоять этой магии, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь э\'ко добыть.', 0),
	(4805, 'ruRU', 'В Зимних Ключах тебе предстоит биться с тварями, которые зовутся йети с холмов Ледополоха. Они неповоротливы, но их толстая шкура выдерживает любые удары. Если хочешь обрести эту способность, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь э\'ко добыть.', 0),
	(4806, 'ruRU', 'В Зимних Ключах тебе предстоит биться с великанами ледяного молота. Они сильны и яростны. Если хочешь обрести их силу, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что сокровище Мау\'ари с собой нужно носить, если хочешь э\'ко добыть.', 0),
	(4807, 'ruRU', 'В Зимних Ключах тебе предстоит сражаться с существами, обладающими врожденной способностью к магии. Сильная магия у этих диких совухов, да, сильная... Если хочешь обрести их магию и использовать в своих целях, принеси мне э\'ко, что найдешь у них.$B$BИ не забудь, что с собой нужно носить сокровище Мау\'ари, если хочешь э\'ко добыть.', 0),
	(4808, 'ruRU', 'Как здесь холодно! Надеюсь, ты $Gпринёс:принесла; мне одеяло!', 0),
	(4809, 'ruRU', 'Ты несешь мне рога хладнокрылов, $N?', 0),
	(4810, 'ruRU', '$N! Ты $Gпоговорил:поговорила; с Фелноком? Ты $Gпринёс:принесла; то, что я просила?', 0),
	(4811, 'ruRU', 'Что вы можете сказать о том красном кристалле? Он действительно существует?', 0),
	(4812, 'ruRU', 'На фоне лесного пейзажа Темного Берега кристалл выглядит совершенно чужеродным. Вам кажется, что откуда-то изнутри кристалла до вас доносится чуть слышное жужжание.', 0),
	(4821, 'ruRU', 'Мне нужно узнать побольше об этом таинственном яйце. Кто знает, что может из него вылупиться...', 0),
	(4822, 'ruRU', 'У них наверное много и других вкусов, кроме клубники, но клубничное мое любимое!', 0),
	(4862, 'ruRU', 'У тебя в сумке лежат паучьи яйца или ты так, поболтать, зашла?', 0),
	(4864, 'ruRU', 'Привет… Расскажи-ка, какие новости?', 0),
	(4881, 'ruRU', 'Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?', 0),
	(4904, 'ruRU', 'Вы выяснили, что задумал клан Зловещего Тотема?', 0),
	(4906, 'ruRU', 'Пожалуйста, положите конец страданиям созданий Оскверненного леса.', 0),
	(4921, 'ruRU', 'Иглогривы за все заплатят, $N. Клянусь.', 0),
	(4962, 'ruRU', 'Да, $N? Ты сделал выбор? Инфернал или гончая скверны?\n\nЧасто чернокнижники предпочитают усиливать сильные стороны, а не развивать слабые. Порой лучше научиться чему-то одному, чем стать разносторонним заклинателем.', 0),
	(4963, 'ruRU', 'Да, $N? Ты сделал выбор? Инфернал или гончая скверны?\n\nЧасто чернокнижники предпочитают усиливать сильные стороны, а не развивать слабые. Порой лучше научиться чему-то одному, чем стать разносторонним заклинателем.', 0),
	(4966, 'ruRU', 'Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?', 0),
	(4971, 'ruRU', 'Там, где кто-то вмешивается в ход времени, непременно появляются временные паразиты. Я чувствую, что их немало, и они мне очень мешают.$B$BЕсли ты искоренишь хотя бы часть, мне будет гораздо проще разрешить сложившуюся ситуацию. Я почувствую, когда ты справишься с моим заданием.', 0),
	(4972, 'ruRU', 'Временные устройства, которые я ищу, очень просты. По большей части это просто часы, и их стрелки остановились в тот миг, когда в Андорале вспыхнула чума.$B$BВремя нескончамо, а часы, которые ты мне принесешь так и будут стоять... пока мы не справимся с временной аномалией.', 0),
	(4973, 'ruRU', 'Часы Андорала, как и те, на башне, остановились в три часа. Именно в это время чума распространилась по всему городу, лишая жизни несчастных жителей.$B$BКак ни печалимся мы о событиях того дня, они уже вошли в историю, без них не было бы сегодняшнего дня, такого, каким видите его вы, смертные. Бронзовые драконы должны хранить линию времени!', 0),
	(4984, 'ruRU', 'Пораженных чумой волков необходимо истребить. Эта болезнь неизлечима. Я пытался справиться с ней, пока сам не пал ее жертвой.', 0),
	(4985, 'ruRU', 'Я слышу твою поступь, $N. Зрение мое уже помутнилось, но я чувствую все, что вокруг. Ты $Gизбавил:избавила; несчастных гризли от страданий?', 0),
	(4986, 'ruRU', 'Приветствую тебя от имени Круга Кенария, |3-6($C). Что за дела привели тебя к нам?', 0),
	(4987, 'ruRU', 'Приветствую тебя от имени Круга Кенария, $C. Что за дела привели тебя к нам?', 0),
	(5001, 'ruRU', 'Ну, как успехи?', 0),
	(5002, 'ruRU', '$N! Сколько лет, сколько зим!', 0),
	(5022, 'ruRU', 'Добро пожаловать в отдел переписи Штормграда. Если вы хотите навести справки о жителях города, то пришли по адресу.', 0),
	(5041, 'ruRU', 'Как идут поиски припасов? Надеюсь, иглогривов-то ты легко одолеешь?', 0),
	(5048, 'ruRU', 'Я поросила бы вас не топтать мою лужайку, но, как видите, у меня ее нет.', 0),
	(5050, 'ruRU', 'Джон, милый... Это ты? Мне так холодно...', 0),
	(5051, 'ruRU', 'Джон, не давайся в руки вурдалаков... Не отдавай им меня... Гнусные вурдалаки, оберег защитит нас.', 0),
	(5052, 'ruRU', 'Наши племена селятся в тех областях Степей, где растут колючки, фыркает потому что это священные места. И первейшее из них – это земли Иглошкурых. Тело Агамаггана составляет все эти земли, но особенно хранимы холмы, потому что вход в них сделан из его огромной пасти! фыркает Она поглощает всех неверных и выплевывает их тела, когда он хорошенько прожует их! фыркает\n\nАгамагган оставил свое тело, чтобы защитить нас, и щедро делится своим духом, чтобы мы защищали его. фыркает', 0),
	(5054, 'ruRU', 'Иди, $C. Найди Урсиуса.', 0),
	(5055, 'ruRU', 'Брумеран ждет тебя, $N.', 0),
	(5056, 'ruRU', 'Шай-Ротам смела и беспощадна; она будет защищать свой вид с горячим энтузиазмом.', 0),
	(5059, 'ruRU', 'Дверь в служебное помещение потрескалась, будто кто-то долго и упорно пытался ее выломать. В настоящий момент она заперта снаружи.$B$BПодергав за ручку, вы слышите изнутри утробные стоны! Что бы ни скрывалось внутри, оно кажется совсем недружелюбным.', 0),
	(5060, 'ruRU', 'Перед вами массивный шкаф, надежно запертый на врезной замок. Дверцы шкафа сильно исцарапаны. Судя по всему, его не раз пытались взломать, чтобы посмотреть, что внутри.$B$BПохоже, без ключа этот шкаф не открыть.', 0),
	(5064, 'ruRU', 'Вы выяснили, что задумал клан Зловещего Тотема?', 0),
	(5082, 'ruRU', 'Буду очень признательна за помощь!', 0),
	(5083, 'ruRU', 'Что это у тебя?', 0),
	(5085, 'ruRU', 'Надеюсь, вы что-нибудь нашли, $N. Фурболги племени Зимней Спячки становятся всё агрессивнее!', 0),
	(5086, 'ruRU', 'Я думаю, мы начинаем понимать, что тут происходит, $N.', 0),
	(5087, 'ruRU', 'Посмотрим, что случится, когда фурболги племени Зимней Спячки не получат своей огненной воды!', 0),
	(5088, 'ruRU', 'Вы убили смертоносную змею Арикару, $N?', 0),
	(5089, 'ruRU', 'Что там у тебя, $N?', 0),
	(5092, 'ruRU', 'Я хочу, чтобы ты $Gприготовился:приготовилась; к худшему, - копай глубже. Стоящая перед нами задача будет непростой. Когда мы соберем здесь наши силы, чтобы в конечном итоге нанести удар по Плети, вы станете частью наших передовых сил, которые пойдут на битву с ними! Данное вам задание на Холме Печали станет началом нашего пути к победе!', 0),
	(5097, 'ruRU', 'Как только башни будут отмечены, они станут первоочередными целями для нашей атаки на Андорал. Я подозреваю, что как только мы нейтрализуем башни, появится главная угроза Андорала. С этого момента у нас будет прямая борьба за контроль над городом!$B$BВы вернулись, чтобы сообщить об успехе, да? Не забудьте про сигнальный факел; мы должны сохранять контроль над нашим оборудованием.', 0),
	(5098, 'ruRU', 'Как только башни будут отмечены, они станут первоочередными целями для нашей атаки на Андорал. Я подозреваю, что как только мы нейтрализуем башни, появится главная угроза Андорала. С этого момента у нас будет прямая борьба за контроль над городом!$B$BВы вернулись, чтобы сообщить об успехе, да? Не забудьте про сигнальный факел; мы должны сохранять контроль над нашим оборудованием.', 0),
	(5121, 'ruRU', 'Может, ты узнаешь больше в Деревне Зимней Спячки, $N.', 0),
	(5123, 'ruRU', 'Что это у тебя, $N?', 0),
	(5124, 'ruRU', 'Время – деньги, $N. И того, и другого мне всегда не хватает.', 0),
	(5128, 'ruRU', 'Изумрудный Круг благорасположен ко всем, $C. Чем я могу вам помочь?', 0),
	(5147, 'ruRU', 'Есть новости об этом убийце, Арнаке Зловещем Тотеме?', 0),
	(5149, 'ruRU', 'Ты нашел мою куклу?', 0),
	(5151, 'ruRU', 'Нашелся мой гипервместитель?', 0),
	(5153, 'ruRU', 'Ты очень вовремя. Часом не из будущего явился?', 0),
	(5154, 'ruRU', 'Ты нашел книгу, $N?', 0),
	(5155, 'ruRU', 'Как продвигается твой бой, $N? Я знаю, что пролитие крови в качестве доказательства чести может вызывать у некоторых отвращение, но ты должен понять, что это служит двум целям: вы облегчите мою задачу, нанеся ущерб их количеству, и мы завоюем уважение друг к другу, которое только сделает нас сильнее в будущем.$B$BНадеюсь, ты понимаешь.', 0),
	(5156, 'ruRU', 'Надеюсь, твои поиски пройдут успешно, $N. Я еще не начал двигаться так далеко на север, но признаю, мысль о том, что по пути я могу встретить инферналов, меня немного пугает. Хоть у них и нет разума, но всё же они довольно устрашающие.', 0),
	(5157, 'ruRU', 'Как только у нас будет вода из Лунного колодца, мы ее очистим и с её помощью погасим эти жаровни защиты в Оплоте Теней. Это даст мне достаточно времени, чтобы заглянуть в еще более глубокие чертоги и понять, кто же на самом деле возглавляет этот... культ.$B$BМолю Мать-Землю о помощи!', 0),
	(5158, 'ruRU', 'Чую, ты не $Gпростой:простая; $Gпутешественник:путешественница;, что ищет дорогу в Кабестан. Заходи, садись, отдохни у нас в лагере. Отдохнешь – тогда и поговорим.', 0),
	(5159, 'ruRU', 'Вижу, ты $Gвернулся:вернулась;, $N. Это хорошо. Ты $Gнашёл:нашла; Ислен в Степях? Или нам придется искать другой путь к нашей цели?', 0),
	(5160, 'ruRU', 'Рада видеть тебя, $N.', 0),
	(5163, 'ruRU', 'Жду, не дождусь, так хочется услышать, как реагировали мои друзья!$B$BТакого они никак не могли ожидать!', 0),
	(5165, 'ruRU', 'Жаровни должны быть потушены, если мы хотим иметь хоть какую-то надежду подготовиться к гораздо более серьезной битве. Идти в логово дракона без всякого ведома - глупая затея. И это намного хуже дракона. Совет Теней несет полную ответственность за множество преступлений и злодеяний. Придется действовать быстро, чтобы их остановить.', 0),
	(5212, 'ruRU', 'Некоторые считают, что у меня параноя, а я вот отвечу: \\"Бди! Вирус не дремлет!\\"', 0),
	(5213, 'ruRU', 'Мы на пороге открытия! Скоро мы узнаем, на чем основана устойчивость вируса чумы.', 0),
	(5214, 'ruRU', 'Я сам не справлюсь, $N! Помоги старику...', 0),
	(5216, 'ruRU', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', 0),
	(5217, 'ruRU', 'Добро пожаловать в Лагерь Промозглого Ветра, $N. Наслаждайся ощущением безопасности. Как дела с котлами?', 0),
	(5218, 'ruRU', 'Чумной котёл Плети стоит перед вами, извергающий огромное количество токсинов в воздух.$B$BПоразив хранителя котла и получив ключ, вы можете сами добавить реагенты.', 0),
	(5219, 'ruRU', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', 0),
	(5220, 'ruRU', 'Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.', 0),
	(5221, 'ruRU', 'Чумной котёл Плети стоит перед вами, извергающий огромное количество токсинов в воздух.$B$BПоразив хранителя котла и получив ключ, вы можете сами добавить реагенты.', 0),
	(5222, 'ruRU', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', 0),
	(5223, 'ruRU', 'Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!', 0),
	(5224, 'ruRU', 'Чумной котёл Плети стоит перед вами, извергающий огромное количество токсинов в воздух.$B$BПоразив хранителя котла и получив ключ, вы можете сами добавить реагенты.', 0),
	(5225, 'ruRU', 'Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.', 0),
	(5226, 'ruRU', 'На пустоши Гаррона находится последний котел на востоке, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел\'Тузада ее не спасет.', 0),
	(5227, 'ruRU', 'Чумной котёл Плети стоит перед вами, извергающий огромное количество токсинов в воздух.$B$BПоразив хранителя котла и получив ключ, вы можете сами добавить реагенты.', 0),
	(5242, 'ruRU', 'Теперь, без Фел-дана, Совет Теней потеряет цель и будет беспомощен. Они перегрызутся между собой за власть и сокровища - плату за будущие планы. А мы воспользуемся этим времением и вырежем и их, и их рабов-демонов.', 0),
	(5243, 'ruRU', 'Учти, далеко не все ящики припасов в разрушенном городе остались в целости и сохранности. Воины Плети боятся святой воды, однако она не является препятствием для диких зверей.', 0),
	(5245, 'ruRU', 'Что привело тебя сюда?', 0),
	(5246, 'ruRU', 'Лишь по страницам священных записей я разберу, смогу ли помочь вам или нет…', 0),
	(5247, 'ruRU', 'Реликвия должна быть в руках только того, кто заслуживает абсолютного доверия. Она не должна быть вновь похищена…', 0),
	(5248, 'ruRU', 'Прррроооокляааат.. Навееечноооо...', 0),
	(5252, 'ruRU', 'Прошло довольно много времени после твоего ухода, $N. Как прошло путешествие?', 0),
	(5253, 'ruRU', 'Да, $R?', 0),
	(5261, 'ruRU', 'Как прошла охота, $N Ты $gобнаружил:обнаружила; и $gуничтожил:уничтожила; этих вредителей?', 0),
	(5262, 'ruRU', 'С чем пожаловал, $N?', 0),
	(5283, 'ruRU', 'Ах, нет ничего краше доброго кузнечного загара. Сразу видно, у кого славный загар, по белым полосам от передника.', 0),
	(5284, 'ruRU', 'Железнус деловито складывает золотые монеты в аккуратные столбики.', 0),
	(5305, 'ruRU', 'Его фартук! Где он?', 0),
	(5306, 'ruRU', 'Легенда гласит, что если хотя бы раз применить змеекамень Вос\'гаджин, лезвие топора останется острым на тысячу лет!', 0),
	(5307, 'ruRU', 'Вы что, забыли, какое у вас задание, $N?', 0),
	(5321, 'ruRU', 'Прибыл ли Керлониан?', 0),
	(5343, 'ruRU', 'Позаботься о моей будущем, а я позабочусь о твоем.', 0),
	(5344, 'ruRU', 'Ты хочешь денег, да?', 0),
	(5361, 'ruRU', 'Что у вас за новости, |3-6($C)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!', 0),
	(5381, 'ruRU', 'Эй, $N, а где демоническая шкатулка?', 0),
	(5386, 'ruRU', 'У меня копыта подергиваются и слюни текут от нетерпения, как подумаю о жареном кровобрюхе... Ты ведь принес мне кровобрюха, верно?', 0),
	(5402, 'ruRU', 'Камень приспешника Плети  – знак различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово слабый – относительное понятие. Не стоит недооценивать Плеть.$B$BОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.', 0),
	(5403, 'ruRU', 'Камень захватчика Плети – знак различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.$B$BСеребряный Рассвет вручает знак доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.', 0),
	(5404, 'ruRU', 'Камень осквернителя Плети – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!$B$BОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, $N – с этими тварями шутки плохи.', 0),
	(5406, 'ruRU', 'Камень осквернителя Плети – знак различия предводителей Плети. Он есть у каждого обладающего властью в Плети. Убийство этих проклятых тварей служит благу Серебряного Рассвета... да и вообще всеобщему благу!$B$BОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, $N – с этими тварями шутки плохи.', 0),
	(5407, 'ruRU', 'Камень захватчика Плети – знак различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.$B$BСеребряный Рассвет вручает знак доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.', 0),
	(5408, 'ruRU', 'Камень приспешника Плети  – знак различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово слабый – относительное понятие. Не стоит недооценивать Плеть.$B$BОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.', 0),
	(5441, 'ruRU', 'Негодяи, бездельники…\n\nЧто? Где моя дубинка? Ну что, удалось тебе всыпать этим лентяям?', 0),
	(5481, 'ruRU', 'Где это никчемное поганище? Ты принес мне то, что мне нужно? Если нет, то иди и не возвращайся, пока не соберешь достаточно цветков!', 0),
	(5482, 'ruRU', 'Я полагаю, ты уже собрал достаточно погибельника?', 0),
	(5501, 'ruRU', 'Ну, где они, мои косточки, где же они? Караван вот-вот придет. Всего десять костей – и это будет мой звездный час, клянусь чем угодно! Вот увидишь!', 0),
	(5508, 'ruRU', 'Камень осквернителя Плети – знак различия предводителей Плети. Их всегда можно найти у наиболее могучих тварей. Конечно, для этого придется их убить, тем самым способствуя делу Серебряного Рассвета и добра вообще!$B$BОт имени Серебряного Рассвета я вручу тебе по знаку доблести за каждый из этих знаков. Только соблюдай осторожность, $N – с этими тварями шутки плохи.', 0),
	(5509, 'ruRU', 'Камень захватчика Плети – знак различия элитных войск Плети. Порой их можно найти у сильных бойцов в Чумных землях. Убить таких бойцов – настоящий подвиг, который должно совершать во имя борьбы со злом.$B$BСеребряный Рассвет вручает знак доблести в обмен на десять таких камней. Принеси их мне, и непременно получишь достойную награду.', 0),
	(5510, 'ruRU', 'Камень приспешника Плети  – знак различия Плети. Иногда их можно найти у нежити, у более слабых бойцов, хотя слово слабый – относительное понятие. Не стоит недооценивать Плеть.$B$BОт имени Серебряного Рассвета я готов вручить тебе по знаку доблести за каждые двадцать камней, причем с радостью – чем больше ты убьешь приспешников Плети, тем лучше.', 0),
	(5513, 'ruRU', 'А, благородный $C)! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.', 0),
	(5515, 'ruRU', 'Эва то появляется, то исчезает.', 0),
	(5527, 'ruRU', 'Реликварий Чистоты – удивительный предмет сам по себе. Их было сделано очень мало, и почти все они были утрачены за прошедшие века.$B$BНадо признать, я давно узнал о том, что деревне Южного Ветра хранится один из этих артефактов. Но после начала треволнений в Силитусе я решил, что эта тайна должна остаться тайной. Расспрашивать – лишь вызывать подозрения у наших врагов.$B$BУвы, спокойное время миновало, особенно учитывая нынешнюю ситуацию в Эльдре\'Таласе.', 0),
	(5535, 'ruRU', 'Как идут поиски духов высокорождённых, $N?$B$BАзерот видел много бедствий, однако эти духи являют собой одно из самых серьезных. Возможно, дело в их всепоглощающей тяге к тайной магии. Ты знаешь, что эта тяга ведет за собой Пылающий Легион... И ты знаешь, чем всё это может закончиться.', 0),
	(5536, 'ruRU', 'Как продвигается твоя битва с сатирами, $N?$B$BОни такие сильные, как вы думали? Сильнее? Или, может быть, они были ничем для вас.', 0),
	(5537, 'ruRU', 'Как бы гнусно это ни звучало, для создания ключа нам нужен солидный запас фрагментов скелетов. Недаром его назвали Костяным ключом', 0),
	(5538, 'ruRU', 'Да, я знаю, кто ты и зачем пришел. Арбингтон послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!', 0),
	(5541, 'ruRU', 'Надеюсь, ты не за боеприпасами $gпришел:пришла;, потому как они у меня почти закончились!', 0),
	(5561, 'ruRU', 'Караван скоро будет здесь. Надеюсь, ты привел новых прирученных кодо? Да? Да?', 0),
	(5723, 'ruRU', 'Что ж, по крайней мере, ты пока цел. А сокровище нашел?', 0),
	(5724, 'ruRU', 'Удалось ли что-нибудь найти, $N? Хоть какой-нибудь намек на то, почему ее сородич погиб без нужды?', 0),
	(5725, 'ruRU', 'Меня ждет сотня дел, |3-6($C). Где книги?', 0),
	(5726, 'ruRU', 'Ну что, $N, удалось тебе добыть знак отличия? Он необходим, чтобы внедриться в организацию, которая представляет собой самую серьезную угрозу Орде.\n\nТы еще узнаешь, насколько замысловатую сеть способны сплести как орки, так и люди, ведомые алчностью и жаждой власти. Тебе станут очевидны их козни и тайные помыслы. Ты обнаружишь, что вокруг тебя идет война, какая тебе и не снилась!', 0),
	(5727, 'ruRU', 'Демон Бездны – создание могущественное! Я помню, как боролся с ним, когда был в твоем возрасте, $N. С годами мой демон стал меньше сопротивляться – но подозреваю, он просто надеется, что я утрачу бдительность.\n\nНе забывай этого, $N!', 0),
	(5728, 'ruRU', 'Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!', 0),
	(5729, 'ruRU', 'Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!', 0),
	(5730, 'ruRU', 'Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!', 0),
	(5741, 'ruRU', 'Ты нашел Скипетр Света? Он у тебя?', 0),
	(5761, 'ruRU', 'Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!', 0),
	(5762, 'ruRU', 'Уж не пустынная ли это пыль у вас на воротнике?\n\nХм... Если мой нос не врет, то это не пыль, а соль! Были на Мерцающей равнине, да?', 0),
	(5763, 'ruRU', 'Присядь и отдохни, |3-6($C). Скоро ты снова отправишься в джунгли...', 0),
	(5801, 'ruRU', 'Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.', 0),
	(5803, 'ruRU', 'Ты сумел далеко зайти, $N – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Араджа – любым из возможноых способов – и принеси мне, и я сделаю из него головку ключа.', 0),
	(5863, 'ruRU', 'Я обеспокоена! Пожалуйста, будь $Gосторожен:осторожна;!', 0),
	(5881, 'ruRU', 'У тебя какие-то новости от землепряда Магграна?', 0),
	(5882, 'ruRU', 'Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.$B$BЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.', 0),
	(5883, 'ruRU', 'Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.$B$BЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.', 0),
	(5884, 'ruRU', 'Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.$B$BВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.', 0),
	(5885, 'ruRU', 'Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!$B$BКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.', 0),
	(5886, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!', 0),
	(5887, 'ruRU', 'Обладание Маяком Кенария позволяет увидеть оскверненные осколки души затронутых порчей животных, убитых ради вящего блага. Я измельчаю эти осколки и делаю из них реактив, который идет на изготовление кенарийского бальзама исцеления растений. Мы используем это средство для исцеления пораженных порчей растений.$B$BЗа эти осколки я дам тебе немного уже готового кенарийского бальзама исцеления растений.', 0),
	(5888, 'ruRU', 'Если во время поиска ископаемых в Оскверненном лесу у тебя будет с собой Маяк Кенария, ты сможешь найти порченый купорос, проникающий в жилы металлов. Я знаю, как очищать этот купорос и превращать его в реактив, который идет на изготовление кенарийского бальзама исцеления растений. Затем этим бальзамом можно исцелять пораженные растения.$B$BЕсли ты принесешь мне порченого купороса, я дам тебе уже готового кенарийского бальзама исцеления растений.', 0),
	(5889, 'ruRU', 'Маяк Кенария позволяет опрытному травнику замечать коварный зародыш Скверны – мерзостный результат поразившей Оскверненный лес порчи. В результате долгих моих трудов здесь мне удалось научиться преврашать зародыш Скверны в очищающее вещество... которое мы используем для приготовления так называемого кенарийского бальзама исцеления растений.$B$BВо время сбора растений в Оскверненном лесу ты сможешь замечать зародыш Скверны, пока на тебе лежит заклятие Маяк Кенария. За то, что ты мне принесешь, я дам тебе уже готового кенарийского бальзама.', 0),
	(5890, 'ruRU', 'Маяк Кенария позволяет опытному специалисту по снятию шкур находить куски пораженных порчей шкур среди добытого в Оскверненном лесу добра. Я перерабатываю эти вроде бы бесполезные обрывки в густую пасту, которая ускоряет действие кенарийского бальзама исцеления растений. Когда ты будешь свежевать туши убитых в Оскверненном лесу животных, позаботься, чтобы на тебе лежало заклятие Маяка Кенария!$B$BКогда соберешь порченые клочки, принеси их мне, и я дам тебе немного готового кенарийского бальзама исцеления растений.', 0),
	(5891, 'ruRU', 'Сила магического предмета соответствует силе эссенций, получающихся в результате его распыления. Мной изобретен способ переработки сырой субстанции, используемой зачаровывателями, в реактив, пригодный для создания кенарийского бальзама исцеления растений. Для этого тебе не нужен Маяк Кенария. Подойдет любой предмет, с которого сняты чары, и который выделяет простую субстанцию Пустоты.$B$BМне нужна всего одна порция простой субстанции Пустоты, а за это я тебе дам кенарийского бальзама исцеления. Эта субстанция чрезвычайно сильна – даже малого количества хватит надолго!', 0),
	(5903, 'ruRU', 'Ну как, нашел термитники, $N? Их полно в Проклятых землях.', 0),
	(5921, 'ruRU', 'Вы прибыли из Тельдрассила? Скажите, как там ловится рыба?', 0),
	(5925, 'ruRU', 'Похоже, ты что-то хочешь мне рассказать, $N Ты что-то знаешь о древесниках?', 0),
	(5929, 'ruRU', 'Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.', 0),
	(5931, 'ruRU', '$N вы уже вернулись из Аубердина? Вы говорили с Лайрдом?', 0),
	(6001, 'ruRU', 'Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.', 0),
	(6021, 'ruRU', 'Ты $Gнашёл:нашла; их убежище, $N? $GСправился:Справилась; с Зельдарром?', 0),
	(6026, 'ruRU', 'Верь старине Дымку, $R, дело стоящее. Серебряный Рассвет за копейку не удавится.', 0),
	(6027, 'ruRU', 'Ах, $N, как я рад тебя видеть! Ну как, есть при тебе Книга Древних?', 0),
	(6028, 'ruRU', 'Приветствую, $C. От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Лагеря Промозглого Ветра. Так же я могла бы подыскать для вас подходящее дело...', 0),
	(6030, 'ruRU', 'Да пребудет с вами Свет, в эти темные времена, $C. Что привело вас сюда, в этот последний оплот надежды среди тьмы и отчаяния?', 0),
	(6031, 'ruRU', 'Ты $Gпринёс:принесла; рунную ткань? Мой народ сгорает от нетерпения получить одежду из рунической ткани!', 0),
	(6062, 'ruRU', 'Удачи тебе, юный охотник!', 0),
	(6082, 'ruRU', 'Ну что, удалось тебе укротить бронескорпида?', 0),
	(6083, 'ruRU', 'Тебе нужно тренироваться, чтобы набраться опыта в укрощении питомцев. Удалось ли тебе приручить приливного краба?', 0),
	(6134, 'ruRU', 'Эй, $N, где моя эктоплазма?', 0),
	(6142, 'ruRU', 'Поскорее бы порыбачить на наживку из мяса моллюсков!.. Ты ведь принес мне 10 наживок, как я просила?', 0),
	(6143, 'ruRU', 'Ты нашел Скипетр Света? Он у тебя?', 0),
	(6161, 'ruRU', 'Сундук надежно заперт...', 0),
	(6181, 'ruRU', 'Такое ощущение, что вы сильно торопитесь. Что ж, если так, то вы пришли в правильное место!', 0),
	(6261, 'ruRU', 'Да вы вспотели, $gсударь:сударыня;! Не стоило так много бегать на своих двоих. В следующий раз возьмите грифона!', 0),
	(6281, 'ruRU', 'Путешествовали, да? Видели что-нибудь интересненькое?', 0),
	(6282, 'ruRU', 'Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая расползаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Когтя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?', 0),
	(6283, 'ruRU', 'Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!', 0),
	(6284, 'ruRU', 'Бесселет – безжалостный хищник... Я опасаюсь за тех, кто путешествует по Паучему Тракту ночами. Именно тогда Бесселет и ее отродья охотятся на ничего не подозревающих путников. Я сам едва не стал жертвой ее полуметровых смертоносных клыков, но, к счастью, сумел отбиться и убежать. Я отдам что угодно за то, чтобы это чудовище было уничтожено.', 0),
	(6285, 'ruRU', 'Вы уже вернулись из Штормграда? Озрик прислал доспехи?', 0),
	(6301, 'ruRU', 'Страшные разрушения, причиненные войной и теми, кто наживался на лесозаготовках, глубоко ранят мою душу. Чтобы начать цикл возрождения и оживить эти земли, мне нужны семена Геи. Есть ли они у тебя, |3-6($C)?', 0),
	(6321, 'ruRU', 'Похоже, вы пришли по серьезному делу?', 0),
	(6322, 'ruRU', 'Если вам нужно преодолеть большое расстояние, удобнее всего сделать это на летучей мыши.', 0),
	(6323, 'ruRU', 'Я держу оружие в отличном состоянии. Все почищено и готово к использованию.', 0),
	(6324, 'ruRU', 'Вы вернулись, $N. Привезли наши припасы из Подгорода?', 0),
	(6341, 'ruRU', 'Чем могу помочь? Нужен транспорт?', 0),
	(6342, 'ruRU', 'Вы прибыли из Тельдрассила? Скажите, как там ловится рыба?', 0),
	(6343, 'ruRU', '$N, ты уже $gвернулся:вернулась; из Аубердина? $gГоворил:Говорила; с Лайрдом?', 0),
	(6344, 'ruRU', 'В великой печали даю я тебе это поручение, но у нас нет надежды исцелить леди Сатру.\n\nМы надеемся, что если принести серебряные паутинные железы в жертву Элуне, то она благословит Сатру, и та возродится с покоем в душе.', 0),
	(6365, 'ruRU', 'Хочешь куда-то добраться в мгновение ока? Тогда ты обратился по адресу!', 0),
	(6381, 'ruRU', 'Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая расползаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Когтя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?', 0),
	(6384, 'ruRU', 'Какой вкусный запах! Ты часом не сырое мясо несешь?', 0),
	(6385, 'ruRU', 'Тебе нужен ветрокрыл?', 0),
	(6386, 'ruRU', 'Ты вернулся из Оргриммара? Гришак понравилось мясо?', 0),
	(6387, 'ruRU', 'Надоел Телcамар? $GРешил:Решила; слетать в другой город?', 0),
	(6388, 'ruRU', 'Похоже, ты $gсобрался:собралась; куда-то лететь. Хочешь нанять грифона?', 0),
	(6389, 'ruRU', 'Тебе удалось, $N? Выпустил термитов? Нельзя допустить, чтобы в руках Алого ордена оказалась и лесопилки, и Дольный Очаг. Нет уж, пусть лучше останутся вовсе с пустыми руками. Они лишь умножают наши и без того многочисленные жертвы в последней войне. Нет им пощады!', 0),
	(6391, 'ruRU', 'Чем я могу вам помочь, $gгосподин:госпожа;?', 0),
	(6392, 'ruRU', 'А, $N. Ты уже $gвернулся:вернулась; из Стальгорна?', 0),
	(6393, 'ruRU', 'Совет Приливов проявляет нетерпение. Они желают положить конец войне, которая вот уже не одну эпоху идет во всех измерениях. Мои собратья жаждут услышать новости о грандиозной победе над ненавистными элементалями огня. Где же огненные кристаллы, что так нужны мне?', 0),
	(6394, 'ruRU', 'Ну что, $N, удалось тебе проникнуть в грот? А кирку мою нашла?', 0),
	(6395, 'ruRU', 'Они просто идиоты... копающие себе могилы.', 0),
	(6421, 'ruRU', 'Какие новости из Ущелья Камнепадов? Я вспомнил, что существует легенда, в которой говорится о резоните... Но не за что ухватиться. Быть может, узнав, что таится на дне пещеры, мы сможем пролить свет на их зловещие намерения.', 0),
	(6441, 'ruRU', 'Надеюсь, вы поторопитесь добыть мне эти рога, $N. Я скоро возвращаюсь в Кабестан!', 0),
	(6442, 'ruRU', 'Наг все больше и больше, $N. Прошу, сделай это для меня.', 0),
	(6461, 'ruRU', 'Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!', 0),
	(6462, 'ruRU', 'Ты нашел обереги, $N? Моя кровь кипит от гнева, что эти священные обереги в руках фурболгов!', 0),
	(6481, 'ruRU', 'Я боюсь, что если мы не избавимся от этой угрозы немедленно, весь Каменный Коготь падет. Мощь земельника несравнима ни с какой другой. По пробуждении Гоггерок будет ослаблен долгим сном, и тебе следует воспользоваться этим. Иди же, $N!', 0),
	(6482, 'ruRU', 'Еще раз привествую тебя, $N! Ты пришел показать мне свои охотничьи трофеи?', 0),
	(6504, 'ruRU', 'Надеюсь, ты быстро найдешь эти страницы, $N! Мне очень надо скорее вернуться к работе!', 0),
	(6521, 'ruRU', 'Ты нашел посланника, $N? Надеюсь, он мертв? Мы не можем позволить Плети закрепиться в Калимдоре. Довольно и того, что они постоянно осаждают наши границы – не хватало еще отбиваться от них на двух фронтах! Единственное, что радует меня в принесенных тобой вестях, – что старая ведьма, похоже, не подверглась скверне. В глубине души она понимала, что Плеть может наделить ее огромной властью, и все же осознавала, что, заключи она союз с нежитью, Степи перестанут быть ее истинной вотчиной.', 0),
	(6522, 'ruRU', 'С чем пожаловал, $N? Надеюсь, это действительно важное дело – я не люблю, когда мне докучают по пустякам.', 0),
	(6541, 'ruRU', 'Я очень занята, |3-6($C). Если ты пришел не по важному делу, иди своей дорогой...', 0),
	(6543, 'ruRU', 'Торопись, $N. Они должны получить указания, это срочно.', 0),
	(6544, 'ruRU', 'Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!', 0),
	(6548, 'ruRU', 'Тебе удалось их убить?', 0),
	(6561, 'ruRU', 'Да пребудет с тобой милость Матери-Земли, $N. \n\nМы должны стремиться к гармонии и согласию во всем мире. Все происходит по воле Матери-Земли, и все мы – орудия в ее руках.', 0),
	(6562, 'ruRU', 'Так у тебя есть для меня приказ? Всегда приятно увидеть новобранца с горячей душой и твердой волей.\n\nТебе нужна хорошая соображалка, если хочешь задержаться здесь. Наги все сильнее угрожают нам, $N. Я сам видел. А с тех пор как я сюда прибыл, мне несколько раз приходилось отбивать их нападения на этой самой заставе.\n\nНо если тебе охота поучаствовать в этом, поговори с кем-нибудь еще на заставе.', 0),
	(6563, 'ruRU', 'Как поиски кристаллов, $N? Ты видел, как наги их собирают? Я молю своих предков, чтобы нам удалось понять, зачем им это.', 0),
	(6564, 'ruRU', 'Да, $N? В чем дело? Мне еще многое нужно узнать об этих кристаллах, что собирают наги.', 0),
	(6565, 'ruRU', 'Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.', 0),
	(6571, 'ruRU', 'Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!', 0),
	(6581, 'ruRU', 'Прямо из Кабестана, свежие лезвия для пил Песни Войны! Да, они у меня с собой.$B$BНо чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!$B$BЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защитить себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.$B$BИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?', 0),
	(6607, 'ruRU', 'Ну как, сегодня клев был?', 0),
	(6610, 'ruRU', 'Мне скоро конец придет от голода! Быстрей, $N – а то мне придется залезть в собственную заначку.', 0),
	(6621, 'ruRU', 'Ты победил вождя Мургута, $N? принес его тотем Гиблой Чащи?', 0),
	(6627, 'ruRU', 'Осталось недолго, $N, честное слово. Одеяние неплохо послужит тебе и даст преимущество над противниками.', 0),
	(6628, 'ruRU', 'Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.', 0),
	(6641, 'ruRU', 'Так у тебя есть для меня приказ? Всегда приятно увидеть новобранца с горячей душой и твердой волей.\n\nТебе нужна хорошая соображалка, если хочешь задержаться здесь. Наги все сильнее угрожают нам, $N. Я сам видел. А с тех пор как я сюда прибыл, мне несколько раз приходилось отбивать их нападения на этой самой заставе.\n\nНо если тебе охота поучаствовать в этом, поговори с кем-нибудь еще на заставе.', 0),
	(6661, 'ruRU', 'Аррр... Мы еще долго будем ждать?', 0),
	(6662, 'ruRU', ' Нипси просовывает указательный палец в одно из отверстий для доступа воздуха, проделанных в коробке. $b$bЖивенькие-здоровенькие... и как раз вовремя!', 0),
	(6921, 'ruRU', 'Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.', 0),
	(6922, 'ruRU', 'О, привет еще раз, $N. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя в форт?', 0),
	(6981, 'ruRU', 'Приветствую тебя, |3-6($R). Я могу тебе чем-то помочь?', 0),
	(7025, 'ruRU', 'От всех этих разговоров об угощении у меня самого аппетит разыгрался. Мммм... Прянички с молочком...', 0),
	(7028, 'ruRU', 'Не задавай лишних вопросов!$B$BЗаказ есть заказ.', 0),
	(7041, 'ruRU', 'Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, $N…', 0),
	(7043, 'ruRU', '$N, без этих лакомств наш праздник Зимнего Покрова будет загублен на корню! Можете себе представить: все послушные детки останутся без знаменитых пирожков Гракку!', 0),
	(7044, 'ruRU', 'Я очнулся от нескончамого кошмара...', 0),
	(7066, 'ruRU', 'От тебя несет скверной, как от большинства искателей приключений наших дней. Но ты отличаешься от остальных. О чем ты хочешь со мной поговорить? Я чую что-то знакомое, но не могу понять, что именно.$B$BПрошу тебя, скажи, почему ты хотел поговорить со мной?', 0),
	(7067, 'ruRU', 'Что ты решил, $N? Ты сможешь мне помочь? Ступишь ли ты на священную землю, чтобы помочь мне создать единый народ кентавров?!', 0),
	(7070, 'ruRU', 'Ты уже побывал в Мараудоне? Понимаю, дело это опасное, но если ты достигнешь успеха, награда с лихвой окупит затраченные усилия.', 0),
	(7321, 'ruRU', 'Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...', 0),
	(7383, 'ruRU', 'Друиды, Древо-оракул и верховный друид тщательно наблюдали за ростом Тельдрассила. Но хотя мы и обрели новый дом, бессмертие к нам не вернулось.', 0),
	(7429, 'ruRU', 'Эта вещь называется "ключ от оков Гордока" – по крайней мере, так называют его эти "остроумцы". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…$b$bНо о чем я говорю? Он у вас есть, да? Он при вас?!', 0),
	(7484, 'ruRU', 'Снова ты? Ну, а теперь-то тебе чего надо?', 0),
	(7485, 'ruRU', 'Радуйся, что я такой терпеливый, а то бы я тебе...', 0),
	(7488, 'ruRU', 'Ну что, $N, сеть у тебя? Скопившуюся в ней магическую энергию необходимо рассредоточить!', 0),
	(7490, 'ruRU', 'Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!', 0),
	(7491, 'ruRU', 'Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!', 0),
	(7637, 'ruRU', 'Приветствую тебя, благородный ! Я наполнил свою верную курильницу свежайшими благовониями и трижды благословил ее специально для тебя. Твое пожертвование поможет нам здесь, в Стальгорне, не только изготовить новую курильницу, но также пополнить оскудевающие запасы пищи для наших нужд.', 0),
	(7639, 'ruRU', 'С возвращением, $N. Вы принесли курильницу экзорцизма?', 0),
	(7640, 'ruRU', 'Приятно вновь увидеться с тобой, $N. Завершена ли твоя работа в Долине Ужаса?', 0),
	(7642, 'ruRU', 'А, это ты, $N. Я не смогу закончить изготовление чепрака без тех вещей, о которых я тебе говорил. Удалось ли тебе собрать все?', 0),
	(7643, 'ruRU', 'Дух древнего коня внимательно взирает на вас – так, словно ждет чего-то.', 0),
	(7644, 'ruRU', '$N, ты вернулся! Ну что, удалось тебе справиться с Меридет Карлсон и Тендрисом Тенеломом? Честно говоря, даже и не знаю, кто из них опаснее...', 0),
	(7645, 'ruRU', 'Да, я доказала, что ты неправ? Все они ошибались! Я БЫЛА ПРАВА ВСЕ ЭТО ВРЕМЯ!!!', 0),
	(7646, 'ruRU', 'Ты продвинулся уже так далеко, $N. Твой последний акт жертвования мирскими вещами станет залогом одного из твоих величайших достижений. Я это чувствую всем своим существом!', 0),
	(7647, 'ruRU', 'Дух зловещего рыцарского коня смотрит на вас тоскливым взором. В его мертвых глазах уже давно погас огонь надежды.', 0),
	(7648, 'ruRU', 'А вы неплохо показали себя, $N. Как только чепрак будет готов, вы отправитесь на следующий подвиг.', 0),
	(7653, 'ruRU', 'За чертежи пояса я прошу 20 слитков тория.', 0),
	(7654, 'ruRU', 'За чертежи этих сапог я хочу как минимум 40 слитков тория. Точно, 40. Ну не плачь, $Gсынок:дочка;, хочешь носовой платок?$B$B<Деротайн смеется.>', 0),
	(7655, 'ruRU', 'Для изготовления наручей мне понадобится 20 слитков тория…$B$BС тобой все в порядке, $Gсынок:дочка;? Что-то ты $Gпокраснел:покраснела;...', 0),
	(7656, 'ruRU', 'Для чертежей нагрудного доспеха мне нужно будет 60 слитков тория.$B$BИ что ты опять ноешь? Опять будешь жаловаться своим божкам, спрашивая, почему они отреклись от тебя?! Держись, $Gприятель:подруга;! Никто и никогда не говорил, что жизнь справедлива.', 0),
	(7657, 'ruRU', 'С тебя 50 слитков тория, и чертежи шлема – твои.', 0),
	(7658, 'ruRU', 'Просто отдай 30 ториевых слитков, и чертежи штанов твои.$B$BЯ знаю, я тебя веду к банкротству! Я все это слышал раньше, так что ты можешь сохранить свою слезливую историю, $Gслабак:слабачка;.', 0),
	(7659, 'ruRU', 'За чертежи наплечников я прошу 20 слитков тория.', 0),
	(7791, 'ruRU', 'Мы всегда готовы принять шерсть в качестве пожертвования. Шестьдесят отрезов – дар, который жители Штормграда запомнят надолго. Ты ведь знаешь пословицу: "С миру по нитке – голому рубашка". А нам очень нужна шерсть!$B$BЕсли у тебя есть 60 отрезов шерстяной ткани и ты хочешь сделать пожертвование, то я могу принять дар прямо сейчас.', 0),
	(7792, 'ruRU', 'Мы занимаемся сбором шерстяной ткани. Если вы пожертвуете на благие цели 60 отрезов, то заслужите признательность всего народа.$b$bЕсли у вас есть 60 отрезов, можете пожертвовать их прямо сейчас.', 0),
	(7798, 'ruRU', 'Мы занимаемся сбором шелка. Если вы пожертвуете на благие цели 60 отрезов, то заслужите признательность всего народа.\n\nЕсли у вас есть 60 отрезов, можете пожертвовать их прямо сейчас.', 0),
	(7802, 'ruRU', 'Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Стальгорна. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.', 0),
	(7848, 'ruRU', 'Только те, чья сущность в сродстве с Огненными Недрами, могут прийти через портал.', 0),
	(7905, 'ruRU', 'Да, милсдарь, чем могу служить? У вас есть сертификат на призовой билет?', 0),
	(7926, 'ruRU', 'Да, милсдарь, чем могу служить? У вас есть сертификат на призовой билет?', 0),
	(7945, 'ruRU', 'Судя по видению, вам нужен именно этот пень...', 0),
	(8042, 'ruRU', 'Приятно видеть тебя в добром здравии, $N. Каждый из нас наслышан про битвы, в которых тебе удалось одержать победу. Хаккар не должен покинуть пределы Зул\'Гуруба, иначе он поглотит весь мир!$B$BДай мне свой талисман, я наполню его силой. Используй Силу Мугамбы, чтобы покарать наших врагов!', 0),
	(8043, 'ruRU', '$GГосподин/Госпожа; $N, ты $Gвернулся:вернулась;! Молтор рассказал о твоих подвигах самому королю. Твоя слава достигла Южных морей. В один прекрасный день ты станешь $Gлегендарным:легендарной; $Gвоителем:воительницей; и войдешь в историю на века.$B$BДай мне свой талисман, я еще немного увеличу его силу.', 0),
	(8044, 'ruRU', 'Король Растахан посылает тебе слова благодарности, $Gгосподин:госпожа; $N. Подобная честь до сих пор не оказывалось ни одному чужаку.$B$B<Джинрок кланяется.>$B$BДай мне свой талисман, и я усилю его. Теперь Ярость Мугамбы неразрывно связана с твоей душой.', 0),
	(8046, 'ruRU', 'Похоже, я слишком поторопился в своих суждениях, $C. Твоя слепая вера в этот Свет чего-то стоит.$B$BДай мне свое клеймо, я увеличу его силу.', 0),
	(8047, 'ruRU', 'Должен признаться, я не думал, что у тебя хватит решимости довести это дело до конца, $C. Ты $Gстал:стала; для Зандалара бесценным союзником. В самом деле, я восхищен.$B$BДай мне свое клеймо, я увеличу его силу.', 0),
	(8048, 'ruRU', 'Король признал твое существование, $C. Вы первый в своем роде, которого Растахан принял как верного союзника Зандалара.$B$BВы будете очень вознаграждены за свои усилия. Представьте свой бренд, и я применю финальное усиление.', 0),
	(8050, 'ruRU', 'Добро пожаловать, $C. Око Зулдазара пульсирует энергией. Вы готовы сделать следующий шаг. Дай мне талисман, и я выполню наполнение.', 0),
	(8051, 'ruRU', 'Сказки о твоих битвах с Гурубаши разносятся ветром, $C. Даже члены королевской семьи начинают говорить о ваших поступках. Ходят слухи, что король Растахан даже упомянул вас по имени.$B$BПришло время наполнить Око. Дай мне талисман, и я выполню службу.', 0),
	(8052, 'ruRU', 'Если бы у нас было еще десять тысяч таких, как ты, $N. Армии Хаккара будут развеяны по ветру в мгновение ока.$B$BУвы, Око готов полностью реализовать свой потенциал. Дай это мне.', 0),
	(8053, 'ruRU', 'Ты $Gвернулся:вернулась;? Знаки Силы с тобой? Или ты просто отнимаешь у меня время?$B$BЯ надеюсь, что нет, язычник.', 0),
	(8054, 'ruRU', 'Знаки у тебя? Обагрила ли кровь врагов твои доспехи?', 0),
	(8055, 'ruRU', 'Знаки Силы у тебя? Нам необходимы могучие заклятия, заключенные в них. Если ты добудешь эти знаки, то здорово поможешь племени.', 0),
	(8056, 'ruRU', '$Gполучил:получила; нужные мне Знаки силы из Зул\'Гуруба? Эти наручи стоят любых усилий, которые вам понадобятся!', 0),
	(8057, 'ruRU', 'Ты $Gдобыл:добыла; Знаки Силы в Зул\'Гурубе? Эти наручи того стоят, Квилладру, можешь мне поверить!', 0),
	(8058, 'ruRU', 'Тебе удалось достать Знаки Силы? Свершилось ли возмездие во имя Зандалара?', 0),
	(8059, 'ruRU', 'Тебе удалось добыть Знаки Силы? Сражаясь со злобными приспешниками Хаккара, ты не только доказываешь готовность постичь пути бесноватых, но подтверждаешь для нас свою важность.', 0),
	(8060, 'ruRU', 'О, $N ты уже $Gвернулся:вернулась? Тебе удалось достать Знаки Силы?', 0),
	(8061, 'ruRU', 'Ты $Gвернулся:вернулась из Зул\'Гуруба? Удалось ли тебе получить Знаки силы у приспешников Хаккара?', 0),
	(8062, 'ruRU', 'Ступай в Зул\'Гуруб и охоться на тех, кто владеет Знаками Силы, $N. Пусть они будут твоей добычей.', 0),
	(8063, 'ruRU', 'Отыщи безумие в Зул\'Гурубе и затми его своим собственным, $N! Это означает успех, а успех - награду! Пусть Бог Крови снова не правит безраздельно!', 0),
	(8064, 'ruRU', '$Gполучил:получила нужные мне Знаки силы из Зул\'Гуруба? Пояс гаруспика будет твоим, если он у тебя есть.', 0),
	(8065, 'ruRU', '$Gполучил:получила необходимые Знаки силы из Зул\'Гуруба? Туника гаруспика стоит любых усилий, которые тебе придется приложить.', 0),
	(8066, 'ruRU', 'Ударьте безумных миньонов Хаккара в Зул\'Гурубе - это те, в чьих руках находятся Знаки силы, $N. Докажите им - и всему племени - свой успех в качестве претендента на хищник.', 0),
	(8067, 'ruRU', 'Ваши удары по Зул\'Гурубу увенчались успехом, $N? Только когда ты принесешь мне то, что я ищу - и полностью проявишь себя в племени, - ты заработаешь непревзойденную мантию среди Зандаларов.', 0),
	(8068, 'ruRU', 'Как прошел твой набег на Зул\'Гуруб? Ты $Gдовел:довела врагов до безумия, используя мастерство иллюзий? Впрочем, от чего бы они ни умерли, добытые Знаки Силы помогут нам предотвратить воцарение Хаккара.', 0),
	(8069, 'ruRU', 'Удалось ли тебе достать Знаки Силы? Я знаю, это сделать непросто... Но у меня было видение, что именно чужеземец возглавит нас и поведет на борьбу с Хаккаром. Может быть, это именно ты?', 0),
	(8070, 'ruRU', 'Образцы могущества... они у вас есть? Только когда они у нас появятся, мы сможем использовать скрытую энергию, хранящуюся в них. Было бы хорошо перевернуть столы на приспешников Кровавого Бога...', 0),
	(8071, 'ruRU', 'У тебя есть Знаки силы из Зул\'Гуруба?', 0),
	(8072, 'ruRU', 'О, ты $Gвернулся:вернулась – с тобой ли Знаки Силы? Легенды о Карвахале Безумном говорят нам, что, как бы ни был силен враг, его можно одолеть. Хаос способен поставить на колени любого, и это одна из немногих закономерностей, присущих ему.', 0),
	(8073, 'ruRU', 'С возвращением на остров, $N... ты победно $Gвернулся:вернулась с Знаками силы на буксире?', 0),
	(8074, 'ruRU', 'Знаки силы - это то, что мне нужно, мы извлечем силу прямо из них в нашей борьбе со злом из Зул\'Гуруба. У тебя есть они для меня?', 0),
	(8075, 'ruRU', 'Знаки силы - ключевой источник магической силы - той же силы, которая используется для создания кольчужной одежды авгура. Принеси мне то, что мне нужно, и я смогу поделиться лучшими облачениями, которые любой зандаларский авгур пожелает.', 0),
	(8076, 'ruRU', 'Удалось добыть Знаки Силы в Зул\'Гурубе? Чтобы победить Хаккара, нам нужна колдовская мощь, заключенная в них. Помоги нам, и ты не останешься без награды.', 0),
	(8077, 'ruRU', 'Знаки силы... ты $Gвернулся:вернулась; с ними? Только когда они у нас появятся, мы поделимся с тобой высшим символом демонической силы, $N.', 0),
	(8078, 'ruRU', 'Ты $Gпринес:принесла; Знаки Силы? Ты $Gпобедил:победила; врагов племени? Хаккар должен знать гнев мстителя!', 0),
	(8079, 'ruRU', 'Ты $Gвернулся:вернулась; с победой? Знаки Силы с тобой? Расскажи мне о совершенной мести!', 0),
	(8102, 'ruRU', 'Снова здравствуй, $C. Я вижу, камешек пригодился. Благодаря его сверхъестественной силе тебе удалось одолеть множество врагов, и они умерли в ужасных мучениях. Пришло время увеличить силу камня. Дай его мне.', 0),
	(8103, 'ruRU', 'Хаккари боятся тебя, $N. Они боятся тебя едва ли не больше, чем своего собственного безликого Кровавого бога. Ты $Gуничтожил:уничтожила; множество приспешников Хаккара с помощью силы Каджаро.', 0),
	(8104, 'ruRU', 'Дай мне талисман, $N. Я должен тебе кое-что показать.', 0),
	(8107, 'ruRU', 'В Зандаларе уважение следует заслужить, $N. Тролли предлагают свою дружбу и заключают союзы только с теми, кого они уважают.$B$BДай мне свой талисман, я наполню его силой.', 0),
	(8108, 'ruRU', 'Я готов , $C. Еще раз улучшу твой талисман. Я только прошу тебя продолжать уничтожение Хаккара и его приспешников.$B$BДай мне талисман.', 0),
	(8109, 'ruRU', 'Призови своих демонов, $C. Пусть энергия Кезанского порока напитает их. Придет время, и ты сможешь использовать их на поле боя, чтобы уничтожить своих врагов.$B$BДа... Пришло время окончательно улучшить ожерелье Кезанского порока. Дай мне свой талисман.', 0),
	(8111, 'ruRU', 'Привет, непоседа! Приятно тебя видеть снова. В племени только и разговоров, что о твоих победах в Зул-Гурубе. Молтор обмолвился, что неплохо бы добавить силы твоему талисману. Дай-ка его Майвики, посмотрим, сможет ли она его улучшить.', 0),
	(8112, 'ruRU', 'Как себя чувствует твой талисман, $N? Похоже, пришло время добавить немного магии и колдовства в его листья... А то что-то они поникли. Дай-ка мне его, Майвики сейчас все исправит.', 0),
	(8113, 'ruRU', 'Давно не виделись, $N! Известно ли тебе, что сам король Растахан приказал добавить последний магический штрих к твоему талисману? Да-да, именно так! Я бы не поверила, если бы не слышала собственными ушами. Давай талисман сюда.', 0),
	(8117, 'ruRU', 'Хорошие новости, $N. Молтор в последнее время будет петь тебе дифирамбы. Он сказал, как ты превращаешься в настоящего героя Зандалара.$B$BОн также сказал, чтобы Мэйвики отполировала ваш шар еще немного! Дай это, чтобы Мэйвики могла сделать видение ярче.', 0),
	(8118, 'ruRU', 'Ша-мон! Мэйвики пошутят!$B$B<Мэйвики смеется.>$B$BИтак, ты $Gиспользовал:использовала; духов и элементы против наших врагов в Зул\'Гуруб, а? Хвала духам!$B$BМэйвики украсит ваш ожерелье. Дай сюда, $N.', 0),
	(8119, 'ruRU', '<Мэйвики указывает на ваш талисман.>$B$BПосмотри, $N! Он ожил. Духи танцуют вокруг талисмана.$B$BОтдай его Мэйвики, чтобы она внесла последнее улучшение.', 0),
	(8142, 'ruRU', 'Впечатляет, $N. У тебя есть талант к убийству, которого я не ощущал ни у кого уже много лет. Даже Молтор знает о той работе, которую ты $Gпроделал:проделала; для Зандалара. Пора еще больше усилить талисман. Дай мне.', 0),
	(8143, 'ruRU', 'Я чувствую, что ты $Gубил:убила; хаккари, $N, бесчисленное количество раз. Ты несешь вонь их моджо.$B$BПолагаю, талисман Тени помог? Отдай его мне и позволь мне усилить его силу.', 0),
	(8144, 'ruRU', 'Он стремится к росту, $N. В талисман впиталось все, что ты $Gсделал:сделала;. Тысячи трупов троллей, усеивающих Зул\'Гуруб, подпитывают его силу. Дай его мне, и я сделаю последнее улучшение.', 0),
	(8146, 'ruRU', 'Даже отсюда я слышу звук твоих залпов, опустошающих наших врагов. Их крики разносятся эхом агонии.$B$BТы $Gпрославился:прославилась; среди троллей Зандалара, $N. Мы благодарны тебе за все, что ты $Gсделал:сделала;.$B$BДай мне свой талисман, чтобы я мог добавить еще одно плетение.', 0),
	(8147, 'ruRU', 'Ах, $N, приятно снова тебя понюхать.$B$B<Фалтир усмехается.>$B$BИзвини за мое чувство юмора. Иногда это может быть очень грязно.$B$BЯ чувствую, что Ты $Gпричинил:причинила; огромную боль нашим врагам. Силы Хаккара в гневе выкрикивают твое имя. Это превосходно.$B$BТы $Gзаработал:заработала; еще одно плетение на своем талисмане. Передай это мне', 0),
	(8148, 'ruRU', 'Молтор передает сообщение от короля Растахана, $N. Королевский двор очень впечатлен твоим уничтожением сил Хаккари. Я должен наградить тебя последним переплетением твоего талисмана. Передай мне.', 0),
	(8149, 'ruRU', 'Ты $Gсовершил;совершила; путешествие к Могиле Утера и $Gпоместил:поместила; там дань?$B$BЭто может быть опасное путешествие для менее опытных искателей приключений; условно говоря, более безопасный способ передвижения - путешествие на север от реки, протекающей через Хилсбрад, до Чумных земель. Это течет из озера, которое смежно с Холмом Скорби; отправляйтесь на запад через холмы, избегая прилегающей гробницы... той, которая кишит Плетью.', 0),
	(8150, 'ruRU', 'Ты $Gсовершил:совершила; путешествие к Памятнику Грома и $Gпоместил:поместила; его дань там?$B$BМесто, где стоит памятник, до сих пор тронуто заразой Пылающего Легиона. Если вы менее опытны в приключениях, будьте осторожны при приближении к памятнику.', 0),
	(8153, 'ruRU', '$Gпринес:принесла; рога?', 0),
	(8183, 'ruRU', '$N, ты $Gокружен:окружена темной аурой. Неужели и тебя настигло проклятие Свежевателя Душ?', 0),
	(8193, 'ruRU', 'Сегодня между 14:00 и 16:00 у нас будет проходить соревнование, чтобы определить, кто из них самый лучший рыболов! Просто будьте ПЕРВЫМ, кто принесёт мне 40 Крапчатых вкуснорыб, выловленных из Пиратской Бухты, найденных вдоль побережья Тернистой долины, и вы будете объявлены Морским дьяволом!$B$BЕсли вы не $Gпервый:первая;, кто принес мне 40 рыб, мой ученик все равно вознаградит вас деньгами за каждые 5 рыб, которые вы ей принесете.$B$BО, и не откладывайте, они быстро портятся!', 0),
	(8194, 'ruRU', 'Несмотря на то, что у нас уже есть победитель конкурса, я все равно куплю у тебя Крапчатую рыбу по разумной цене. Что ты скажешь?!', 0),
	(8196, 'ruRU', '$N, из которых можно изготовить могучий экстракт, растут на островах Южных морей. Одно-единственное манго придает и физические и душевные силы тому, кто его съест. Тебе когда-нибудь приходилось пробовать манго? Если нет, то ты много потерял!$B$BУ нас есть запасы манго, и мы охотно обменяем плоды на Почетный знак Зандалара. Если ты не знаешь, где достать знаки, поговори с Винчаксой. Приступим к обмену?', 0),
	(8201, 'ruRU', 'Ты уже $Gоткрутил:открутила; жрецам головы, $N? Мы должны остановить Хаккара, пока он не набрался сил!', 0),
	(8221, 'ruRU', '<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне рыбу-ангела Кифэра, то получите награду.$B$B<Щелк><Жжж>', 0),
	(8222, 'ruRU', 'За все время, что я работаю на ярмарке, я усвоил множество истин. Поделюсь полезным знанием: публика обожает блестящие безделушки! Это может быть что угодно – возьми, скажем, ножку от стула и покрась ее золотой краской. За эту штуковину будет драться детвора со всей округи!$B$BИтак, $N, мне нужна светящаяся кровь скорпида. Скорпидов можно найти в Силитусе, Выжженных землях или Пылающих степях.', 0),
	(8223, 'ruRU', 'А знаешь, $N, кровь скорпидов – отличное средство! Удивительно, как с помощью блесток можно любой мусор превратить в изысканную поделку. Клиентам полюбились безделушки, а любовь правит миром, так ведь?$B$BТвоя помощь неоценима, $N. Если вдруг ты раздобудешь еще светящейся крови скорпида, принеси ее мне, и я дам тебе ярмарочные купоны!', 0),
	(8224, 'ruRU', '<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне дезийскую ставриду, то получите награду.$B$B<Щелк><Жжж>', 0),
	(8225, 'ruRU', '<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне синего полосатика Браунелла, то получите награду..$B$B<Щелк><Жжж>', 0),
	(8227, 'ruRU', 'Привет, $Gдорогой:дорогая;. Ты здесь чтобы порыбачить?', 0),
	(8232, 'ruRU', 'Я вижу на твоем челе печать невзгод, $N. Тебе удалось убить дракона?', 0),
	(8235, 'ruRU', 'Ты $Gпринес:принесла; мне фрагменты? Я должен как можно скорее приступить к работе.', 0),
	(8236, 'ruRU', 'Верховный маг Ксилем уже прислал мне сумку. Ты $Gпринес:принесла; ключ?', 0),
	(8240, 'ruRU', 'Уничтожь драгоценности на Алтаре Занзы! Сделай это, и Занза благословит тебя дважды!', 0),
	(8241, 'ruRU', 'Не будем тратить драгоценное время на ерунду, $N. Пора пополнить запасы огненного плавня – они уже совсем на исходе.$B$BВот что мне от тебя нужно:$BЧешуя пламезавра$BЖелезные слитки$BУголь.$B$BМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.', 0),
	(8242, 'ruRU', 'Не будем тратить драгоценное время на ерунду, $R. Пора пополнить запасы огненного плавня – они уже совсем на исходе.$B$BВот что мне от тебя нужно:$BЧешуя пламезавра$BТяжелая кожа$BУголь.$B$BМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.', 0),
	(8243, 'ruRU', 'С вашим повышением статуса среди племени вы получите доступ к некоторым из наших наиболее полезных напитков. Вот... эти отвары сильны в моджо - благословлены Занзой и подходят для искателей приключений из всех слоев общества!$B$BЯ позволю вам выбрать одно из трех, которые я предлагаю; взамен мне нужен один жетон чести зандалара. Обратите внимание, что в любой момент времени в вашем духе могут действовать только эффекты одного из них.$B$BДайте мне знать, когда будете готовы к обмену!', 0),
	(8246, 'ruRU', 'Для друзей нашего племени, $N, у меня есть особый подарок прямо из нашего дома в Южных морях... Перстни Зандалара! Они усиливают любые наплечники и влияют на силу нападения или заклинаний.$B$BВ обмен на каждое кольцо мне нужно 15 почетных знаков Зандалара.', 0),
	(8249, 'ruRU', 'Моим разбойникам необходимо потренироваться во взломе замков, и мне нужны соответствующие замки. Зан делает такие, что они только зеленым новичкам годятся.$B$BВот что, принеси-ка мне 5 тяжелых ларцов, а я замолвлю за тебя словечко кому надо.$B$BТы можешь отпереть ларцы и порыться в них, но оставь там хотя бы несколько монеток... даже разбойнику-ученику нужна мотивация.', 0),
	(8251, 'ruRU', 'У тебя есть пыль?', 0),
	(8252, 'ruRU', 'Сирены из плевелашей - удивительно искусные маги. Надеюсь, не так искусен, как ты?', 0),
	(8253, 'ruRU', 'Ты $Gубил:убила; моего старого врага?', 0),
	(8255, 'ruRU', 'Ты $Gвернулся:вернулась;. Надеюсь, удача улыбнулась тебе?', 0),
	(8256, 'ruRU', 'Нам нужна лимфа как можно скорее! Тебе удалось добыть ее?', 0),
	(8257, 'ruRU', 'Ты $Gдобыл:добыла; кровь Морфаза?', 0),
	(8258, 'ruRU', 'Время критично, $N - удалось ли тебе остановить угрозу Рыцаря смерти Темного Терзателя?', 0),
	(8277, 'ruRU', 'Ты уже $Gсобрал:собрала; для меня образцы? Мы теряем Ноггла!', 0),
	(8278, 'ruRU', 'Это последний шанс спасти Ноггла! Спеши!', 0),
	(8279, 'ruRU', 'Кто идет? А, это ты! Ты уже все главы словаря $Gсобрал:собрала;?', 0),
	(8281, 'ruRU', 'Земснаряд-дробилки представляют собой серьезную угрозу, и с ней нужно бороться немедленно!', 0),
	(8282, 'ruRU', 'Ты еще не $Gнашел:нашла>;мою сумку? С другой стороны, грех жаловаться, от яда-то меня излечили.', 0),
	(8283, 'ruRU', 'Доказательством гибели твари послужат ее хелицеры. Нет хелицер, нет и награды.', 0),
	(8284, 'ruRU', 'Разграбленный лагерь находится на северо-западе. Возвращайся, когда соберешь все фрагменты.', 0),
	(8285, 'ruRU', 'Ты! Как ты меня $Gнашел:нашла;? Кто ты? За тобой не следят? Говори!', 0),
	(8286, 'ruRU', 'Анахронос вернулся?', 0),
	(8287, 'ruRU', 'Что ты мне $Gпринес:принесла;, $N?', 0),
	(8288, 'ruRU', 'Твоя цель – завоевать благосклонность рода Ноздорму.', 0),
	(8301, 'ruRU', 'Недоверие к смертным расам коренится в далеком прошлом; но пусть тебе об этом расскажут сами драконы, когда придет время.', 0),
	(8302, 'ruRU', 'Быть может, когда-нибудь ты возглавишь гарнизон крепости Кенария.', 0),
	(8304, 'ruRU', 'Не теряй времени, $N!', 0),
	(8306, 'ruRU', 'Наталия?', 0),
	(8308, 'ruRU', 'Мамочки.', 0),
	(8309, 'ruRU', 'Если в одном из ульев тебе попадется ненормальная ночная эльфийка, дай ей хорошего пинка от нашего имени.', 0),
	(8310, 'ruRU', 'Поиграй с мартышками, дитя. У меня нет времени на глупости.', 0),
	(8311, 'ruRU', 'Ты уже набрал для меня сладостей? Жаль, что я сам не могу пойти, но я рад, что ты мне помогаешь! Мне даже становится легче.', 0),
	(8312, 'ruRU', 'Что, много конфет тебе дали? Попечительница сказала, что мы можем выбрать только в одно место, и тут, по крайней мере, происходит много всего интересного.', 0),
	(8313, 'ruRU', 'Ты $Gосвоил:освоила; рецепт? Надеюсь, ты поделишься им с друзьями?', 0),
	(8314, 'ruRU', 'Ну и ну! Что это, $N?', 0),
	(8315, 'ruRU', 'Мы должны воспользоваться подходящей возможностью и нанести удар!', 0),
	(8317, 'ruRU', 'Как идут дела с клёцками?', 0),
	(8318, 'ruRU', 'Ты $Gпринес:принесла; мне тексты?', 0),
	(8319, 'ruRU', 'Можешь и дальше приносить мне тексты. Скоро мы выгоним Сумеречный Молот из Силитуса.', 0),
	(8320, 'ruRU', 'Войдите в пустыню и найдите сумеречных геолордов, $N. Вернись ко мне после того, как они будут убиты.', 0),
	(8321, 'ruRU', 'Тебе удалось победить Вайрала Подлого? Где его перстень-печатка?', 0),
	(8323, 'ruRU', 'Тебе удалось найти зашифрованные тексты? Мне было бы интересно заглянуть в свеженький номер "Истинно верующего".', 0),
	(8324, 'ruRU', 'Ты $нашел:нашла; новые зашифрованные тексты? Принеси мне целую кипу, на расшифровку уходит немало времени.', 0),
	(8325, 'ruRU', 'Наша работа по восстановлению нашего общества начинается здесь, $N. Как только мы будем в состоянии обезопасить наш дом, мы сможем больше осмотреть и Запределье.', 0),
	(8326, 'ruRU', 'Мне неприятно просить тебя уничтожать этих зверей. Хотя, в прошлые времена, мы жили в относительной гармонии с лесными существами, сейчас настали другие времена. Первым делом для всех Син\'дорай является выживание, постарайся запонить это.', 0),
	(8330, 'ruRU', 'Получилось ли у тебя найти мои вещи? Как только мы восстановим свое господство над Островом Солнечного Скитальца, они понадобятся мне в моей работе. Хотя сейчас я должен следить за Солнечным Колодцем... или над тем, что от него осталось.', 0),
	(8332, 'ruRU', 'У тебя есть осколок и герб, $N? Они мне понадобятся, чтобы сделать медальон сумеречного культиста.', 0),
	(8333, 'ruRU', 'Если тебе понадобится еще один станционный медальон служителя Сумрака, я с радостью помогу тебе. Но мне понадобится еще один осколок и несколько талисманов Бездны…', 0),
	(8334, 'ruRU', 'Лучше будет если ты узнаешь о выживании, и цене на выживание сейчас, чем позже. Как эльфу крови, тебе нужно привыкнуть к тому, что в чем-то придется делать нелегкий выбор.$B$BКогда Плеть разрывала наш дом надвое, здесь некому было помочь нам. И нам пришлось самим себя вытягивать из этой петли.', 0),
	(8335, 'ruRU', 'Выслушай внимательно моё предостережение - Фелендрен Изгой является лишь симптомом гораздо более серьезной проблемы. Его смерть решит наши насущные проблемы, но всех кровавых эльфов постигнет та же судьба, что и его, если мы позволим нашим пристрастиям одержать верх над нами.', 0),
	(8336, 'ruRU', 'Раньше большинство существ на острове были умиротворены и неагрессивны благодаря нашей магии.  Когда Плеть уничтожила Солнечный Колодец, мы утратили контроль над этими созданиями.  Магические осколки - это остатки того контроля, который у нас когда-то был, и поэтому они могут быть использованы для создания нового устройства, способного исправить ситуацию .$B$BЕще лучше, если с их помощью мы сможем узнать, что же на самом деле отравляет наш остров...', 0),
	(8338, 'ruRU', 'Судя по твоему виду, у тебя что-то срочное. Могу я чем-нибудь помочь?', 0),
	(8341, 'ruRU', 'У тебя есть осколки и печатки, $N? Они мне понадобятся, чтобы создать кольцо светлости.', 0),
	(8342, 'ruRU', '$N, если ты собираешься вновь выступить против Высшего Совета Бездны, тебе понадобится еще одно кольцо Власти служителя Сумрака. Принеси мне еще несколько осколков и перстней, и я сделаю такое кольцо.', 0),
	(8344, 'ruRU', 'Сущности призраков послужат мне хорошим источником экспериментов. Как и твоя жизнь в качестве $C, важно учиться тому, что мы находим в мире... прежде, чем подчинять это своей воле. Поскольку демоны являются самым богатым источником силы, будет большим благом, если такая зараза действительно присутствует на острове.$B$BЧто ж... это благо для нас, чернокнижников.', 0),
	(8345, 'ruRU', '$GПрочел:Прочла; ли ты надпись на святилище, $C?', 0),
	(8346, 'ruRU', 'А, $N. Ты $Gвыполнил:выполнила; свою задачу?', 0),
	(8348, 'ruRU', 'Как дела с герцогом Бездны? Трудно пришлось?', 0),
	(8350, 'ruRU', 'Добро пожаловать в мою таверну, |3-6($c). Я вижу, ты что-то мне $Gпринес:принесла;?', 0),
	(8352, 'ruRU', 'Ну как все прошло?', 0),
	(8361, 'ruRU', 'Работа закончена?', 0),
	(8362, 'ruRU', 'Ты уже $Gдоказал:доказала;, что умеешь сражаться, $N. Нельзя ослаблять натиск на Сумеречный Молот. Ступай, сразись с новыми храмовниками Бездны, и получишь в награду вещи, которые мы с Хуумом добыли в бою.', 0),
	(8363, 'ruRU', 'Ты $Gдоказал:доказала;, что можешь вызвать на бой герцогов Бездны, $N. А я всегда готов поощрять хорошие тенденции. Принеси мне еще перстней, и я награжу тебя.', 0),
	(8364, 'ruRU', 'Тебе удалось превзойти все мои ожидания, $N. Ты можешь справиться с противниками, которых мы с Хуумом не решились бы вызвать на бой.$B$BМне остается лишь поощрять тебя за борьбу с Сумеречным Молотом и его главарями.$B$BПринеси мне еще сумеречных скипетров, и я постараюсь достойно тебя наградить.', 0),
	(8365, 'ruRU', 'У тебя на руках все двадцать шляп? Не верю, покажи. И все должны быть в безупречном состоянии!', 0),
	(8366, 'ruRU', 'Уже $Gвернулся:вернулась;? Надеюсь, ты хорошенько $Gпроучил:проучила; эту южноморскую шваль!', 0),
	(8367, 'ruRU', 'Травы Арати мокры от крови и слышны лязга стали и воинственные крики воинов которые сражаются за Альтерак. Не трать моего времени, разве что ты $Gпринес:принесла; новости с фронта!', 0),
	(8369, 'ruRU', 'Что слышно из земель Северного Волка? Как идет битва в Альтеракской долине?', 0),
	(8371, 'ruRU', 'Как $Gтвои:ваши; путешествия, $Gпарень:девушка;?', 0),
	(8375, 'ruRU', 'Какие вести с фронта, $N?', 0),
	(8385, 'ruRU', 'А, $N. Я надеюсь, что ты еще не раз вступишь в бой на разных полях битвы. Многие юноши и девушки стараются подражать закаленным бойцам вроде тебя.', 0),
	(8386, 'ruRU', 'У тебя есть новости из Ущелья Песни Войны, $N?', 0),
	(8387, 'ruRU', 'Битва за Альтерак продолжается! Возвращайся в Альтеракскую долину и выгони наглых захватчиков с исконных земель клана Северного Волка, $N!', 0),
	(8410, 'ruRU', 'Что ты мне $Gпринес:принесла;, $C?', 0),
	(8411, 'ruRU', 'Где элементы, $Gдружище:подруга;?', 0),
	(8412, 'ruRU', 'Духи знают, что делают, а они пытаются убить меня! Надеюсь, ты несешь мне нужные части.', 0),
	(8413, 'ruRU', 'Где перья, дружище?', 0),
	(8414, 'ruRU', 'Какое зло ты принес мне?', 0),
	(8416, 'ruRU', 'Удалось ли Тельданису очистить камни Плети?', 0),
	(8417, 'ruRU', 'Столи откашлялся от моей выпивки?', 0),
	(8418, 'ruRU', 'Тебе удалось убить проклятых троллей?', 0),
	(8421, 'ruRU', 'Ну, все принес?', 0),
	(8422, 'ruRU', 'Где перья? Эта кукла нуждается в них!', 0),
	(8423, 'ruRU', 'Горящие шипы кабана оставляют ужасные шрамы. Не бойся боли и обезображивания, $C, они ничто по сравнению с тюрьмой, к которой я привязан.', 0),
	(8424, 'ruRU', 'Приверженцев тени нелегко победить, не так ли? Но ты $C, и ты победишь или погибнешь, пытаясь.', 0),
	(8425, 'ruRU', 'Ты уже назад – так быстро? Для тебя и меня время течет по-разному, быть может, для тебя это и вправду было долгое путешествие...', 0),
	(8460, 'ruRU', 'Запомни, $N. Если хочешь заслужить наше доверие, прояви себя.', 0),
	(8461, 'ruRU', 'Я уверен, тебе удастся завоевать доверие Древобрюхов. Древобрюхи никогда не забывают своих союзников, особенно в такие темные времена.', 0),
	(8463, 'ruRU', 'Ну что, удалось тебе отыскать похищенное?', 0),
	(8464, 'ruRU', 'Мы крайне признательны за то, что вы делаете для племени Древобрюхов, $N. Благодаря своим неустанным усилиям, вы, бесспорно, завоюете доверие и уважение моего племени.', 0),
	(8466, 'ruRU', 'Хотя я уже тебе доверяю, заслужить доверие моих подозрительных соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.$B$BУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.', 0),
	(8467, 'ruRU', 'Хотя я уже тебе доверяю, заслужить доверие моих соплеменников тебе еще только предстоит. Тут я смогу тебе помочь.$B$BУ некоторых фурболгов Мертвого Леса есть характерные головные уборы, которые могут послужить доказательством уменьшения их числа. Приноси мне перья из всех головных уборов, какие только сможешь добыть, и с каждыми очередными пятью штуками доверие к тебе в племени Древобрюхов будет возрастать.', 0),
	(8468, 'ruRU', 'Ты хочешь мне что-то показать?', 0),
	(8469, 'ruRU', 'Ты $Gзаслужил:заслужила; мое доверие $N, теперь осталось проделать то же самое с моим крайне недоверчивым племенем. Для этого придется потрудиться.$B$BПлемя Зимней Спячки, как известно, носит особые бусы, чтобы защищаться от злых духов. Бусы не оправдали своё предназначение, поскольку всё племя подверглось порче. Принеси мне бусы, которые носят падшие фурболги. Твой авторитет в племени будет расти с каждыми принесёнными бусами.', 0),
	(8470, 'ruRU', 'Да, $C, чем могу тебе помочь? Ты ходишь среди нас беспечно, хотя это не слишком-то правильно. Я чую что-то... что-то тревожное...', 0),
	(8471, 'ruRU', '#C, ты пришел к нам с миром, но я вижу, что у тебя очень важная цель. Важная не только для фурболгов, но и для твоих соплеменников, $R. О чем ты хочешь нам поведать?', 0),
	(8472, 'ruRU', 'Ну что, $n, удалось тебе собрать волшебные сердечники?', 0),
	(8473, 'ruRU', 'Ну что, $N, удалось ли тебе зарядить рунный камень?', 0),
	(8474, 'ruRU', 'Ты хочешь мне что-то показать?', 0),
	(8475, 'ruRU', 'Ты $Gвернулся:вернулась;, $N. Разве тебе не нужно сражаться с нежитью у Тропы Мертвых?', 0),
	(8476, 'ruRU', 'Ты найдешь Тор\'Вату и Зеб\'Вату к юго-востоку отсюда. Возвращайся, когда убьешь троллей.', 0),
	(8477, 'ruRU', 'Ну что, $N, ты принесла мне молот Отембе?', 0),
	(8479, 'ruRU', 'Принесла ли ты голову Зул\'Мароша?', 0),
	(8480, 'ruRU', 'Ты еще не $Gсобрал:собрала; утраченное оружие?', 0),
	(8481, 'ruRU', 'Ты $Gвернулся:вернулась; к нам, $N... Значит ли это, что демон сражен?', 0),
	(8482, 'ruRU', 'Ты мне что-то принес? Дай-ка взглянуть...', 0),
	(8483, 'ruRU', 'Ну что, удалось тебе разобраться с этим прохвостом?', 0),
	(8484, 'ruRU', '$C, добро пожаловать в мои владения. Стальгорн всегда следует считать домом для такого героя, как вы. Какое у тебя дело со мной?', 0),
	(8485, 'ruRU', 'Вождь тебя приветствует, $C. Твои дела укрепляют Орду в эти смутные времена. Какое у тебя дело ко мной?', 0),
	(8486, 'ruRU', 'Ты уже $Gизбавился:избавилась; от волшебных призраков?', 0),
	(8487, 'ruRU', 'Ты собрал образцы, которые я просила, $N?', 0),
	(8490, 'ruRU', 'Ну что, $N, удалось ли тебе зарядить рунный камень?', 0),
	(8491, 'ruRU', 'О, ты уже здесь! А где шкуры?', 0),
	(8492, 'ruRU', 'Ну что, солдат, удалось собрать 20 медных слитков?', 0),
	(8493, 'ruRU', 'Ты уже $gвернулся:вернулась;, |3-6($c)? Превосходно! Слитки, которые тебе удалось достать, сослужат нам добрую службу. Я могу сказать со всей ответственностью, что медь пойдет на изготовление паровых танков, а так же вертолетов и прочей военной техники.$B$BИ пусть эти штабеля меди не смущают твой взгляд, к сожалению, их пока недостаточно, чтобы подготовится к войне в Ан\'Кираже как следует. Но ведь мы еще можем рассчитывать на твою помощь?', 0),
	(8494, 'ruRU', 'Принесите 20 железных слитков капралу Карнсу в Палаты Войны Стальгорна.', 0),
	(8495, 'ruRU', 'Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, $C, а то я буквально таю изнутри. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.', 0),
	(8498, 'ruRU', 'Что ты мне $Gпринес:принесла;, $N?', 0),
	(8500, 'ruRU', 'Добро пожаловать снова, $N. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.', 0),
	(8503, 'ruRU', 'Это грязный поклеп! Я не брал отсюда ни одной травинки! Хотя соблазн очень велик... ведь это ж практически настоящая панацея от утилитарной бесполезности.  кашляет  Да, кстати, как там насчет удавника, который ты $gдолжен был:должна была; принести мне?', 0),
	(8504, 'ruRU', 'Эй, ты там... Ой... Что это было? Ах, да, $N! $GЗашел:Зашла; поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?', 0),
	(8505, 'ruRU', 'Тебе удалось собрать цветы лилового лотоса?', 0),
	(8507, 'ruRU', 'Дружина капитана Черной Наковальни расквартирована рядом с Ульем Зора. Если ты не найдешь его, поговори с Джанелой Твердомолот.', 0),
	(8508, 'ruRU', 'Я так понимаю, ты хочешь подписать эти бумаги?', 0),
	(8509, 'ruRU', 'Что? Докладывай быстро и четко, $C! Тебе удалось собрать необходимое количество слез Артаса?', 0),
	(8511, 'ruRU', 'Ну, $c, где обещанная кожа?', 0),
	(8512, 'ruRU', 'Рада снова тебя видеть, $N. Похоже, что мы еще не собрали достаточно кожи для всяких воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.', 0),
	(8513, 'ruRU', 'Так точно, $gсэр:мэм;, я помню вас. Вы принесли среднюю кожу?', 0),
	(8514, 'ruRU', 'Так точно, $gсэр:мэм;, мы собрали много средней кожи, но все равно недостаточно. Заверяю вас, мы найдем этой коже самое наилучшее применение, ни один клочок не пропадет зря. Я знаю, что требую слишком многого, но если у вас еще сохранилось желание, помогите мне набрать установленную норму.', 0),
	(8515, 'ruRU', 'Это же обещанной кожей у тебя сумки набиты, $C? Не могу дождаться, когда же ты отдашь ее мне! Тогда все-все останутся нами довольны, правда?', 0),
	(8516, 'ruRU', 'Да-да, стопки еще не очень высокие. $N, мы не выполняем норму – не хватает целых 80000 плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.$B$BТы ведь принесешь мне еще плотной кожи?', 0),
	(8517, 'ruRU', 'Двадцать льняных бинтов у тебя, |3-6($c)?', 0),
	(8518, 'ruRU', 'Меня всегда изумляет самоотверженность, ведь многие обычно более склонны к эгоизму. $C, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?', 0),
	(8520, 'ruRU', 'Приветик, $C, ну что, удалось раздобыть двадцать шелковых бинтов?', 0),
	(8521, 'ruRU', 'Очень мило с твоей стороны снова предложить мне помощь, $C. Мы уже собрали очень много шелковых бинтов, но это, к сожалению, далеко не конец. $N, можешь принести еще штук двадцать? Я была бы благодарна тебе от имени всего Альянса.', 0),
	(8522, 'ruRU', 'Проходит день за днем, а мы все продолжаем и продолжаем готовиться. $C, тебе удалось достать бинты из рунической ткани?', 0),
	(8523, 'ruRU', 'Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, $C. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.$B$B$N, можешь принести мне еще бинтов из рунной ткани?', 0),
	(8524, 'ruRU', 'Готов поспорить, что ты вернешься с нужным количеством радужного тунца, |3-6($c)!', 0),
	(8525, 'ruRU', 'Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты $gпришел:пришла;, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец?  облизывается $B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!', 0),
	(8526, 'ruRU', 'Ну что, где там наши жареные ящеры?', 0),
	(8528, 'ruRU', 'Я уверена, что ты $Gвернулся:вернулась; так быстро, потому что $Gпринес:принесла; необходимое количество желтохвоста.', 0),
	(8529, 'ruRU', 'Если у тебя еще не пропало желание помогать нам, то нам опять нужен желтохвост, $N. Я думаю, в прошлый раз ты $Gприобрел:приобрела достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?', 0),
	(8532, 'ruRU', 'Я надеюсь, 20 медных слитков у тебя с собой, $C?', 0),
	(8533, 'ruRU', 'Уже $Gвернулся:вернулась;? Из тебя быстро получился бы отличный рудокоп, $C. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что кое-что ты можешь, но вот вопрос – хочешь ли.', 0),
	(8534, 'ruRU', 'Ты найдешь разведчика Азенель внутри Улья Зора. Торопись, $N! Время имеет существенное значение.', 0),
	(8543, 'ruRU', 'Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я немного нервничаю, думаю, ты меня понимаешь, как солдат солдата, $C. Это будет победоносная война, когда начнется. Воины Орды преодолеют пески и с оружием в руках кинутся на киражских тараканов. В этот день все мы обретем великую славу!$B$BХар! Но сначала нужно собрать достаточное количество этих несчастных оловянных слитков. Забавно, что мы не можем начать грандиозную войну без этих маленьких штуковин, правда?', 0),
	(8545, 'ruRU', 'Хорошо бы поскорее собрать все слитки и закончить подготовку к войне в Ан\'Кираже. Ты уже $Gдостал:достала; все, что мне нужно, $Gдружище:подруга;?', 0),
	(8546, 'ruRU', 'Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.$B$BТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.', 0),
	(8547, 'ruRU', 'Привет! Приятно познакомиться!$B$BЯ вижу, что у вас есть специальный ваучер. Отдай его мне, и я предложу тебе что-нибудь взамен.', 0),
	(8549, 'ruRU', 'Уже $Gсобрал:собрала; мироцвет и $Gвернулся:вернулась;, $C?', 0),
	(8551, 'ruRU', 'Эгей, $N! $GНашел:Нашела; Горлаша? Это был мой любимый сундук, к тому же в тайном отделении там лежат все мои сокровища!', 0),
	(8552, 'ruRU', 'Привет.У тебя ко мне дело?', 0),
	(8572, 'ruRU', 'В наших интересах держать наших самых верных союзников в хорошей форме, $N.', 0),
	(8575, 'ruRU', 'Оооо! Пульсирующая магией штуковина! Для меня?', 0),
	(8578, 'ruRU', 'Огненные Недра? Надеюсь что мои очки все еще целы!', 0),
	(8580, 'ruRU', 'Ты ведь не хочешь рассердить Пелекейки, ага, $Gдружище:подруга;? Ты хочешь, чтобы Пелекейки был счастлив. Поэтому сейчас пойдешь и принесешь ему целую охапку огнецвета, причем очень-очень быстро!', 0),
	(8582, 'ruRU', 'Ты так скоро $Gвозвратился:возвратилась; $C? А где лиловый лотос? Поторопись, а то все мои труды пойдут насмарку.', 0),
	(8583, 'ruRU', 'Вынуждена констатировать тот факт, что мы все еще нуждаемся в цветах лилового лотоса, |3-6($C). Мои исследования направлены на изучение новых способов применения этого реагента, и очень много уходит на то, чтобы выработать методологию.$B$BМне нужно, чтобы ты собрал как минимум еще двадцать образцов. Возвращайся, когда выполнишь это задание.', 0),
	(8585, 'ruRU', 'Мммм... Химеры...', 0),
	(8586, 'ruRU', 'Поторопись! Мы же не хотим, чтобы это мясо пропало.', 0),
	(8587, 'ruRU', 'Что это за чудный запах?', 0),
	(8588, 'ruRU', 'Я тут не в игрушки играю, так что времени трепаться с тобой у меня нет, $C. Слишком много толстой кожи, с которой надо возиться. Возвращайся обратно, когда соберешь хотя бы десять кусков.', 0),
	(8589, 'ruRU', 'Так точно, |3-6($C), мне все еще нужна толстая кожа. Запросы от генералов и интендантских служб кажутся бесконечными. Но это еще ничто по сравнению с тем, что требуют от нас хозяева дирижаблей!$B$BМне придется, пожалуй, двойную норму сдать. $N, пожалуйста, принеси побольше толстой кожи, и как можно скорее!', 0),
	(8590, 'ruRU', 'Что, $C, уже удалось достать плотную кожу?', 0),
	(8591, 'ruRU', 'Как видишь, |3-6($C), я все еще продолжаю собирать плотную кожу. И я снова хочу просить тебя о помощи. Обещаю, Орда не забудет приложенных тобой усилий.$B$BПостарайся достать кожу как можно скорее, для нас очень важно поскорее закончить приготовления к войне!', 0),
	(8595, 'ruRU', 'Удивительно, что смертному существу вроде тебя, $N, удалось одолеть киражского владыку. Но их армия по-прежнему сильна и многочисленна. Если хочешь доказать, что ты действительно $Gпоборник:поборница; нашего дела, продолжай истреблять киражи.', 0),
	(8598, 'ruRU', 'В чем дело?', 0),
	(8599, 'ruRU', 'От вас рыбой несет!', 0),
	(8600, 'ruRU', 'Не может же быть, чтобы срезка десяти прочных кож отняла столько времени! Может, тебе стоит наточить охотничий нож? Или я ошибся, и кожи у тебя с собой?', 0),
	(8607, 'ruRU', 'Пожалуйста, не подведи, это поставит меня в крайне неудобное положение. Возвращайся с бинтами из магической ткани как только сможешь.', 0),
	(8620, 'ruRU', 'Я вот как положил одну ногу на другую... эй, где все 8 частей книги?', 0),
	(8695, 'ruRU', 'Ты $Gпринес:принесла; мне все, что необходимо для изготовления накидки, $N?', 0),
	(8708, 'ruRU', 'Ты $Gпринес:принесла; мне необходимые материалы, $N?', 0),
	(8728, 'ruRU', 'Арканитовые буйки сами собой не делаются, $N. НЕТ, денег взаймы не дам.', 0),
	(8729, 'ruRU', 'Время на исходе!', 0),
	(8730, 'ruRU', 'Другой наш герой проиграл порождению Смертокрыла. Мы будем навеки прокляты этим страданием...', 0),
	(8731, 'ruRU', 'Капитана Расщепленного Черепа можно найти за пределами Улья Регал.', 0),
	(8732, 'ruRU', 'Я так понимаю, ты хочешь подписать эти бумаги?', 0),
	(8735, 'ruRU', '<Ремулос находится в глубокой задумчивости.>', 0),
	(8738, 'ruRU', 'Ты найдешь разведчика Лэндиона внутри Улья\'регала. Торопись, $N! Время имеет существенное значение.', 0),
	(8739, 'ruRU', 'Ты найдешь разведчика Джалию внутри Улья Аши. Торопись, $N! Время имеет существенное значение.', 0),
	(8743, 'ruRU', 'Гонг Скарабея зловеще нависает над тобой. Крепись духом, $N – как только гонг Скарабея загудит, врата Ан\'Киража откроются.$B$BДряхлая пасть этого зверя может извергнуть только хаос и разрушение. Защити свой народ!', 0),
	(8746, 'ruRU', '$N! Ну что, помогли тебе эти записки? Метцен нашелся? Страшно подумать, что могли сделать с ним эти бессердечные головорезы... Но мы просто не могли выплатить такой запредельный выкуп!', 0),
	(8747, 'ruRU', 'Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.', 0),
	(8752, 'ruRU', 'Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.', 0),
	(8757, 'ruRU', 'Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.', 0),
	(8762, 'ruRU', '$N! Тех записок в сумке, что я тебе дал, оказалось достаточно для обнаружения Метцена? Страшно подумать, что могли сделать с ним эти бессердечные головорезы... Но мы просто не могли выплатить такой запредельный выкуп!', 0),
	(8763, 'ruRU', 'На первый взгляд, сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.\n\nСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых монет, и машинка заработает.', 0),
	(8784, 'ruRU', 'Ты $Gвесь:вся; светишься! Я знаю, что это значит...', 0),
	(8785, 'ruRU', 'Ты $Gпринес:принесла; мне все материалы?', 0),
	(8789, 'ruRU', 'Найди то, что мне нужно, и ты станешь чем-то большим, чем сумма составляющих твою личность элементов, $Gзащитник:защитница;.', 0),
	(8790, 'ruRU', 'Ты сокрушишь их и освободишь нас от этих оков.', 0),
	(8791, 'ruRU', 'О, $N, ты уже $Gвернулся:вернулась;! $GЦелым:Целой; и $Gневредимым:невредимой;, могу добавить. Ну, какие новости из Ан\'Киража?', 0),
	(8801, 'ruRU', '<Калестраз преклоняет перед вами колени>$B$B$GГосподин:Госпожа; $N, вы разбили наши оковы.', 0),
	(8802, 'ruRU', '$GГосподин:Госпожа;, $N! Все закончилось...', 0),
	(8811, 'ruRU', 'Один рекомендательный жетон позволяет немного улучшить отношение жителей Штормграда к сдавшему его искателю приключений.$b$bИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.$b$bНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.', 0),
