	(11990, 'ruRU', 'Всё $Gпринёс, друг:принесла, подруга;?', 0),
	(11991, 'ruRU', 'Многие храбрые воины стараются брать с тебя пример, бросаясь в бой против Орды. Что нового тебе встретилось в странствиях?', 0),
	(11999, 'ruRU', 'Ты снова здесь. Что тебе удалось узнать?', 0),
