	(12003, 'ruRU', 'Не думаю, что тебе удалось найти туннели, не так ли?', 0),
	(12004, 'ruRU', 'Тебе удалось воспрепятствовать объединению усилий синих драконов и Эфириума?', 0),
	(12005, 'ruRU', 'Удалось ли тебе предотвратить заключение договора между синими драконами и Эфириумом?', 0),
	(12006, 'ruRU', 'Каким-то образом я чувствую, что ты еще не убил достаточное количество этих осквернителей!', 0),
	(12007, 'ruRU', 'Ты $Gдобыл:добыла; Око пророка, $Gдруг:подруга;?', 0),
	(12008, 'ruRU', 'Они усилят Орду, командор.', 0),
	(12009, 'ruRU', 'Сколько крабов тебе удалось раздобыть?', 0),
	(12012, 'ruRU', 'Что тебя беспокоит, дитя мое?', 0),
	(12013, 'ruRU', 'Ты меня за дурака держишь? Арканимус по-прежнему пожирает души моих братьев и сестер, |3-6($C)!', 0),
	(12016, 'ruRU', 'Ты $Gпринес:принесла; мне сочную плоть Кили\'уа?', 0),
	(12017, 'ruRU', 'Ту\'у\'гвар мертв?', 0),
	(12020, 'ruRU', 'Дворфы Черного Железа потерпели поражение! Убегая в «Угрюмого обжору», они потеряли почти весь свой транспорт. Но главное – наш лагерь цел и невредим. $b$bБеги к Бокси и расскажи ему о нашей славной победе над кланом Черного Железа.', 0),
	(12022, 'ruRU', 'Хлебай да бросай, С.С.М. все стерпит – чего бы я тогда его сооружал?', 0),
	(12026, 'ruRU', 'Что ты мне принесла?', 0),
	(12028, 'ruRU', 'Что думаешь?', 0),
	(12029, 'ruRU', 'Ты принесла мне пепел, $N?', 0),
	(12031, 'ruRU', '<Старейшина Мана\'лоа смотрит сквозь вас, чувствуя, что вы еще не выполнили его задачу.>', 0),
	(12032, 'ruRU', '$N, ты $Gвернулся:вернулась;!', 0),
	(12033, 'ruRU', 'Мы раздавим Плеть!', 0),
	(12034, 'ruRU', 'Что это у тебя?', 0),
	(12035, 'ruRU', 'Ты $Gзакончил:закончила;, $N?', 0),
