	(12038, 'ruRU', 'Рад видеть тебя, $N.\n\nЗначит, ты нашел таблички?', 0),
	(12039, 'ruRU', 'Чего стоит жизнь, в которой нет места риску?', 0),
	(12040, 'ruRU', 'Империя Азжол снова восстанет!', 0),
	(12041, 'ruRU', 'Что это у тебя?', 0),
	(12042, 'ruRU', 'Ярко ли горит Плеть, $N?', 0),
	(12043, 'ruRU', 'Ты собрал руду? Мой посыльный скоро вернется – мы должны отправить посылку, пока битва еще продолжается!', 0),
	(12044, 'ruRU', 'Ты $gсобрал:собрала; руду? Мой посыльный скоро вернется - мы должны отправить посылку, пока битва еще продолжается!', 0),
	(12045, 'ruRU', 'Ну что, где осколки? А то основную холодильную установку я уже почти достроила!', 0),
	(12046, 'ruRU', 'Ну, как охота? Где шкуры?', 0),
