	(12936, 'ruRU', 'Награда – по окончании боя, приятель.', 0),
	(12937, 'ruRU', 'Тебе удалось поднять на ноги раненых защитников?', 0),
	(12939, 'ruRU', 'Может, вернешься туда и победишь ещё пару-тройку врайкулов?', 0),
	(12942, 'ruRU', 'Ты нашла лагерь Бронзоборода?', 0),
	(12943, 'ruRU', 'Моя разведка доносит, что Уфранг еще жив.$B$BТы что, не умеешь читать, $R', 0),
	(12948, 'ruRU', 'Награда – по окончании боя, приятель.', 0),
	(12949, 'ruRU', 'Ключ у тебя?', 0),
	(12952, 'ruRU', 'Я научу тебя навыкам огранки драгоценных камней.', 0),
	(12953, 'ruRU', 'Ты нашла лагерь Бронзоборода?', 0),
