	(12960, 'ruRU', 'Ты $g$gпринес:принесла;:$gпринес:принесла;ла; мне брошь Беспощадного солнца для отправки в Нижнюю Шахту?', 0),
	(12961, 'ruRU', 'Ты $gпринес:принесла; мне изысканную костяную статуэтку для отправки в Нижнюю шахту?', 0),
