	(12963, 'ruRU', 'Ты $gпринес:принесла; мне реликвию Восходящего Солнца для отправки в Нижнюю шахту?', 0),
	(12964, 'ruRU', 'Ты что-нибудь $Gвыяснил:выяснила; насчет этой руды?', 0),
	(12965, 'ruRU', 'Это правда? Вальдуран обладает мощными реликвиями титанов? Ты $Gуничтожил:уничтожила; их?', 0),
	(12967, 'ruRU', 'Удалось ли тебе привести Снорри к очередной победе, $C?', 0),
	(12968, 'ruRU', 'Ты нашла лагерь Бронзоборода?', 0),
	(12969, 'ruRU', 'Ты наказала этих предательниц?', 0),
	(12970, 'ruRU', 'Тише-тише, а то мы можем вызвать подозрения...', 0),
	(12972, 'ruRU', 'Да, $N?', 0),
	(12973, 'ruRU', 'Тысяч извинений, $Gмой:моя; $Gмальчик:девочка;! Я был полностью захвачен моментом и совершенно не заметил тебя...', 0),
	(12975, 'ruRU', 'Ты $Gнашел:нашла; фрагменты рога Ходира?', 0),
	(12976, 'ruRU', 'Ты $Gпринес:принесла; мне фрагменты рога Ходира, $R?', 0),
	(12977, 'ruRU', 'Сильные порывы ветра кружатся вокруг рога, вызывая его звук эхом по всем окружающим горам.', 0),
	(12978, 'ruRU', 'Ты $Gвзял:взяла; молот в Нидавелире?', 0),
	(12979, 'ruRU', 'Что это там у тебя?', 0),
	(12980, 'ruRU', 'Что ты $Gузнал:узнала;?', 0),
	(12981, 'ruRU', 'Яркое синее сияние окружает наковальню.', 0),
	(12982, 'ruRU', 'Еще не все мои рыцари смерти свободны! Их было больше.', 0),
	(12983, 'ruRU', 'Ты $Gнашел:нашла; матриарха?', 0),
	(12984, 'ruRU', 'С Вальдураном нужно разобраться до того, как убежище падет.', 0),
	(12985, 'ruRU', 'Ты $Gпринес:принесла; то, о чем я тебя просил, $R?', 0),
	(12986, 'ruRU', 'Ты $Gвернулся:вернулась; с знанием, что я ищу, $R?', 0),
	(12987, 'ruRU', '$GУстановил:Установила; ли ты Шлем Ходира, $R.', 0),
	(12988, 'ruRU', 'Удалось помешать им?', 0),
	(12989, 'ruRU', 'Как все прошло с йети?', 0),
	(12991, 'ruRU', 'Ты $Gуничтожил:уничтожила; силу железного колосса?', 0),
	(12992, 'ruRU', 'Врайкулов не $Gубил:убила;!', 0),
	(12993, 'ruRU', 'Ты $Gпринес:принесла; документы?', 0),
	(12994, 'ruRU', 'Призрачный ледяной ворг с любопытством смотрит на вас.', 0),
	(12995, 'ruRU', '$N, не думаю, что ты $Gзакончил:закончила;.', 0),
	(12996, 'ruRU', 'Ты нашла лагерь Бронзоборода?', 0),
	(12997, 'ruRU', 'Ты уничтожила зараженные яйца?', 0),
	(12998, 'ruRU', 'Скажи мне, что сердце не попало в руки врага.', 0),
	(13000, 'ruRU', 'Ты $Gпринес:принесла; шкуры?', 0),
	(13001, 'ruRU', 'Ты $Gсобрал:собрала; материалы для копья, |3-6($R)?', 0),
	(13002, 'ruRU', 'Это то, что я искал. Давай я тебя научу искусству огранки.', 0),
	(13004, 'ruRU', 'Твое пожертвование очень ценно. Давай я тебя научу искусству огранки.', 0),
	(13005, 'ruRU', 'Привет, $N. Какие новости $Gпринес:принесла;?', 0),
	(13006, 'ruRU', 'Иней сгущается на шлеме буквально у вас на глазах, и по краям уже начинают формироваться сосульки...', 0),
	(13007, 'ruRU', 'Ты $Gпобедил:победила; железного колосса?', 0),
	(13008, 'ruRU', 'Ты $Gосвободил:освободила; опутанных рыцарей?', 0),
	(13009, 'ruRU', 'Ну, что, |3-6($C)? Как успехи?', 0),
	(13010, 'ruRU', 'Ты $Gубил:убила; Йормуттара?', 0),
	(13011, 'ruRU', 'Рад снова тебя видеть, $N.', 0),
	(13034, 'ruRU', 'Ты $Gузнал:узнала;, что написано в исторических документах лагеря Тунка\'ло?', 0),
	(13035, 'ruRU', 'Рад снова тебя видеть, $N.', 0),
	(13038, 'ruRU', 'Что ты $Gпринес:принесла; из гробницы?', 0),
	(13039, 'ruRU', 'Не сдавайтесь, $N!', 0),
	(13040, 'ruRU', 'Ты $Gдобыл:добыла; ядовитые железы, $R?', 0),
	(13041, 'ruRU', 'Ты $Gпринес:принесла; кальцедоний?', 0),
	(13042, 'ruRU', 'Ты не $Gзакончил:закончила; то, о чем я тебя просил.$B$BУходи и не возвращайся, пока не сделаешь это, или я буду очень сердит.', 0),
	(13043, 'ruRU', 'Ты $Gвернул:вернула; фолиант доктора, но не $Gприкончил:прикончила;?$B$BВернись туда и убей его, пока не стало слишком поздно!', 0),
	(13045, 'ruRU', 'С каждой минутой их шансы выжить тают...', 0),
	(13047, 'ruRU', 'Ах, $N! Рад видеть тебя, малышка.', 0),
	(13048, 'ruRU', 'Ты $Gнастроил:настроила; Молот Знаний на время Штормового Копыта?', 0),
	(13049, 'ruRU', 'Нашлись ли доспехи и оружие Штормового Копыта?', 0),
	(13050, 'ruRU', 'Ты $Gдобыл:добыла; яйца, $N?', 0),
	(13055, 'ruRU', 'Уже вернулся, $Gбраток:сестрёнка;?', 0),
	(13058, 'ruRU', 'Ну что, получилось? Истинная линия времени восстановлена?', 0),
	(13059, 'ruRU', 'Я чувствую, что ты еще не $Gсразил:сразила; Тана Иллскара. Что остановило твою руку?', 0),
	(13061, 'ruRU', 'Ты уничтожила зараженные яйца?', 0),
	(13062, 'ruRU', 'Ты уничтожила зараженные яйца?', 0),
	(13063, 'ruRU', 'Да, $N?', 0),
	(13064, 'ruRU', 'Слушай меня, |3-6($R).', 0),
	(13069, 'ruRU', 'Тск, тск... ты сегодня еще не $Gсбил:сбила; свою часть протодраконов!', 0),
	(13071, 'ruRU', 'Что?Не вижу большого огня!!!$B$B$N, вернитись и сделай больше огня!', 0),
	(13074, 'ruRU', 'Приятно видеть тебя $Gживым:живой;. Удалось достать желуди?', 0),
	(13075, 'ruRU', 'Рад встрече, $C. Я знал, что ты все равно вернешься, несмотря на мое предупреждение, но ты хотя бы $Gпослушал:послушала; меня и не $Gстал:стала; подвергать риску кого-то еще. Что не может не радовать.$B$BПочему ты $Gвернулся:вернулась; ко мне?', 0),
	(13078, 'ruRU', 'О, милая Далия, как мне тебя не хватает!', 0),
	(13079, 'ruRU', 'Ты снова $Gвернулся:вернулась; ко мне, $C. Ради чего ты рискуешь собой?', 0),
	(13083, 'ruRU', 'Он ушел, да? Его больше нет? Я почувствовал, как из этого мира исчез кусочек света, и в мире стало темнее...', 0),
	(13084, 'ruRU', 'У тебя еще много работы.', 0),
	(13086, 'ruRU', 'Крики умирающих будут преследовать меня всегда! Помоги им!', 0),
	(13087, 'ruRU', 'ГДЕ МОЕ МЯСО?!', 0),
	(13088, 'ruRU', 'Эти парни хотят видеть мясо у себя в похлебке!', 0),
	(13089, 'ruRU', 'Похлебка ждет тебя...', 0),
	(13090, 'ruRU', 'Будет мясо – будет и похлебка.', 0),
	(13091, 'ruRU', 'Гадание на костях показывает, что мое задание до сих пор не выполнено.', 0),
	(13092, 'ruRU', 'Меня поражает, что эти создания когда-то имели еще и какую-то власть над миром. С такой примитивной магией!', 0),
	(13093, 'ruRU', 'Принеси мне побольше костей врайкулов, и мы сделаем так, что судьба будет к тебе благосклонна.', 0),
	(13094, 'ruRU', 'Пожалуйста, $N, скажи мне, что ты $Gнашел:нашла; книгу Беринарда...', 0),
	(13095, 'ruRU', 'Пожалуйста, $N, скажи мне, что ты нашел книгу Беринарда...', 0),
	(13096, 'ruRU', 'Смерть Акали была отомщена, $R?', 0),
	(13097, 'ruRU', 'Мне бы хотелось тебе помочь, но я могу дать тебе только теплое напутствие и сердечную поддержку.\n\nНе торопись, подготовься, как следует, и выступай, когда будешь готов. Только прошу, не затягивай слишком долго, потому что иначе пророк сам нагрянет сюда.', 0),
	(13098, 'ruRU', 'Ты нашел таблички с летописью Драккари?', 0),
	(13100, 'ruRU', 'Ты $gпринес:принесла; мне поесть?\n\nА то сижу тут, как привязанный. Ни на секунду не выйти из лавки! А кушать-то хочется!', 0),
	(13101, 'ruRU', 'Где же еда? Я жду гостей! Они должны прибыть с минуты на минуту!', 0),
	(13102, 'ruRU', 'Мои постояльцы голодны! Мне срочно нужно рагу.', 0),
	(13103, 'ruRU', 'Ты не $gвидел:видела; слугу с моим вином и сыром? Жрать хочу – умираю!', 0),
	(13107, 'ruRU', 'Я почти готов. Осталось только дождаться, когда мне принесут еду и когда подойдут мои подру... э... мои коллеги - маги.', 0),
	(13108, 'ruRU', 'Локен принял правосудие?', 0),
	(13109, 'ruRU', 'Волхан потушен, маленький $R?', 0),
	(13110, 'ruRU', 'Это мрачная задача, $N, но она должна быть сделана.', 0),
	(13111, 'ruRU', 'Ты принес то, о чем я тебя просила?', 0),
	(13112, 'ruRU', 'Ты $Gпринес:принесла; мне поесть?$B$BА то сижу тут, как привязанный. Ни на секунду не выйти из лавки! А кушать-то хочется!', 0),
	(13113, 'ruRU', 'Где же еда? Я жду гостей! Они должны прибыть с минуты на минуту!', 0),
	(13114, 'ruRU', 'Только чтобы на этот раз в рагу не было никаких гномов!', 0),
	(13115, 'ruRU', 'Ты не $Gвидел:видела; слугу с моим вином и сыром? Я голоден!', 0),
	(13116, 'ruRU', 'Только смотри, чтобы сосиски были на 100% из люторожьего мяса, без всяких там добавочных субпродуктов типа гномов!', 0),
	(13117, 'ruRU', 'Ты $Gузнал:узнала; откуда берутся эти скелеты?', 0),
	(13118, 'ruRU', 'Не трать время, $N.', 0),
	(13119, 'ruRU', 'Тебе удалось уничтожить алтари призыва?', 0),
	(13120, 'ruRU', 'Ты $Gразместил:разместила; сферы?', 0),
	(13121, 'ruRU', 'Тебе не удалось ничего узнать?! Так-то ты благодаришь меня за помощь тебе и рыцарям Черного Клинка?$B$BИди и без нужных мне сведений не возвращайся!', 0),
	(13122, 'ruRU', 'Камни Плети помогут нам отслеживать перемещения сил противника.', 0),
	(13125, 'ruRU', 'Покончи с ними, $N!', 0),
	(13126, 'ruRU', 'Итак, это сделано!', 0),
	(13127, 'ruRU', 'С Лордом-магом Уром уже разобрались?', 0),
	(13128, 'ruRU', 'Ты $Gпринес:принесла; новости из Белгаристраша?', 0),
	(13129, 'ruRU', 'Ну что, ткань у тебя?', 0),
	(13130, 'ruRU', 'Ты что, $Gзаблудился:заблудилась;?', 0),
	(13131, 'ruRU', 'Ну, что? Как успехи?', 0),
	(13132, 'ruRU', 'Ты $Gнашел:нашла; того, кто здесь главный, |3-6($R)? Ты $Gзаставил:заставила; их страдать?', 0),
	(13133, 'ruRU', 'Где древний герой?$B$BУ нас нет времени на праздную болтовню. Иди в Залы Предков и разыщи его, пока не поздно!', 0),
	(13134, 'ruRU', 'Все сделано, как я просила?', 0),
	(13135, 'ruRU', 'Ты $Gдобыл:добыла; кристаллизованную энергию?', 0),
	(13136, 'ruRU', 'Это что за мерзость?', 0),
	(13137, 'ruRU', 'Тебе все еще нужно победить древнего героя!', 0),
	(13138, 'ruRU', 'У тебя получилось расплавить куски металла?', 0),
	(13139, 'ruRU', 'Вольно, $N. Докладывай.', 0),
	(13140, 'ruRU', 'Тебе удалось добыть саронитовые пластины?', 0),
	(13142, 'ruRU', 'Верховный тан Балагард все еще жив. Ты что, не $Gнашел:нашла; крепость?', 0),
	(13143, 'ruRU', 'Я уверен, что у новых хозяев им тоже приходится несладко, но эти твари никогда не забудут уроки, которые мы высекли на их шкурах. Они будут бояться этих знаков до скончания веков, пока их род не исчезнет с этой земли.', 0),
	(13144, 'ruRU', 'Ты их уничтожил?', 0),
	(13145, 'ruRU', 'Полет может быть немного более изящным, но мы не сможем подобраться так близко, не будучи обнаруженными.', 0),
	(13146, 'ruRU', 'Они даже не видели, как это происходит?', 0),
	(13147, 'ruRU', 'Предсказуемые хамы.', 0),
	(13152, 'ruRU', 'Ты $Gразвязал:развязала; против него создание доктора?', 0),
	(13159, 'ruRU', 'Это конец? Ты $Gсмог:смогла; выдержать нападение?', 0),
	(13160, 'ruRU', 'Слишком легко.', 0),
	(13162, 'ruRU', 'Мы избавились от нее?', 0),
	(13163, 'ruRU', 'Он умер?', 0),
	(13164, 'ruRU', 'Освободились ли мы наконец от того, чего хочет Артас?', 0),
	(13166, 'ruRU', 'Акерус будет наш!', 0),
	(13167, 'ruRU', 'С ним покончено, |3-6($C)? Король-предатель встретил свой неизбежный конец?', 0),
	(13168, 'ruRU', 'Варианты уловок, доступных нам, очевидны. Это будут очень полезные инструменты.', 0),
	(13169, 'ruRU', 'Не нужно быть расточительным - эти гончие будут служить тем, кто будет их кормить.', 0),
	(13170, 'ruRU', 'Трудно искать то, что не видно.', 0),
	(13171, 'ruRU', '$GУничтожал:Уничтожила; кристаллы? Я не хочу, чтобы они оказались неприятным сюрпризом для моих грифонов.', 0),
	(13172, 'ruRU', 'Повеселись, а?', 0),
	(13174, 'ruRU', 'Ты $Gпринес:принесла;, что я просил?', 0),
	(13178, 'ruRU', 'Ты нашла еще Вечную мерзлоту, невеличка |3-6($R?', 0),
	(13181, 'ruRU', 'Какие новости с полей сражений?', 0),
	(13182, 'ruRU', 'Удалось ли тебе избавить наш дом от яиц?', 0),
	(13183, 'ruRU', 'Надеюсь, ты $Gвернулся:вернулась; с победой?', 0),
	(13185, 'ruRU', 'Ты нашла еще Вечную мерзлоту, невеличка |3-6($R?', 0),
	(13186, 'ruRU', 'Нет времени на болтовню, перейдем сразу к делу: ты $Gуничтожил:уничтожила; их осадные машины?', 0),
	(13187, 'ruRU', 'Ты $Gпобедил:победила; безликих, |3-6($C)?', 0),
	(13188, 'ruRU', 'Говори, ибо сейчас ты умрешь.', 0),
	(13189, 'ruRU', 'Интересный поворот событий!', 0),
	(13190, 'ruRU', 'Удалось ли тебе сжечь труп наблюдателя, $R?', 0),
	(13204, 'ruRU', 'Что это за творение?!', 0),
	(13205, 'ruRU', 'Ты $Gукрал:украла; оружие врайкулов?', 0),
	(13206, 'ruRU', 'Ну, что у тебя там, |3-6($C)?', 0),
	(13207, 'ruRU', 'Ну, теперь оказалось, что это хорошо, что мы столкнулись друг с другом в конце концов.', 0),
	(13211, 'ruRU', 'Ты $Gизбавился:избавилась; от тел убитых солдатами Плети?', 0),
	(13212, 'ruRU', 'Ты $Gпринес:принесла; мне... э... останки рыцаря Олакина?', 0),
	(13220, 'ruRU', 'Ты $Gвоскресил:воскресила; нашего храброго крестоносца?', 0),
	(13222, 'ruRU', 'Нет времени на болтовню, перейдем сразу к делу: ты $Gуничтожил:уничтожила; крепость?', 0),
	(13223, 'ruRU', 'Как продвигается защита осадных машин?', 0),
	(13228, 'ruRU', 'Ну, $N?$B$BУ тебя есть новая информация для меня?', 0),
	(13230, 'ruRU', 'Рад встрече, |3-6($C). Я знал, что ты все равно вернешься, несмотря на мое предупреждение, но ты хотя бы $послушал:послушала; меня и не стала подвергать риску кого-то еще. Что не может не радовать.\n\nПочему ты вернулась ко мне?', 0),
	(13231, 'ruRU', 'Ну, $N?$B$BЧто ты $Gузнал:узнала;?', 0),
	(13232, 'ruRU', 'Что это, $C?', 0),
	(13233, 'ruRU', 'Я верю, что ты $Gзапятнал:запятнала; снег кровью наших врагов, $N.', 0),
	(13234, 'ruRU', 'Итак, |3-6($R)?\n\nКаковы твои выводы?', 0),
	(13235, 'ruRU', 'Ты $Gприкончил:прикончила; великана?', 0),
	(13237, 'ruRU', 'Ну, $R?$B$BЧто ты $Gузнал:узнала;?', 0),
	(13239, 'ruRU', 'Получилось, $C?', 0),
	(13240, 'ruRU', 'Я чувствую ,что тебе ещё предстоит уничтожить все конструкции.', 0),
	(13241, 'ruRU', '<Архимаг прижимает пальцы к вискам и концентрируется.>$B$BБерсерки еще не убиты. Обрати внимание на мое предупреждение, $N. Ты $Gдолжен:должна; сделать это!', 0),
	(13242, 'ruRU', '<Гримаса боли искажает лицо Саурфанга.>\n\nМое сердце…моя сила...', 0),
	(13243, 'ruRU', 'Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.\n\nЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!', 0),
	(13244, 'ruRU', 'Даже я не могу понять, почему мы стоим здесь и говорим, когда тебе еще предстоит устранить угрозу титановых авангардов.', 0),
	(13245, 'ruRU', 'У тебя есть топор? Ингвар мертв?', 0),
	(13246, 'ruRU', 'Если бы нам был известен способ, как исцелить ее, мы бы не просили тебя ее убить.\n\nНо мы знаем, насколько сильна стала власть Малигоса над магией. После его манипуляций с силовыми линиями Азерота он стал непревзойденным мастером тайной магии.', 0),
	(13247, 'ruRU', 'Мне не нужно напоминать тебе, что Малигос пытается остановить использование всей магии в мире и что стая синих драконов убивает любого, кто знает, как им владеть.', 0),
	(13248, 'ruRU', 'Нельзя позволить Имирону повести за собой народ врайкулов. Если он вернется в Ледяную Корону с победой, велика вероятность того, что все будет потеряно.', 0),
	(13249, 'ruRU', 'Повержен ли пророк? С тобой ли у тебя амулет?', 0),
	(13250, 'ruRU', 'У тебя есть моджо?$B$BМне прискорбно наблюдать за гибелью еще одной великой нации троллей.$B$BЯ могу только думать, что если бы не вмешательство Короля-лича, тролли не смогли бы чувствовать вескую необходимость обратиться к своим богам и украсть их...', 0),
	(13251, 'ruRU', 'Мы должны использовать ошибку Мал\'Ганиса. Не каждый день мы получаем такой шанс.\n\nЕсли мы сможем изучить этот артефакт, может быть, мы лучше станем понимать натрезимов!', 0),
	(13252, 'ruRU', 'У тебя есть диск?', 0),
	(13253, 'ruRU', 'Мы снова разговариваем, $N. Означает ли это, что мы в безопасности от безумия Локена или мы всё же обречены?', 0),
	(13254, 'ruRU', 'Я рад, что в Азжол-Неруб спускаешься ты, а не я.$B$BЯ не люблю находиться под землей.', 0),
	(13255, 'ruRU', '$N? Ты все ещё в здравом уме?', 0),
	(13256, 'ruRU', 'Если хорошенько подумать, зачем бы я телепортировался в тюрьму, чтобы потом пытаться из нее выбраться? Это же самое охраняемое здание в городе.\n\nМне кажется, эти синие совсем сошли с ума!', 0),
	(13261, 'ruRU', 'Ну что, |3-6($R), ты поджарила этих змеев?', 0),
	(13268, 'ruRU', 'Ладный пошив твоей одежды подсказывает мне, что ты и $Gсам:сама; $Gспособный:способная; $Gпортной:портная; и без труда усвоишь мой урок.$B$BМногие северяне-гуманоиды носят одежду, которая легко может быть обращена в материал, если знать пару хитростей.$B$BЗа сущие копейки я могу научить тебя, как распарывать их одежду так, чтобы нарезать немного дополнительной ткани.', 0),
	(13273, 'ruRU', 'Ну что, где записи?', 0),
	(13274, 'ruRU', 'Ну что, прав был геолог Сорен? Удалось ли тебе отыскать ядро Норганнона?', 0),
	(13275, 'ruRU', 'Ну что, где кровь?', 0),
	(13280, 'ruRU', 'Погоди секунду... ты ещё не $Gустановил:установила; наш боевой штандарт!$B$BЧего ждешь?', 0),
	(13283, 'ruRU', 'Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.', 0),
	(13284, 'ruRU', 'Вы благополучно достигли Имирхейма?', 0),
	(13287, 'ruRU', 'Ты $Gвернулся:вернулась;, $C...$B$BНе о чем сообщить?', 0),
	(13288, 'ruRU', 'Так, $R?$B$Bтвои поганища оказались эффективными?', 0),
	(13291, 'ruRU', 'Ну как дела, $R?', 0),
	(13292, 'ruRU', 'Да, друг?', 0),
	(13301, 'ruRU', 'Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.', 0),
	(13307, 'ruRU', 'Ты $Gубил:убила; знаменосцев и $Gпресек:присекла; их попытки использовать павших против нас?', 0),
	(13308, 'ruRU', 'Сослужи мне эту службу – и получишь щедрую награду.$B$B<Темный проповедник проецирует в ваше сознание умиротворяющие вибрации покоя.>$B$BОсвободи меня! Даю слово, ты не пожалеешь.', 0),
	(13309, 'ruRU', 'Ты $Gзатащил:затащила; моих мальчиков внутрь?', 0),
	(13310, 'ruRU', 'Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.', 0),
	(13311, 'ruRU', 'Я вижу, что вам удалось собрать колоду Демонов! Поздравляем!', 0),
	(13316, 'ruRU', 'Ты $Gискалечил:искалечила; защитников Корп\'ретара?', 0),
	(13324, 'ruRU', 'Ты $g$gсобрал:собрала;:$gсобрал:собрала;а; все карты Призм! Поздравляю!', 0),
	(13325, 'ruRU', 'Ты $gсобрал:собрала; все карты Хаоса! Поздравляю!', 0),
	(13326, 'ruRU', 'Ты $gсобрал:собрала; все карты Аристократов! Поздравляю!', 0),
	(13327, 'ruRU', 'Ты $gсобрал:собрала; все карты Нежити! Поздравляю!', 0),
	(13330, 'ruRU', 'Ты $Gсделал:сделала; то, о чем я тебя просил?', 0),
	(13334, 'ruRU', 'Ты $Gубрал:убрала; знаменосцев Плети и их приспешников? Хорошо. Наши приготовления должны продолжаться.', 0),
	(13335, 'ruRU', 'Ты $Gпроверил:проверила; решение на риверах?', 0),
	(13343, 'ruRU', '<Хроми странно смотрит на вас.>$B$BЯ знаю вас? Я ощущаю вокруг вас ауру, как если бы само ваше существование изменялось. Либо это, либо вы застряли во временной петле.$B$BКакой бы ни была причина, вам лучше исправить это быстро, иначе вы не просуществуете очень долго!', 0),
	(13345, 'ruRU', 'Ну что, |3-6($R), удалось ли выяснить, чем заняты их ученые?', 0),
	(13347, 'ruRU', '<Король Ринн смахивает слезу.>$B$B<Король Ринн кивает.>$B$BЭто моя вина.', 0),
	(13355, 'ruRU', 'Ну-ка, |3-6($R), что тут у тебя?', 0),
	(13357, 'ruRU', 'Хорошо? Как все вышло?', 0),
	(13366, 'ruRU', 'Ну что, |3-6($R), удалось ли выяснить, чем заняты их ученые?', 0),
	(13367, 'ruRU', 'Ну что, $R? Удалось ли тебе остановить Алумета?', 0),
	(13372, 'ruRU', '$N, ты $Gзавладел:заведала; Ключом от Радужного Средоточия! Он у тебя с собой?$B$B<Королева с тревогой смотрит на своего супруга, Краса.>$B$BКак он к тебе попал? О, это был ключ Сапфирона?', 0),
	(13373, 'ruRU', 'Ты не $Gдостиг:достигла; своей целевой квоты, $N. Бомбардировщиками слишком сложно управлять?', 0),
	(13375, 'ruRU', '$N, ты $Gзавладел:заведала; Ключом от Радужного Средоточия! Он у тебя с собой?$B$B<Королева с тревогой смотрит на своего супруга, Краса.>$B$BКак он к тебе попал? О, это был ключ Сапфирона?', 0),
	(13376, 'ruRU', 'Чего ты ждешь? У нас есть машины и боеприпасы... нам нужны только отважные канониры, чтобы применить их в деле.', 0),
	(13380, 'ruRU', '$N, бомбардировщики сложно использовать, но ты $Gдолжен:должна; справиться с ними, если мы хотим победить в борьбе с Плетью.', 0),
	(13387, 'ruRU', 'За Альянс!', 0),
	(13391, 'ruRU', 'Ну что, где кровь?', 0),
	(13397, 'ruRU', '$N, ты $Gвернулся:вернулась;!', 0),
	(13406, 'ruRU', 'Вы не достигли своей целевой квоты, $N. Выходи и взрывай все!', 0),
	(13407, 'ruRU', 'Ты $Gвернулся:вернулась;! Ты $Gпобедил:победила;, $n?', 0),
	(13408, 'ruRU', '$N, вернись ко мне, когда поможешь захватить каждый из фортов!', 0),
	(13409, 'ruRU', 'Возвращайся, когда все укрепления будут захвачены!', 0),
	(13410, 'ruRU', '$N, вернись ко мне, когда поможешь захватить каждый из фортов!', 0),
	(13411, 'ruRU', 'Возвращайся, когда все укрепления будут захвачены!', 0),
	(13413, 'ruRU', 'Что ты думаешь о моих питомцах, смертный?', 0),
	(13417, 'ruRU', 'Король Грозовое Сердце искренне благодарит за воссоединение с братьями. Похоже, сейчас он собирается свести счеты - возможно, вы снова встретитесь с ним на пороге Артаса.', 0),
	(13422, 'ruRU', 'Привет, $Gбрат:сестра;.', 0),
	(13425, 'ruRU', 'Ты $Gуничтожил:уничтожила; зараженные яйца?', 0),
	(13432, 'ruRU', 'Я знаю, что прошу невозможного, но все равно верю в тебя. Сейчас судьба мира – в твоих руках.', 0),
	(13478, 'ruRU', 'Какие вести из дальних стран?', 0),
	(13538, 'ruRU', 'Какие новости с юга?', 0),
	(13539, 'ruRU', 'Сильнее моего отвращения к чернокнижникам - только отвращение к нежити. Однако иногда они могут пригодиться.', 0),
	(13549, 'ruRU', 'Что случилось?', 0),
	(13556, 'ruRU', 'Кто бы мог подумать, что великому Дубра\'джину будет нужно столько яиц! Интересно, что он будет с ними делать?', 0),
	(13559, 'ruRU', 'Простые подношения не были достойны Ходира, когда он еще обретался среди снежных великанов.$B$BИ пусть с нами его уже нет, мы никогда не оставим традицию подношения даров и всегда будем почитать его силу и мудрость. Ты поддерживаешь наши традиции, и это о многом говорит, крохотный |3-6($C).', 0),
	(13625, 'ruRU', 'Как проходит конная боевая практика?', 0),
	(13627, 'ruRU', 'Вы получили "товар", о котором мы говорили?', 0),
	(13641, 'ruRU', 'Ты уже $Gнашел:нашла; кристалл провидца?', 0),
	(13643, 'ruRU', 'Посещали ли вы могилы убитых?', 0),
	(13654, 'ruRU', 'Тебе удалось узнать что-нибудь об этом странном оруженосце?', 0),
	(13681, 'ruRU', 'Ты достал этот камень?', 0),
	(13790, 'ruRU', 'Ты $gзакончил:закончила; тренироваться вместе с другими чемпионами?', 0),
	(13830, 'ruRU', 'Рыба-призрак преследует вас изо всех сил? $b$b<Марсия выглядит особенно гордой собой за свой каламбур.>', 0),
	(13833, 'ruRU', 'Ну что – удалось поймать хоть одного ужорька? Не забывай – их проще всего приманить на кровь!', 0),
	(13834, 'ruRU', 'Запомни - с террорелями переговоры не ведут!', 0),
	(13836, 'ruRU', 'Приветствую. У вас лишней руки не найдется?', 0),
	(13845, 'ruRU', 'Неужели это – то, о чем я думаю, |3-6($C)?', 0),
	(13846, 'ruRU', 'Ты хочешь сделать пожертвование?', 0),
	(13850, 'ruRU', 'Все еще не застрахован, да? Сдаваться. Это занимает слишком много времени!', 0),
	(13887, 'ruRU', 'Ты нашел яйца?', 0),
	(13904, 'ruRU', 'Детеныш смотрит на тебя.', 0),
	(13906, 'ruRU', 'Ты хорошо заботился о своем ящере?', 0),
	(13915, 'ruRU', 'Равазаврик облизывается и наклоняет голову набок.', 0),
	(13926, 'ruRU', 'Ты позаботишься о нас?', 0),
	(13927, 'ruRU', 'Попечительница сирот говорит Кекек идти с вами.', 0),
	(13929, 'ruRU', 'Мы можем увидеть большое дерево? А мы можем?', 0),
	(13930, 'ruRU', 'Кекек хочет посетить дерево людей-медведей. Мы идем.', 0),
	(13933, 'ruRU', 'Мы посетим храм драконьих тварей?', 0),
	(13934, 'ruRU', 'Кекек хочет посетить святилище драконов.', 0),
	(13937, 'ruRU', 'Мы идем в "Чудо чудное"?', 0),
	(13938, 'ruRU', 'Этот магазин игрушек еще не открылся?', 0),
	(13950, 'ruRU', 'Ты отведёшь меня в Приют Зимних Плавноиков, $N?', 0),
	(13951, 'ruRU', 'Ты отведёшь Кекека на Поляну Снегопада?', 0),
	(13955, 'ruRU', 'Мы сейчас пойдем к королеве драконов?', 0),
	(13956, 'ruRU', 'Вы знаете, как найти Этимидиана? Мы никогда не видели его раньше.', 0),
	(13959, 'ruRU', 'Нам обязательно возвращаться? Мы хотим остаться с тобой.', 0),
	(13960, 'ruRU', 'Кекек не хочет идти. Кекек хочет увидеть больше Нордскола с Джерси.', 0),
	(13986, 'ruRU', 'О! Привет. Я не уверен, что мы раньше встречались, могу ли я что-нибудь для вас сделать?', 0),
	(14017, 'ruRU', 'Тебе удалось выяснить, что они делают с останками Черного рыцаря?', 0),
	(14023, 'ruRU', 'Пряная хлебная запеканка никогда не будет лишней – это одно из самых любимых праздничных блюд.', 0),
	(14024, 'ruRU', 'Тыквенный пирог? Его-то нам и не хватало!', 0),
	(14028, 'ruRU', 'Мне кажется, или я чувствую запах клюквенного соуса?', 0),
	(14030, 'ruRU', 'Ты хочешь поучаствовать в Пиршестве странников?', 0),
	(14033, 'ruRU', '$N, рад снова тебя видеть.', 0),
	(14035, 'ruRU', 'Что привело тебя в Дарнас, $N?', 0),
	(14037, 'ruRU', 'На столах явно недостает пряной хлебной запеканки.', 0),
	(14040, 'ruRU', 'Тыквенному пирогу мы всегда рады.', 0),
	(14041, 'ruRU', 'Как идет празднование Пиршества странников?', 0),
	(14043, 'ruRU', 'А, привет еще раз, $N.', 0),
	(14044, 'ruRU', 'Рад снова видеть тебя, $N.', 0),
	(14047, 'ruRU', 'Что привело тебя в Оргриммар, $N?', 0),
	(14048, 'ruRU', 'Тебе удалось найти индеек?', 0),
	(14061, 'ruRU', 'Как идет охота на индеек?', 0),
	(14076, 'ruRU', 'Тебе удалось добыть яйца йормунгаров? По-моему, эти червяки скоро примутся пожирать своих надсмотрщиков.', 0),
	(14092, 'ruRU', 'Тебе удалось добыть яйца? А то йормунгары уже проявляют недовольство.', 0),
	(14100, 'ruRU', 'Хммм, что заставило тебя обратиться за помощью к Служителям Земли?', 0),
	(14107, 'ruRU', 'Вы принесли мир духам павших героев?', 0),
	(14108, 'ruRU', 'Неужели с кракеном еще не покончено? Поторопись, крестоносец – времени осталось мало!', 0),
	(14111, 'ruRU', 'Духи шевелятся внутри вас. Что заставило вас обратиться за помощью к Служителям Земли?', 0),
	(14112, 'ruRU', 'Надеюсь, ты $Gпринес:принесла; еду для Ледяного Рева – иначе мне придется перевести его на диету из представителей Похитителей Солнца.', 0),
	(14145, 'ruRU', 'Надеюсь, ты $Gпринес:принесла; еду для Ледяного Рева – иначе мне придется перевести его на диету из представителей Серебряного Авангарда.', 0),
	(14160, 'ruRU', 'Добрый день, $N. Что у тебя там?', 0),
	(14163, 'ruRU', 'Рад тебя видеть, $N! У вас есть новости с фронта?', 0),
	(14164, 'ruRU', 'Альянс был изгнан с поля битвы?', 0),
	(14199, 'ruRU', 'Черный Рыцарь появился неожиданно, как предвидел Верховный маг Времиар?', 0),
	(14351, 'ruRU', 'Что принесло $C с поля боя в Подгород?', 0),
	(14352, 'ruRU', 'Чего ты хочешь, $N? Лучше бы это было важно.', 0),
	(14353, 'ruRU', 'Ты $Gнашел:нашла; посла, $N? Он мертв?$B$BМы не можем позволить Плети закрепиться на Калимдоре. Она представляют собой достаточную угрозу для наших границ, чтобы иметь дело с ней на двух фронтах.$B$BЕдинственный оптимистичный знак...', 0),
	(14356, 'ruRU', 'Вы сохранили книги? Их нужно держать подальше от чужих рук.', 0),
	(14409, 'ruRU', 'Кажется, у меня есть время поговорить. По какому поводу это происходит?', 0),
	(24428, 'ruRU', 'Клянусь зубом Ноздорму!', 0),
	(24429, 'ruRU', 'Это еще что значит?', 0),
	(24442, 'ruRU', 'Что ты $Gобнаружил:обнаружила;, $N?', 0),
	(24500, 'ruRU', 'Мы должны передать эту информацию Альянсу! Это вполне может быть ключом к поражению Артаса.', 0),
	(24545, 'ruRU', 'Когда вы приближаетесь, пламя кузницы, кажется, горит еще сильнее.', 0),
	(24629, 'ruRU', 'Эти духи не будут распыляться сами по себе, ты же знаешь.$B$BИдите!', 0),
	(24635, 'ruRU', 'Одеколон не выдаст себя, ты же знаешь.$B$BПолучить распыление!', 0),
	(24636, 'ruRU', 'Знаешь, эти конфеты не будут бросаться на людей.$B$BТебе нужно приниматься за работу!', 0),
	(24803, 'ruRU', 'Калуаки имеют давнюю традицию оттачивать наши навыки рыбалки, проверяя их каждую неделю.$B$BПервый учащийся, который поймает и принесет мне черную акулу, будет щедро вознагражден и будет известен как величайший рыбак севера... хотя бы на пару дней.$B$BЛюбимая еда черноплодной акулы - пигмеев. Попробуйте ловить черную подсказку везде, где вы обычно ловите рыбу.', 0),
	(24806, 'ruRU', 'Боюсь, у нас уже был победитель на сегодня, $Gмолодой:молодая; $N. Однако, если вы принесете акулу, я увижу, что она снова попала в воду, и у меня может быть кое-что для вас...', 0),
	(24857, 'ruRU', 'У тебя озабоченный вид, $N. Какие новости ты $Gпринес:принесла;?', 0),
	(24915, 'ruRU', 'Что это у тебя, |3-6($C)? Во мне пробуждаются чувства, которые, я думал, уже давно мертвы.', 0),
	(24916, 'ruRU', 'Чем я могу помочь тебе, |3-6($C)?', 0),
	(24918, 'ruRU', 'Что это, |3-6($R)?', 0),
	(24919, 'ruRU', 'Чем могу служить, |3-6($R)?', 0),
	(25283, 'ruRU', 'Дай мне знать, какой из них работает, хорошо?', 0),
